INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9228920e-65fb-56b2-a3bb-1b8d3aebeabc', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '4785b2c5-f281-555f-a0f3-fc596c5c6ade', 1, 41, 'ኢየሱስም በመዝገብ አንጻር ተቀምጦ ሕዝቡ በመዝገብ ውስጥ ገንዘብ እንዴት እንዲጥሉ ያይ ነበር፤ ብዙ ባለ ጠጎችም ብዙ ይጥሉ ነበር፤'),
  ('83415fdc-a1c1-5563-aed0-fa1b38fbe1ed', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '4785b2c5-f281-555f-a0f3-fc596c5c6ade', 2, 42, 'አንዲትም ድሀ መበለት መጥታ አንድ ሳንቲም የሚያህሉ ሁለት ናስ ጣለች።'),
  ('39e6678a-a980-5401-ac44-e466d42606f8', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '4785b2c5-f281-555f-a0f3-fc596c5c6ade', 3, 43, 'ደቀ መዛሙርቱንም ጠርቶ “እውነት እላችኋለሁ፤ በመዝገብ ውስጥ ከሚጥሉት ሁሉ ይልቅ ይህች ድሀ መበለት አብልጣ ጣለች፤'),
  ('e35b90b5-342c-5b91-a12a-bdde62d0ef53', '3c3f11bc-3baa-537c-acc5-9a78a0fcc732', '4785b2c5-f281-555f-a0f3-fc596c5c6ade', 4, 44, 'ሁሉ ከትርፋቸው ጥለዋልና፤ ይህች ግን ከጕድለትዋ የነበራትን ሁሉ ትዳርዋን ሁሉ ጣለች፤” አላቸው።'),
  ('5d82f23c-a967-5e1d-ad66-9a08642bba26', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 1, 1, 'እርሱም ከመቅደስ ሲወጣ ከደቀ መዛሙርቱ አንዱ “መምህር ሆይ! እንዴት ያሉ ድንጋይዎችና እንዴት ያሉ ሕንጻዎች እንደ ሆኑ እይ፤” አለው።'),
  ('f3602e52-8ea8-52df-a7b5-d62ca40df32a', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 2, 2, 'ኢየሱስም መልሶ “እነዚህን ታላላቅ ሕንጻዎች ታያለህን? ድንጋይ በድንጋይ ላይ ሳይፈርስ በዚህ አይቀርም፤” አለው።'),
  ('cde5a0b3-082b-5b65-ad48-becf13053ab1', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 3, 3, 'በመቅደስም ትይዩ በደብረ ዘይት ተቀምጦ ሳለ፥ ጴጥሮስና ያዕቆብ ዮሐንስም እንድርያስም'),
  ('39b9c1e8-cb2e-55d6-a463-73b8be49892f', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 4, 4, '“ንገረን፤ ይህ መቼ ይሆናል? ይህስ ሁሉ ይፈጸም ዘንድ እንዳለው ምልክቱ ምንድር ነው?” ብለው ለብቻቸው ጠየቁት።'),
  ('0293f760-f3ac-5ed3-aedc-cee4a91314e2', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 5, 5, 'ኢየሱስም መልሶ እንዲህ ይላቸው ጀመር “ማንም እንዳያስታችሁ ተጠንቀቁ።'),
  ('f15fc1e4-4ec3-5db1-a764-9606b917a836', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 6, 6, 'ብዙዎች ‘እኔ ነኝ፤’ እያሉ በስሜ ይመጣሉና፤ ብዙዎችንም ያስታሉ።'),
  ('94fde95c-1c82-5eb0-a693-68bd0ff71634', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 7, 7, 'ጦርንም የጦርንም ወሬ በሰማችሁ ጊዜ አትደንግጡ፤ ይህ ሊሆን ግድ ነውና፤ ነገር ግን መጨረሻው ገና ነው።'),
  ('89cbd88e-740f-5866-a623-695104fb9f69', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 8, 8, 'ሕዝብ በሕዝብ ላይ መንግሥትም በመንግሥት ላይ ይነሣልና፤ በልዩ ልዩ ስፍራ የምድር መናወጥ ይሆናል፤ ራብ ይሆናል፤ እነዚህ የምጥ ጣር መጀመሪያ ናቸው።'),
  ('513ca196-ee32-5e75-a36c-0c4c8aad6fd2', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 9, 9, '“እናንተ ግን ለራሳችሁ ተጠንቀቁ፤ ወደ ሸንጎ አሳልፈው ይሰጡአችኋል፤ በምኵራብም ትገረፋላችሁ፤ ምስክርም ይሆንባቸው ዘንድ ስለ እኔ በገዥዎችና በነገሥታት ፊት ትቆማላችሁ።'),
  ('60993d72-5a30-54cc-a88b-1a2c48f7db62', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 10, 10, 'አስቀድሞም ወንጌል ለአሕዛብ ሁሉ ይሰበክ ዘንድ ይገባል።'),
  ('4bd1df85-94a9-53e2-a275-bce6cd3f22a6', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 11, 11, 'ሲጐትቱአችሁና አሳልፈው ሲሰጡአችሁም ምን እንድትናገሩ አስቀድማችሁ አትጨነቁ፤ ዳሩ ግን በዚያች ሰዓት የሚሰጣችሁን ተናገሩ፤ የሚነግረው መንፈስ ቅዱስ ነው እንጂ እናንተ አይደላችሁምና።'),
  ('04b57429-a7e8-53e0-afbc-3e558e414f7f', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 12, 12, 'ወንድምም ወንድሙን አባትም ልጁን ለሞት አሳልፎ ይሰጣል፤ ልጆችም በወላጆቻቸው ላይ ይነሣሉ፤ ይገድሉአቸውማል።'),
  ('2cfe889c-a088-5690-a7ae-e7c0a42001e7', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 13, 13, 'በሁሉም ዘንድ ስለ ስሜ የተጠላችሁ ትሆናላችሁ፤ እስከ መጨረሻ የሚጸና ግን እርሱ ይድናል።'),
  ('4174f2b2-c2d6-52a9-a3ed-e402dab2e418', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 14, 14, '“ነገር ግን በነቢዩ በዳንኤል የተባለውን የጥፋት ርኵሰት በማይገባው ስፍራ ቆሞ ብታዩ፥ አንባቢው ያስተውል፤ በዚያን ጊዜ በይሁዳ ያሉ ወደ ተራሮች ይሽሹ፤'),
  ('c10f7d34-62ad-5582-afd8-b09e033bbc65', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 15, 15, 'በሰገነትም ያለ ወደ ቤት አይውረድ፤ ከቤቱም አንዳች ይወስድ ዘንድ አይግባ፤'),
  ('f6663d0b-1e00-50ae-a082-a3a4cdc74468', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 16, 16, 'በእርሻም ያለ ልብሱን ይወስድ ዘንድ ወደ ኋላው አይመለስ።'),
  ('ab34882f-2b74-5d70-a503-be10be611570', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 17, 17, 'በዚያን ወራትም ለርጉዞችና ለሚያጠቡ ወዮላቸው።'),
  ('dc770227-ad54-5780-a34c-038c17f81840', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 18, 18, 'ነገር ግን ሽሽታችሁ በክረምት እንዳይሆን ጸልዩ፤'),
  ('9aedddb2-43f1-5913-ae55-703708a49537', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 19, 19, 'በዚያን ወራት እግዚአብሔር ከፈጠረው ከፍጥረት መጀመሪያ ጀምሮ እስከ አሁን ድረስ ያልሆነ ደግሞም የማይሆን የመከራ ዐይነት ይሆናልና።'),
  ('f00eece8-fbe3-5e2c-a6d3-e17cce9c395a', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 20, 20, 'ጌታስ ወራቶቹን ባያሳጥር፥ ሥጋ የለበሰ ሁሉ ባልዳነም፤ ነገር ግን ስለ መረጣቸው ምርጦች ወራቶቹን አሳጠረ።'),
  ('dc438ebc-932a-5612-a214-6ad7dc629b69', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 21, 21, 'በዚያን ጊዜም ማንም ‘እነሆ፥ ክርስቶስ ከዚህ አለ፤’ ወይም ‘እነሆ፥ ከዚያ አለ፤’ ቢላችሁ አትመኑ፤'),
  ('26d717c7-1850-5911-a0fe-930b0b9f848d', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 22, 22, 'ሐሰተኞች ክርስቶሶችና ሐሰተኞች ነቢያት ይነሣሉና፤ ቢቻላቸውስ የተመረጡትን እንኳ ያስቱ ዘንድ ምልክትና ድንቅ ያደርጋሉ።'),
  ('439254d1-1890-5f66-a96a-048ed4d51d95', '079b958b-c7a5-5190-a197-6104f9a24a86', 'a054feb0-aa7d-5914-aaf3-68f68ba14242', 23, 23, 'እናንተ ግን ተጠንቀቁ፤ እነሆ፥ አስቀድሜ ሁሉን ነገርኋችሁ።'),
  ('9a773f8c-f644-57cb-afea-df69ab0cd4cf', '079b958b-c7a5-5190-a197-6104f9a24a86', '07891501-4e01-5b9f-afcf-bdad735cfae5', 1, 24, '“በነዚያ ቀኖች ግን ከዚያ መከራ በኋላ ፀሐይ ይጨልማል፤ ጨረቃም ብርሃንዋን አትሰጥም፤'),
  ('af29b30e-afae-5041-abc2-dee0ac04c198', '079b958b-c7a5-5190-a197-6104f9a24a86', '07891501-4e01-5b9f-afcf-bdad735cfae5', 2, 25, 'ከዋክብትም ከሰማይ ይወድቃሉ፤ የሰማያትም ኀይላት ይናወጣሉ።'),
  ('5da7c888-1ecc-56ae-acd6-9e724e3e7441', '079b958b-c7a5-5190-a197-6104f9a24a86', '07891501-4e01-5b9f-afcf-bdad735cfae5', 3, 26, 'በዚያን ጊዜም የሰው ልጅ በብዙ ኀይልና ክብር በደመና ሲመጣ ያዩታል።'),
  ('df849afd-9692-5ad5-a258-3f0a4cfde0c4', '079b958b-c7a5-5190-a197-6104f9a24a86', '07891501-4e01-5b9f-afcf-bdad735cfae5', 4, 27, 'በዚያን ጊዜም መላእክትን ይልካል፤ ከአራቱ ነፋሳትም ከምድር ዳርቻ እስከ ሰማይ ዳርቻ የተመረጡትን ይሰበስባቸዋል።'),
  ('36e530a6-073e-5a38-afff-c68541dd3d42', '079b958b-c7a5-5190-a197-6104f9a24a86', 'f972a1f3-bbe2-5eb2-aaff-8f25720ca814', 1, 28, '“ምሳሌውንም ከበለስ ተማሩ፤ ጫፍዋ ሲለሰልስ ቅጠልዋም ሲያቈጠቍጥ፥ ያን ጊዜ በጋ እንደ ቀረበ ታውቃላችሁ።'),
  ('510e19a2-9808-535e-a23e-af90d1ab1d7f', '079b958b-c7a5-5190-a197-6104f9a24a86', 'f972a1f3-bbe2-5eb2-aaff-8f25720ca814', 2, 29, 'እንዲሁ ደግሞ እናንተ ይህን ሁሉ መሆኑን ስታዩ ቀርቦ በደጅ እንደ ሆነ እወቁ።'),
  ('dca47e0d-c7cf-5a8c-a799-8e0b17b2790c', '079b958b-c7a5-5190-a197-6104f9a24a86', 'f972a1f3-bbe2-5eb2-aaff-8f25720ca814', 3, 30, 'እውነት እላችኋለሁ፤ ይህ ሁሉ እስኪሆን ድረስ ይህ ትውልድ አያልፍም።'),
  ('720d753a-c235-5b0b-a0c0-e36a82a627b6', '079b958b-c7a5-5190-a197-6104f9a24a86', 'f972a1f3-bbe2-5eb2-aaff-8f25720ca814', 4, 31, 'ሰማይና ምድር ያልፋሉ፤ ቃሌ ግን አያልፍም።'),
  ('f1941572-48f3-51f2-a01d-82c2ff6d6795', '079b958b-c7a5-5190-a197-6104f9a24a86', 'bc571bd7-5222-5fa4-a122-d28e76e8c9f4', 1, 32, '“ስለዚያች ቀን ወይም ስለዚያች ሰዓት ግን የሰማይ መላእክትም ቢሆኑ ልጅም ቢሆን ከአባት በቀር የሚያውቅ የለም።'),
  ('ae80072b-5a23-5571-a4b1-099bda290c67', '079b958b-c7a5-5190-a197-6104f9a24a86', 'bc571bd7-5222-5fa4-a122-d28e76e8c9f4', 2, 33, 'ጊዜው መቼ እንዲሆን አታውቁምና ተጠንቀቁ፤ ትጉ፤ ጸልዩም።'),
  ('b0b1a8e4-a583-5c28-aaab-e77d02b25671', '079b958b-c7a5-5190-a197-6104f9a24a86', 'bc571bd7-5222-5fa4-a122-d28e76e8c9f4', 3, 34, 'ቤቱን ትቶ ወደ ሌላ አገር እንደ ሄደ ሰው ነው፤ ለባሮቹም ሥልጣን ለእያንዳንዱም ሥራውን ሰጥቶ በረኛውን እንዲተጋ አዘዘ።'),
  ('76763412-0bae-5ed7-a77b-f2f3a21cc4e3', '079b958b-c7a5-5190-a197-6104f9a24a86', 'bc571bd7-5222-5fa4-a122-d28e76e8c9f4', 4, 35, 'እንግዲህ በማታ ቢሆን ወይም በእኩለ ሌሊት ወይም ዶሮ ሲጮኽ ወይም በማለዳ ቢሆን ባለቤቱ መቼ እንዲመጣ አታውቁምና'),
  ('7322e29c-2f56-52b7-ac66-e890a9efa712', '079b958b-c7a5-5190-a197-6104f9a24a86', 'bc571bd7-5222-5fa4-a122-d28e76e8c9f4', 5, 36, 'ድንገት መጥቶ ተኝታችሁ እንዳያገኛችሁ ስለዚህ ትጉ።'),
  ('b9090516-1055-5ad8-a7f6-d7d67d718dc1', '079b958b-c7a5-5190-a197-6104f9a24a86', 'bc571bd7-5222-5fa4-a122-d28e76e8c9f4', 6, 37, 'ለእናንተም የምነግራችሁ ለሁሉ እላለሁ፤ ትጉ።”'),
  ('ce6e0b40-893d-504a-aef1-799e8bee6116', '50d72c6c-a862-5a13-a663-cf6499435a55', '49f55b10-6382-5074-a2cb-94ab68d1ea95', 1, 1, 'ከሁለት ቀን በኋላ ፋሲካና የቂጣ በዓል ነበረ። የካህናት አለቆችም ጻፎችም እንዴት አድርገው በተንኰል እንደሚይዙትና እንደሚገድሉት ይፈልጉ ነበር።'),
  ('6b3caf6e-57ca-5e51-a8b6-48ea9cef7201', '50d72c6c-a862-5a13-a663-cf6499435a55', '49f55b10-6382-5074-a2cb-94ab68d1ea95', 2, 2, '“የሕዝብ ሁከት እንዳይሆን በበዓል አይሁን፤” ይሉ ነበርና።'),
  ('a5eabdb1-ede3-5705-a509-be64a5475311', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 1, 3, 'እርሱም በቢታንያ በለምጻሙ በስምዖን ቤት በነበረ ጊዜ፥ በማዕድ ተቀምጦ ሳለ፥ አንዲት ሴት ዋጋው እጅግ የከበረ ጥሩ የናርዶስ ሽቶ የሞላበት የአልባስጥሮስ ብልቃጥ ይዛ መጣች፤ ብልቃጡንም ሰብራ በራሱ ላይ አፈሰሰችው።'),
  ('4a619a5d-8480-53c6-aa8e-9d511d7a305d', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 2, 4, 'አንዳንዶችም “ይህ የሽቶ ጥፋት ለምንድር ነው?'),
  ('a5e099ce-365d-5712-a2bf-90eae08a65aa', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 3, 5, 'ይህ ሽቶ ከሦስት መቶ ዲናር በሚበልጥ ዋጋ ተሽጦ ለድሆች ሊሰጥ ይቻል ነበርና፤” ብለው በራሳቸው ይቈጡ ነበር፤ እርስዋንም ነቀፉአት።'),
  ('ed557821-bc07-53ea-a655-8a61fac56b09', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 4, 6, 'ኢየሱስ ግን እንዲህ አለ “ተዉአት፤ ስለ ምን ታደክሙአታላችሁ? መልካም ሥራ ሠርታልኛለች።'),
  ('4ba4c90e-485b-586c-ae1b-15bb00fbc1e2', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 5, 7, 'ድሆች ሁልጊዜ ከእናንተ ጋር ይኖራሉና፤ በማናቸውም በወደዳችሁት ጊዜ መልካም ልታደርጉላቸው ትችላላችሁ፤ እኔ ግን ሁልጊዜ ከእናንተ ጋር አልኖርም።'),
  ('73d7d463-6000-5874-a0d1-caf4f00ccd10', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 6, 8, 'የተቻላትን አደረገች፤ አስቀድማ ለመቃብሬ ሥጋዬን ቀባችው።'),
  ('31b3713b-97ea-585d-a97b-02b804700594', '50d72c6c-a862-5a13-a663-cf6499435a55', '4b6e41bf-4241-5fe2-ae72-c875c979bdcd', 7, 9, 'እውነት እላችኋለሁ፤ ይህ ወንጌል በዓለሙ ሁሉ በሚሰበክበት በማናቸውም ስፍራ፥ እርስዋ ያደረገችው ደግሞ ለእርስዋ መታሰቢያ ሊሆን ይነገራል።”'),
  ('2dab1ca0-b953-5748-a54e-b30facad669c', '50d72c6c-a862-5a13-a663-cf6499435a55', '45a420a9-f200-5816-acdd-62f928014e97', 1, 10, 'ከዐሥራ ሁለቱም አንዱ የአስቆሮቱ ይሁዳ አሳልፎ ሊሰጠው ወደ ካህናት አለቆች ሄደ።'),
  ('944d587e-a2f0-55a8-a4b9-12bb6551c4a2', '50d72c6c-a862-5a13-a663-cf6499435a55', '45a420a9-f200-5816-acdd-62f928014e97', 2, 11, 'ሲሰሙም ደስ አላቸው፤ ብርም ይሰጡት ዘንድ ተስፋ ሰጡት። በሚመች ጊዜም እንዴት አድርጎ አሳልፎ እንዲሰጠው ይፈልግ ነበር።'),
  ('069d9cf1-06cb-5a6b-adeb-aef2bf6fc078', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 1, 12, 'የፋሲካን በግ በሚያርዱበት በቂጣ በዓል መጀመሪያ ቀን ደቀ መዛሙርቱ “ፋሲካን ትበላ ዘንድ ወዴት ሄደን ልናሰናዳ ትወዳለህ?” አሉት።'),
  ('351a08f4-cffc-592f-a8c4-644267594ed2', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 2, 13, 'ከደቀ መዛሙርቱም ሁለት ላከ፤ እንዲህም አላቸው “ወደ ከተማ ሂዱ፤ ማድጋ ውኀ የተሸከመ ሰውም ይገናኛችኋል፤ተከተሉት።'),
  ('4133404f-3266-5860-ace4-faabe5a1beaa', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 3, 14, 'የሚገባበትንም የቤቱን ጌታ ‘መምህሩ ከደቀ መዛሙርቴ ጋር ፋሲካን የምበላበት የእንግዳ ቤት ወዴት ነው? ይላል፤’ በሉት።'),
  ('645d426c-1a46-5e67-a29a-00f0e1184cbf', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 4, 15, 'እርሱም በደርብ ላይ ያለውን የተሰናዳና የተነጠፈ ታላቅ አዳራሽ ያሳያችኋል፤በዚያም አሰናዱልን።”'),
  ('7b11ce03-1e81-5be0-af46-cbed868bf70d', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 5, 16, 'ደቀ መዛሙርቱም ወጡ፤ ወደከተማም ሄደው እንዳላቸው አገኙ፤ ፋሲካንም አሰናዱ።'),
  ('b221a974-3eff-55d7-a613-0a62ce33506d', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 6, 17, 'በመሸም ጊዜ ከዐሥራ ሁለቱ ጋር መጣ።'),
  ('075c45de-e276-5678-a14a-770c69cf5619', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 7, 18, 'ተቀምጠውም ሲበሉ ኢየሱስ “እውነት እላችኋለሁ፥ ከእናንተ አንዱ፥ እርሱም ከእኔ ጋር የሚበላው አሳልፎ ይሰጠኛል፤” አለ።'),
  ('cbdc729f-da59-52a4-a4f9-de1afc682033', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 8, 19, 'እነርሱም ያዝኑ፥ እያንዳንዳቸውም “እኔ እሆንን?” ይሉት ጀመር።'),
  ('5fe7937a-627f-5160-a942-66de231516a0', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 9, 20, 'እርሱም መልሶ “ከዐሥራ ሁለቱ አንዱ ከእኔ ጋር ወደ ወጭቱ እጁን የሚያጠልቀው ነው።'),
  ('98cc1bb8-7219-5b02-a246-73edc9a69827', '50d72c6c-a862-5a13-a663-cf6499435a55', '343da7fe-8cbe-56f9-ac3a-9db667b9ef7f', 10, 21, 'የሰው ልጅስ ስለ እርሱ እንደ ተጻፈ ይሄዳል፤ ነገር ግን የሰው ልጅ አልፎ ለሚሰጥበት ለዚያ ሰው ወዮለት! ያ ሰው ባልተወለደ ይሻለው ነበር፤” አላቸው።'),
  ('8657c1b1-dd18-50d0-a7b5-1e5c8a86f2c4', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b97369ea-db0e-5017-a027-73b8143121f7', 1, 22, 'ሲበሉም ኢየሱስ ኅብስትን አንሥቶ ባረከ፤ ቈርሶም ሰጣቸውና “እንካችሁ፤ ይህ ሥጋዬ ነው፤” አለ።'),
  ('7d0d9151-ccdc-5e76-a1e5-8331e535d9e6', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b97369ea-db0e-5017-a027-73b8143121f7', 2, 23, 'ጽዋንም አንሥቶ አመስግኖም ሰጣቸው፤ ሁሉም ከእርሱ ጠጡ።'),
  ('d108c67e-218e-5c56-a6c2-33f56cbe7084', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b97369ea-db0e-5017-a027-73b8143121f7', 3, 24, 'እርሱም “ይህ ስለ ብዙዎች የሚፈስ የአዲስ ኪዳን ደሜ ነው።'),
  ('4d4f44b3-d9e4-54e5-aee0-9ce1dbe9ca64', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b97369ea-db0e-5017-a027-73b8143121f7', 4, 25, 'እውነት እላችኋለሁ በእግዚአብሔር መንግሥት ከወይኑ ፍሬ አዲሱን እስከምጠጣበት እስከዚያ ቀን ድረስ ደግሞ አልጠጣውም፤” አላቸው።'),
  ('4902d3fa-27d5-5623-af17-4ef4d0f7849c', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b97369ea-db0e-5017-a027-73b8143121f7', 5, 26, 'መዝሙርም ከዘመሩ በኋላ ወደ ደብረ ዘይት ወጡ።'),
  ('1f0733ac-ab43-5a3d-a598-9501e79a6b94', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e47b8532-9412-5fe7-a701-c5b11650f13e', 1, 27, 'ኢየሱስም “በዚች ሌሊት ሁላችሁ በእኔ ትሰናከላላችሁ፤ ‘እረኛዉን እመታለሁ፤ በጎችም ይበተናሉ፤’ የሚል ተጽፎአልና።'),
  ('85dcf6cb-56c7-587f-ad92-542fc36733b8', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e47b8532-9412-5fe7-a701-c5b11650f13e', 2, 28, 'ነገር ግን ከተነሣሁ በኋላ ወደ ገሊላ እቀድማችኋለሁ፤” አላቸው።'),
  ('b31711e5-4a71-5a7c-ae3e-f34a64a2ea40', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e47b8532-9412-5fe7-a701-c5b11650f13e', 3, 29, 'ጴጥሮስም “ሁሉም ቢሰናከሉ እኔ ግን ከቶ አልሰናከልም፤” አለው።'),
  ('1eecb468-b99c-54d4-acf3-c30384a42d2c', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e47b8532-9412-5fe7-a701-c5b11650f13e', 4, 30, 'ኢየሱስም “እውነት እልሃለሁ፤ ዛሬ በዚች ሌሊት ዶሮ ሁለት ጊዜ ሳይጮኽ ሦስት ጊዜ ትክደኛለህ፤” አለው።'),
  ('0adc9bf0-d57c-5742-a4da-961d0271cc99', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e47b8532-9412-5fe7-a701-c5b11650f13e', 5, 31, 'እርሱም ቃሉን አበርትቶ “ከአንተ ጋር የምሞት እንኳ ቢሆን ከቶ አልክድህም፤” አለ። ሁሉም ደግሞ እንደዚሁ አሉ።'),
  ('9eb6adbe-a82a-5640-a938-a0d506322f10', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 1, 32, 'ጌቴሴማኒ ወደምትባልም ስፍራ መጡ፤ ደቀ መዛሙርቱንም “ስጸልይ ሳለሁ፥ በዚህ ተቀመጡ፤” አላቸው።'),
  ('5cd39da4-4dd1-5e0d-abf8-aa381016f627', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 2, 33, 'ጴጥሮስንና ያዕቆብን ዮሐንስንም ከእርሱ ጋር ወሰደ፤ ሊደነግጥም ሊተክዝም ጀመረና'),
  ('ae9a528b-194d-5211-a1f6-f2f016aff5a3', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 3, 34, '“ነፍሴ እስከ ሞት ድረስ እጅግ አዘነች፤ በዚህ ቈዩ፤ ትጉም፤” አላቸው።'),
  ('769f551e-e7fe-5e0a-a54c-d972edd48285', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 4, 35, 'ጥቂትም ወደ ፊት እልፍ ብሎ በምድርም ወድቆ፥ ይቻልስ ቢሆን ሰዓቲቱ ከእርሱ እንድታልፍ ጸለየና'),
  ('b09ff358-ec44-51ae-a5e8-f92a390bdcbc', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 5, 36, '“አባ አባት ሆይ! ሁሉ ይቻልሃል፤ ይህችን ጽዋ ከእኔ ውሰድ፤ ነገር ግን አንተ የምትወደው እንጂ እኔ የምወደው አይሁን፤” አለ።'),
  ('efbcd11f-7072-58d8-a83e-b29e765843a4', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 6, 37, 'መጣም፤ ተኝተውም አገኛቸው፤ ጴጥሮስንም “ስምዖን ሆይ! ተኝተሃልን? አንዲት ሰዓት ስንኳ ልትተጋ አልቻልህምን?'),
  ('a2a7fa4e-539d-5e8a-a74e-e8f9209c5c14', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 7, 38, 'ወደ ፈተና እንዳትገቡ ትጉ፤ ጸልዩም፤ መንፈስስ ተዘጋጅታለች፤ ሥጋ ግን ደካማ ነው፤” አለው።'),
  ('4fdf2746-d888-5e6e-a7e5-971111c3f359', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 8, 39, 'ደግሞም ሄዶ ያንኑ ቃል ጸለየ።'),
  ('2f1eb9aa-2554-5bb9-a3ba-b44f0116a564', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 9, 40, 'ደግሞም መጥቶ ዐይኖቻቸው በእንቅልፍ ከብደው ነበርና ተኝተው አገኛቸው፤ የሚመልሱለትንም አላወቁም።'),
  ('1a94ef37-8682-5af8-a1d1-2c0f1da73811', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 10, 41, 'ሦስተኛም መጥቶ “እንግዲህስ ተኙ፤ ዕረፉም፤ ይበቃል፤ ሰዓቲቱ ደረሰች፤ እነሆ፥ የሰው ልጅ በኀጢአተኞች እጅ አልፎ ይሰጣል።'),
  ('6d23dd90-beb7-59fe-a94a-ba11ab3304da', '50d72c6c-a862-5a13-a663-cf6499435a55', 'd3cce3e0-7661-569f-ab6f-7cc8190784db', 11, 42, 'ተነሡ፤ እንሂድ፤ እነሆ፥ አሳልፎ የሚሰጠኝ ቀርቦአል፤” አላቸው።'),
  ('091a10fc-1199-553b-a28c-28fae1013a9b', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 1, 43, 'ወዲያውም ገና ሲናገር ከዐሥራ ሁለቱ አንዱ ይሁዳ መጣ፤ ከእርሱም ጋር ብዙ ሰዎች ሰይፍና ጐመድ ይዘው ከካህናት አለቆችና ከጻፎች ከሽማግሌዎችም ዘንድ መጡ።'),
  ('d13639c8-bc32-5106-aba7-6f2fc24c406b', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 2, 44, 'አሳልፎ የሚሰጠውም “የምስመው እርሱ ነው፤ ያዙት፤ ተጠንቅቃችሁም ውሰዱት፤” ብሎ ምልክት ሰጥቶአቸው ነበር።'),
  ('b9231462-dd46-5028-aa54-3b24dabde6a8', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 3, 45, 'መጥቶም ወዲያው ወደ እርሱ ቀረበና “መምህር ሆይ! መምህር ሆይ!” ብሎ ሳመው፤'),
  ('a1e794ed-9468-5703-a33f-f0ae94948ed1', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 4, 46, 'እነርሱም እጃቸውን በእርሱ ላይ ጭነው ያዙት።'),
  ('4a20e7ad-7a9e-54d4-ad83-e65520221bb9', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 5, 47, 'በአጠገብ ከቆሙት ግን አንዱ ሰይፉን መዞ የሊቀ ካህናቱን ባሪያ መታ፤ ጆሮውንም ቈረጠ።'),
  ('fdeca02d-b0d9-54be-afac-3cb6405976bb', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 6, 48, 'ኢየሱስም መልሶ “ወንበዴ እንደምትይዙ ሰይፍና ጐመድ ይዛችሁ ልትይዙኝ መጣችሁን?'),
  ('7a904217-99d1-589a-ad9b-dee1634b2265', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 7, 49, 'በመቅደስ ዕለት ዕለት እያስተማርሁ ከእናንተ ጋር ስኖር አልያዛችሁኝም፤ ነገር ግን መጻሕፍት ይፈጸሙ ዘንድ ይህ ሆነ፤” አላቸው።'),
  ('fd89ba9c-f4e8-5a7a-a264-b98edc7b4fc0', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 8, 50, 'ሁሉም ትተውት ሸሹ።'),
  ('40da5b29-3b7a-5776-a17f-dc3ff87fa4fe', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 9, 51, 'ዕርቃኑን በነጠላ የሸፈነ አንድ ጎበዝ ይከተለው ነበር፤'),
  ('bb114630-ec45-5f11-a698-4063f4540c64', '50d72c6c-a862-5a13-a663-cf6499435a55', 'b4f0fd7b-96b0-57de-a634-bd067c4ff732', 10, 52, 'ጎበዛዝቱም ያዙት፤ እርሱ ግን ነጠላውን ትቶ ዕራቁቱን ሸሸ።'),
  ('94f4733f-a23f-5f63-a5f0-4063d3cf7152', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 1, 53, 'ኢየሱስንም ወደ ሊቀ ካህናቱ ወሰዱት፤ የካህናት አለቆችም ሁሉ ሽማግሌዎችም ጻፎችም ተሰበሰቡ።'),
  ('25cd68dd-e898-5508-ad47-9e1d8f5b6b9a', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 2, 54, 'ጴጥሮስም እስከ ሊቀ ካህናቱ ግቢ ውስጥ በሩቁ ተከተለው፤ ከሎሌዎችም ጋር ተቀምጦ እሳት ይሞቅ ነበር።'),
  ('71666d3f-dd20-5196-a045-d171c0d2d246', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 3, 55, 'የካህናት አለቆችም ሸንጎውን ሁሉ እንዲገድሉት በኢየሱስ ላይ ምስክር ይፈልጉ ነበር፤ አላገኙምም፤'),
  ('5327bd42-63dd-5c14-a263-10deeb6a7e2f', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 4, 56, 'ብዙዎች በሐሰት ይመሰክሩበት ነበርና፤ ምስክርነታቸው ግን አልተስማማም።'),
  ('883aef5d-53cb-5e1e-acb8-20f14b040c65', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 5, 57, 'ሰዎችም ተነሥተው “እኔ ይህን በእጅ የተሠራውን ቤተ መቅደስ አፈርሰዋለሁ፤ በሦስት ቀንም ሌላውን በእጅ ያልተሠራውን እሠራለሁ፤” ሲል ሰማነው፤ ብለው በሐሰት መሰከሩበት።'),
  ('362e165c-bad6-565b-ae94-6e8f82dcc7c6', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 6, 59, 'ምስክርነታቸውም እንዲሁ እንኳ አልተስማማም።'),
  ('ccecf4fa-b7d9-5242-ad9b-8b7a266119e8', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 7, 60, 'ሊቀ ካህናቱም በመካከላቸው ተነሥቶ “አንዳች አትመልስምን? እነዚህስ በአንተ ላይ የሚመሰክሩብህ ምንድር ነው?” ብሎ ኢየሱስን ጠየቀው።'),
  ('62845433-b78c-5488-ad28-c2e4e3112784', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 8, 61, 'እርሱ ግን ዝም አለ፤ አንዳችም አልመለሰም። ደግሞ ሊቀ ካህናቱ ጠየቀውና “የቡሩክ ልጅ ክርስቶስ አንተ ነህን?” አለው።'),
  ('89ae5365-e4e8-59ed-af21-245771779671', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 9, 62, 'ኢየሱስም “እኔ ነኝ፤ የሰው ልጅም በኀይል ቀኝ ሲቀመጥ በሰማይም ደመና ሲመጣ ታያላችሁ፤” አለ።'),
  ('4d78771e-7bf6-533b-ac69-45169c49629d', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 10, 63, 'ሊቀ ካህናቱም ልብሱን ቀደደና “ከእንግዲህ ወዲህ ምስክሮችን ምን ያስፈልገናል?'),
  ('9f50ee25-ae9b-5e02-a1b0-3b45fc0b75e5', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 11, 64, 'ስድቡን ሰማችሁ፤ ምን ይመስላችኋል?” አለ። እነርሱም ሁሉ “ሞት ይገባዋል!” ብለው ፈረዱበት።'),
  ('5e0141b7-dccb-540d-ab93-d1a2d83bafa0', '50d72c6c-a862-5a13-a663-cf6499435a55', '7e007477-b23a-5f26-a4dd-4b498c85a8d2', 12, 65, 'አንዳንዶችም ይተፉበት ፊቱንም ሸፍነው ይጐስሙትና “ትንቢት ተናገር፤” ይሉት ጀመር፤ ሎሌዎችም በጥፊ እየመቱ ወሰዱት።'),
  ('7b3ff6f7-986a-5b79-abb3-57d07dc8216b', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 1, 66, 'ጴጥሮስም በግቢ ውስጥ ወደ ታች ሳለ ከሊቀ ካህናቱ ገረዶች አንዲቱ መጣች፤'),
  ('8d7b2133-1a13-5180-a41c-111c72f4ba91', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 2, 67, 'ጴጥሮስም እሳት ሲሞቅ አይታ ተመለከተችውና “አንተ ደግሞ ከናዝሬቱ ከኢየሱስ ጋር ነበርህ፤” አለችው።'),
  ('89e9dd07-3196-50a4-a41e-307904abd594', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 3, 68, 'እርሱ ግን “የምትዪውን አላውቅም፤ አላስተውልምም፤” ብሎ ካደ። ወደ ውጭም ወደ ደጅ ወጣ፤ ዶሮም ጮኸ።'),
  ('dc86ed55-7235-5fa0-a76e-8507628709ac', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 4, 69, 'ገረዲቱም አይታው በዚያ ለቆሙት “ይህም ከእነርሱ ወገን ነው፤” ስትል ሁለተኛ ትነግራቸው ጀመር።'),
  ('a84bd524-6c19-5db9-abd9-936fed9206d0', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 5, 70, 'እርሱም ደግሞ ካደ። ጥቂት ቈይተውም በዚያ የቆሙት ዳግመኛ ጴጥሮስን “የገሊላ ሰው ነህና ከእነርሱ ወገን በእውነት ነህ፤” አሉት።'),
  ('e3f061fb-d84e-5b06-a24c-e855dc5243db', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 6, 71, 'እርሱ ግን “ይህን የምትሉትን ሰው አላውቀውም፤” ብሎ እራሱን ይረግምና ይምል ጀመር። ወዲያውም ዶሮ ሁለተኛ ጮኸ።'),
  ('e1a25203-5b7d-51fe-a0c3-ea6c4767491b', '50d72c6c-a862-5a13-a663-cf6499435a55', 'e747c69c-889f-5c65-a77a-804c3a1e0b0d', 7, 72, 'ጴጥሮስንም ኢየሱስ “ዶሮ ሁለት ጊዜ ሳይጮኽ ሦስት ጊዜ ትክደኛለህ፤” ያለው ቃል ትዝ አለው፤ ነገሩንም አስቦ አለቀሰ።'),
  ('b7072843-1979-59e0-ab87-88b0df0d74a0', '1c412fad-67a4-5071-a11b-ebd8672f9590', '3a399067-d71a-5d86-a71f-0f434978fb5c', 1, 1, 'ወዲያውም ማለዳ የካህናት አለቆች ከሽማግሌዎችና ከጻፎች ከሸንጎውም ሁሉ ጋር ከተማከሩ በኋላ፥ ኢየሱስን አሳስረው ወሰዱትና ለጲላጦስ አሳልፈው ሰጡት።'),
  ('98beae7b-9a80-5328-acc4-a2f5f4c02153', '1c412fad-67a4-5071-a11b-ebd8672f9590', '3a399067-d71a-5d86-a71f-0f434978fb5c', 2, 2, 'ጲላጦስም “አንተ የአይሁድ ንጉሥ ነህን?” ብሎ ጠየቀው። እርሱም “አንተ አልህ፤” ብሎ መለሰለት።'),
  ('1506826b-8a45-5087-a9f8-3c4ed44b2a2b', '1c412fad-67a4-5071-a11b-ebd8672f9590', '3a399067-d71a-5d86-a71f-0f434978fb5c', 3, 3, 'የካህናት አለቆችም ብዙ ያሳጡት ነበር፤ እርሱ ግን ምንም አልመለሰም።'),
  ('50e4a182-7e29-500d-ab83-01cd409fcdf9', '1c412fad-67a4-5071-a11b-ebd8672f9590', '3a399067-d71a-5d86-a71f-0f434978fb5c', 4, 4, 'ጲላጦስም ደግሞ “አንዳች አትመልስምን? እነሆ፥ በስንት ነገር ያሳጡሃል” ብሎ ጠየቀው።'),
  ('ba5ffe77-6dc2-5cff-a3bd-6113ca7cabc5', '1c412fad-67a4-5071-a11b-ebd8672f9590', '3a399067-d71a-5d86-a71f-0f434978fb5c', 5, 5, 'ኢየሱስም ከዚያ በኋላ ጲላጦስ እስኪደነቅ ድረስ ምንም አልመለሰም።'),
  ('edbf1e58-40b0-51c1-a971-263f560cb88d', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 1, 6, 'በዚያም በዓል የለመኑትን አንድ እስረኛ ይፈታላቸው ነበር።'),
  ('8d3a6bc9-d84b-5c15-a804-b171fc98b3ad', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 2, 7, 'በዐመፅም ነፍስ ከገደሉት ከዐመፀኞች ጋር የታሰረ በርባን የተባለ ነበረ።'),
  ('f6a59ddc-90a0-5e85-a50e-61efe301b05e', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 3, 8, 'ሕዝቡም ወጥተው እንደ ልማዱ ያደርግላቸው ዘንድ እየጮኹ ይለምኑት ጀመር።'),
  ('01e1ac8d-aeff-58f6-ac45-69d9ef3de6aa', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 4, 9, 'ጲላጦስም “የአይሁድን ንጉሥ እፈታላችሁ ዘንድ ትወዳላችሁን?” ብሎ መለሰላቸው፤'),
  ('b9f01aab-8d40-5f23-ad7f-837240b48da5', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 5, 10, 'የካህናት አለቆች በቅንዓት አሳልፈው እንደ ሰጡት ያውቅ ነበርና።'),
  ('94ef4ed0-960e-5efb-a100-e27adae5d39c', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 6, 11, 'የካህናት አለቆች ግን በርባንን በእርሱ ፈንታ ይፈታላቸው ዘንድ ሕዝቡን አወኩአቸው።'),
  ('7984128a-9fcd-5a63-a383-088b8f17b7ec', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 7, 12, 'ጲላጦስም ዳግመኛ መልሶ “እንግዲህ የአይሁድ ንጉሥ የምትሉትን ምን ላደርገው ትወዳላችሁ?” አላቸው።'),
  ('ceca3cca-890a-5615-a4f6-d270437fc130', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 8, 13, 'እነርሱም ዳግመኛ “ስቀለው!” እያሉ ጮኹ።'),
  ('33b715ea-81de-5fd8-abcf-23338639b080', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 9, 14, 'ጲላጦስም “ምን ነው? ያደረገው ክፋት ምንድር ነው?” አላቸው። እነርሱ ግን “ስቀለው!” እያሉ ጩኸት አበዙ።'),
  ('6beb38de-d7fc-51b9-a571-fad511909771', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'eedfbd1d-1239-5f3e-a28d-13c0408140ea', 10, 15, 'ጲላጦስም የሕዝቡን ፈቃድ ሊያደርግ ወዶ በርባንን ፈታላቸው፤ ኢየሱስንም ገርፎ እንዲሰቀል አሳልፎ ሰጠ።'),
  ('665395de-b3d4-5a50-ae92-3f8e28296ea6', '1c412fad-67a4-5071-a11b-ebd8672f9590', '10842ba9-53a7-5f18-a69f-cb3b3fc95556', 1, 16, 'ወታደሮችም ፕራይቶሪዮን ወደሚባል ግቢ ውስጥ ወሰዱት፤ ጭፍራውንም ሁሉ በአንድነት ጠሩ።'),
  ('c18feb29-8461-530d-a2f9-b5849e5fc51c', '1c412fad-67a4-5071-a11b-ebd8672f9590', '10842ba9-53a7-5f18-a69f-cb3b3fc95556', 2, 17, 'ቀይ ልብስም አለበሱት፤ የእሾህ አክሊልም ጐንጕነው ደፉበት፤'),
  ('a689e715-e3a2-5f20-ad4b-3152c5ede09b', '1c412fad-67a4-5071-a11b-ebd8672f9590', '10842ba9-53a7-5f18-a69f-cb3b3fc95556', 3, 18, '“የአይሁድ ንጉሥ ሆይ! ሰላም ለአንተ ይሁን፤” እያሉ እጅ ይነሱት ጀመር፤'),
  ('73ed1d84-1d6d-5e67-ae87-d9b6c9e35006', '1c412fad-67a4-5071-a11b-ebd8672f9590', '10842ba9-53a7-5f18-a69f-cb3b3fc95556', 4, 19, 'ራሱንም በመቃ መቱት፤ ተፉበትም፤ ተንበርክከውም ሰገዱለት።'),
  ('bbb45667-01ef-5aad-a396-175e704a570d', '1c412fad-67a4-5071-a11b-ebd8672f9590', '10842ba9-53a7-5f18-a69f-cb3b3fc95556', 5, 20, 'ከተዘባበቱበትም በኋላ ቀዩን ልብስ ገፈፉት፤ ልብሱንም አለበሱት፤ ሊሰቅሉትም ወሰዱት።'),
  ('e22ee0bd-16a3-518e-a3eb-ed70532d2e81', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 1, 21, 'አንድ መንገድ አላፊም የአሌክስንድሮስና የሩፎስ አባት ስምዖን የተባለ የቀሬና ሰው ከገጠር ሲመጣ መስቀሉን ይሸከም ዘንድ አስገደዱት።'),
  ('542b34a5-1616-5ec8-a92f-0e66a2b109f6', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 2, 22, 'ትርጓሜውም የራስ ቅል ስፍራ ወደሚሆን ጎልጎታ ወደተባለ ስፍራ ወሰዱት።'),
  ('63323a95-906e-5edd-a11e-b0d35ae7bf56', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 3, 23, 'ከርቤም የተቀላቀለበትን የወይን ጠጅ እንዲጠጣ ሰጡት፤ እርሱ ግን አልተቀበለም።'),
  ('9e3b3901-32a4-57f7-a5da-b2cac3cbcbbf', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 4, 24, 'ሰቀሉትም፤ ልብሱንም ማን ማን እንዲወስድ ዕጣ ተጣጥለው ተካፈሉ።'),
  ('ccf93d82-af81-5d28-a962-d529192a9e65', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 5, 25, 'በሰቀሉትም ጊዜ ሦስት ሰዓት ነበረ።'),
  ('4e4a2811-b64f-5d17-aad4-34a53557d15b', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 6, 26, 'የክሱ ጽሕፈትም “የአይሁድ ንጉሥ” የሚል ተጽፎ ነበር።'),
  ('994e4b96-025f-56b9-a56a-40d2a9684ff4', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 7, 27, 'ከእርሱም ጋር ሁለት ወንበዴዎች አንዱን በቀኙ አንዱንም በግራው ሰቀሉ።'),
  ('59e51726-8b48-5e9a-aa77-0be9ebba0f3e', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 8, 28, 'መጽሐፍም “ከዐመፀኞች ጋር ተቆጠረ፤” ያለው ተፈጸመ።'),
  ('3fccf706-1880-5410-a26b-6650511b9ecb', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 9, 29, 'የሚያልፉትም ራሳቸውን እየነቀነቁ ይሰድቡት ነበርና “ዋ! ቤተ መቅደስን የምታፈርስ በሦስት ቀንም የምትሠራ፥'),
  ('ccca93ee-17a3-5eaf-afe5-6ee98cb771d4', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 10, 30, 'ከመስቀል ወርደህ ራስህን አድን፡” አሉ።'),
  ('8a28c694-d992-5862-a598-1640e8014a16', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 11, 31, 'እንዲሁም የካህናት አለቆች ደግሞ ከጻፎች ጋር እርስ በርሳቸው እየተዘባበቱ “ሌሎችን አዳነ፤ ራሱን ሊያድን አይችልም፤'),
  ('afa7e3ce-7820-53b1-ad76-c58e8690e07f', '1c412fad-67a4-5071-a11b-ebd8672f9590', '9be7fb37-3b7f-5188-afc7-48bc0db40422', 12, 32, 'አይተን እናምን ዘንድ የእስራኤል ንጉሥ ክርስቶስ አሁን ከመስቀል ይውረድ፤” አሉ። ከእርሱም ጋር የተሰቀሉት ይነቅፉት ነበር።'),
  ('8b6f516b-c55b-5e67-a186-e179db631e7a', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 1, 33, 'ስድስት ሰዓትም በሆነ ጊዜ፥ እስከ ዘጠኝ ሰዓት በምድር ሁሉ ላይ ጨለማ ሆነ።'),
  ('33201220-e318-5264-aabd-2abfc70b8214', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 2, 34, 'በዘጠኝ ሰዓትም ኢየሱስ “ኤሎሄ! ኤሎሄ! ላማ ሰበቅታኒ?” ብሎ በታላቅ ድምፅ ጮኸ፤ ትርጓሜውም “አምላኬ! አምላኬ! ለምን ተውኸኝ?” ማለት ነው።'),
  ('a5103cec-83d8-5597-a734-42d19eb6d674', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 3, 35, 'በዚያም ከቆሙት ሰዎች ሰምተው “እነሆ፥ ኤልያስን ይጠራል፤” አሉ።'),
  ('54fe1f62-9527-5473-ab7f-4ed5b3e26c33', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 4, 36, 'አንዱም ሮጦ ሆምጣጤ በሰፍነግ ሞላ በመቃም አድርጎ “ተዉ፤ ኤልያስ ሊያወርደው ይመጣ እንደ ሆነ እንይ፤” እያለ አጠጣው።'),
  ('0513b2a6-373a-510f-aa9c-ebe579466be6', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 5, 37, 'ኢየሱስም በታላቅ ድምፅ ጮኸ፤ ነፍሱንም ሰጠ።'),
  ('6b38ba81-2d7b-5f2e-a84d-cc584853737e', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 6, 38, 'የቤተ መቅደስም መጋረጃ ከላይ እስከ ታች ከሁለት ተቀደደ።'),
  ('51a7d194-a4f3-532e-a9e8-d20967ea943c', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 7, 39, 'በዚያም በአንጻሩ የቆመ የመቶ አለቃ እንደዚህ ጮኾ ነፍሱን እንደ ሰጠ ባየ ጊዜ “ይህ ሰው በእውነት የእግዚአብሔር ልጅ ነበረ፤” አለ።'),
  ('3c0a646a-1090-5c42-ac77-f840bd4d5675', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 8, 40, 'ሴቶችም ደግሞ በሩቅ ሆነው ይመለከቱ ነበር፤ ከእነርሱም በገሊላ ሳለ ይከተሉትና ያገለግሉት የነበሩ መግደላዊት ማርያም የታናሹ ያዕቆብና የዮሳም እናት ማርያም ሰሎሜም ነበሩ፤'),
  ('e1290753-f482-5ec3-a7d0-1ba49c8ada8e', '1c412fad-67a4-5071-a11b-ebd8672f9590', 'e0e574d8-e2cc-52c9-a1e6-44d6b56feee1', 9, 41, 'ከእርሱም ጋር ወደ ኢየሩሳሌም የወጡ ሌሎች ብዙዎች ሴቶች ነበሩ።'),
  ('5c947054-ce2b-52fe-a8ef-2bd1416fbaf6', '1c412fad-67a4-5071-a11b-ebd8672f9590', '2caf6b78-b6e4-5c81-ae60-f6c61e3b0143', 1, 42, 'አሁንም በመሸ ጊዜ የሰንበት ዋዜማ የሆነ የማዘጋጀት ቀን ስለ ነበረ፥'),
  ('318dbaeb-810e-55bc-af1c-22fa8867dbdd', '1c412fad-67a4-5071-a11b-ebd8672f9590', '2caf6b78-b6e4-5c81-ae60-f6c61e3b0143', 2, 43, 'የከበረ አማካሪ የሆነ የአርማትያስ ዮሴፍ መጣ፤ እርሱም ደግሞ የእግዚአብሔርን መንግሥት ይጠባበቅ ነበር፤ ደፍሮም ወደ ጲላጦስ ገባና የኢየሱስን ሥጋ ለመነው።'),
  ('d950b5d2-17f8-5ab4-a8d5-6bade45b7047', '1c412fad-67a4-5071-a11b-ebd8672f9590', '2caf6b78-b6e4-5c81-ae60-f6c61e3b0143', 3, 44, 'ጲላጦስም “አሁኑን እንዴት ሞተ?” ብሎ ተደነቀ፤ የመቶ አለቃውንም ጠርቶ “ከሞተ ቆይቶአልን?” ብሎ ጠየቀው፤'),
  ('b2568d8a-6548-5d1e-abec-6aa0e4197ea8', '1c412fad-67a4-5071-a11b-ebd8672f9590', '2caf6b78-b6e4-5c81-ae60-f6c61e3b0143', 4, 45, 'ከመቶ አለቃውም ተረድቶ በድኑን ለዮሴፍ ሰጠው።'),
  ('c7374e49-09ed-5f53-a4d9-51f52fdaa6a9', '1c412fad-67a4-5071-a11b-ebd8672f9590', '2caf6b78-b6e4-5c81-ae60-f6c61e3b0143', 5, 46, 'በፍታም ገዝቶ አውርዶም በበፍታ ከፈነው፤ ከዐለትም በተወቀረ መቃብር አኖረው፤ በመቃብሩ ደጃፍም ድንጋይ አንከባለለ።'),
  ('c43fc3be-8e5f-5bfe-a834-1c10bd53183e', '1c412fad-67a4-5071-a11b-ebd8672f9590', '2caf6b78-b6e4-5c81-ae60-f6c61e3b0143', 6, 47, 'መግደላዊትም ማርያም የዮሳም እናት ማርያም ወዴት እንዳኖሩት ይመለከቱ ነበር።'),
  ('d14c6890-42ed-5e50-af7a-e8fbcb970312', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 1, 1, 'ሰንበትም ካለፈ በኋላ መግደላዊት ማርያም የያዕቆብም እናት ማርያም ሰሎሜም መጥተው ሊቀቡት ሽቶ ገዙ።'),
  ('35486452-6e84-5871-a071-d07b0ed1129b', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 2, 2, 'ከሳምንቱም በፊተኛው ቀን እጅግ በማለዳ ፀሐይ ከወጣ በኋላ ወደ መቃብር መጡ።'),
  ('39af084b-634b-5d47-ab28-3d9c5d6699d5', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 3, 3, 'እርስ በርሳቸውም “ድንጋዩን ከመቃብር ደጃፍ ማን ያንከባልልልናል?” ይባባሉ ነበር፤'),
  ('15f1f150-79d5-541b-a9af-1bcd8aec141f', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 4, 4, 'ድንጋዩ እጅግ ትልቅ ነበርና፤ አሻቅበውም አይተው ድንጋዩ ተንከባሎ እንደ ነበር ተመለከቱ።'),
  ('b1522ebf-02bf-5a94-a600-1e8f8b29e426', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 5, 5, 'ወደ መቃብሩም ገብተው ነጭ ልብስ የተጐናጸፈ ጐልማሳ በቀኝ በኩል ተቀምጦ አዩና ደነገጡ።'),
  ('462516ce-7ee7-5630-a092-a378f7567b59', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 6, 6, 'እርሱ ግን “አትደንግጡ፤ የተሰቀለውን የናዝሬቱን ኢየሱስን ትፈልጋላችሁ፤ ተነሥቶአል፤ በዚህ የለም፤ እነሆ፥ እርሱን ያኖሩበት ስፍራ።'),
  ('b8e91e71-eae1-5c4d-a4a4-d5bf9baaa43f', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 7, 7, 'ነገር ግን ሄዳችሁ ለደቀ መዛሙርቱ ለጴጥሮስም ‘ወደ ገሊላ ይቀድማችኋል፤ እንደ ነገራችሁ በዚያ ታዩታላችሁ፤’ ብላችሁ ንገሩአቸው፤” አላቸው።'),
  ('1c60af62-e453-587d-a2cb-114218653204', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'df07a335-251f-5ac9-a2ef-cb3ca088800c', 8, 8, 'መንቀጥቀጥና መደንገጥ ይዞአቸው ነበርና ወጥተው ከመቃብር ሸሹ፤ ይፈሩ ነበርና ለማንም አንዳች አልነገሩም። እነርሱም ያዘዛቸውን ሁሉ ለጴጥሮስና ከእርሱ ጋር ላሉት በአጭሩ ተናገሩ። ከዚህም በኋላ ኢየሱስ ራሱ ለዘላለም ድኅነት የሆነውን የማይለወጠውን ቅዱስ ወንጌል ከፀሐይ መውጫ እስከ መጥለቂያው ድረስ በእጃቸው ላከው።'),
  ('64a5a7ab-bfde-5088-a14c-720f7bc35b76', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'ff241dd4-810b-56be-ac5a-660a41f8bc51', 1, 9, 'ከሳምንቱም በመጀመሪያው ቀን ማልዶ በተነሣ ጊዜ፥ አስቀድሞ ሰባት አጋንንት ላወጣላት ለመግደላዊት ማርያም ታየ።'),
  ('9cb3fcb8-c960-5a7e-aa5b-5a6b2b088488', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'ff241dd4-810b-56be-ac5a-660a41f8bc51', 2, 10, 'እርስዋ ሄዳ ከእርሱ ጋር ሆነው ለነበሩት ሲያዝኑና ሲያለቅሱ ሳሉ አወራችላቸው፤'),
  ('5e3bfe38-7b6d-5012-a86a-ddb1f1d9d106', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', 'ff241dd4-810b-56be-ac5a-660a41f8bc51', 3, 11, 'እነርሱም ሕያው እንደ ሆነ ለእርስዋም እንደ ታያት ሲሰሙ አላመኑም።'),
  ('16b92cc7-38ac-5299-a8c0-7922b0539926', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '0acb8dd5-af6c-573a-aee2-b6406abb7b25', 1, 12, 'ከዚህም በኋላ ከእነርሱ ለሁለቱ ወደ ባላገር ሲሄዱ በመንገድ በሌላ መልክ ተገለጠ፤'),
  ('c10e7987-0c90-5481-a3d5-7237bb27952a', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '0acb8dd5-af6c-573a-aee2-b6406abb7b25', 2, 13, 'እነርሱም ሄደው ለሌሎቹ አወሩ፤ እነዚያንም ደግሞ አላመኑአቸውም።'),
  ('72cc8097-69fb-5c9d-a1bd-87b6d262cb66', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '61c96470-3b0b-50cb-aba0-ffba4477e8e5', 1, 14, 'ኋላም በማዕድ ተቀምጠው ሳሉ ለዐሥራ አንዱ ተገለጠ፤ ተነሥቶም ያዩትን ስላላመኑአቸው አለማመናቸውንና የልባቸውን ጥንካሬ ነቀፈ።'),
  ('c8631ef0-bfc4-507a-afa2-66d1615991ac', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '61c96470-3b0b-50cb-aba0-ffba4477e8e5', 2, 15, 'እንዲህም አላቸው “ወደ ዓለም ሁሉ ሂዱ፤ ወንጌልንም ለፍጥረት ሁሉ ስበኩ።'),
  ('4f30d4ff-26a8-5599-a0ea-65ddbe35d6ff', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '61c96470-3b0b-50cb-aba0-ffba4477e8e5', 3, 16, 'ያመነ የተጠመቀም ይድናል፤ ያላመነ ግን ይፈረድበታል።'),
  ('8db2a713-9d91-564a-a06a-70fd667fdc05', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '61c96470-3b0b-50cb-aba0-ffba4477e8e5', 4, 17, 'ያመኑትንም እነዚህ ምልክቶች ይከተሉአቸዋል፤ በስሜ አጋንንትን ያወጣሉ፤ በአዲስ ቋንቋ ይናገራሉ፤'),
  ('f7d11172-8cfb-5ad3-ae1a-2e84723e2b3a', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '61c96470-3b0b-50cb-aba0-ffba4477e8e5', 5, 18, 'እባቦችን ይይዛሉ፤የሚገድልም ነገር ቢጠጡ አይጐዳቸውም፤ እጃቸውን በድውዮች ላይ ይጭናሉ፤ እነርሱም ይድናሉ።'),
  ('8c359bb2-5156-59ab-a4b9-6388c1fea857', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '23d1a96e-140c-5869-ab5e-c59da7df0aa2', 1, 19, 'ጌታ ኢየሱስም ከእነርሱ ጋር ከተናገረ በኋላ ወደ ሰማይ ዐረገ፤ በእግዚአብሔርም ቀኝ ተቀመጠ።'),
  ('1e71cd1b-1a18-5e61-af3f-4e268389c9a1', 'b24b387c-736c-54e5-ae75-4a8b6bf332dd', '23d1a96e-140c-5869-ab5e-c59da7df0aa2', 2, 20, 'እነርሱም ወጥተው በየስፍራው ሁሉ ሰበኩ፤ ጌታም ከእነርሱ ጋር ይሠራ ነበር፤ በሚከተሉትም ምልክቶች ቃሉን ያጸና ነበር።'),
  ('fbbee456-ab07-5e71-ada6-caff8388bffa', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'e27df299-011d-5153-a007-342cf7f8bee5', 1, 1, 'በእኛ ዘንድ የተፈጸመውንና የታመነውን የሥራውን ዜና በሥርዐት ሊጽፉ የጀመሩ ብዙዎች ናቸው።'),
  ('8e7949a5-aa89-5be7-a3a7-56e6fd6c3e67', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'e27df299-011d-5153-a007-342cf7f8bee5', 2, 2, 'ከእኛ አስቀድሞ በዐይን ያዩትና የቃሉ አገልጋዮች የነበሩ እንደ አስተላለፉልን፤'),
  ('869f92e8-fde5-5b19-ad38-43fbff6fc122', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'e27df299-011d-5153-a007-342cf7f8bee5', 3, 3, 'የከበርህ ቴዎፍሎስ ሆይ፥ ከመጀመሪያው ተከትዬ፥ ሁሉንም በየተራው እውነተኛውን እጽፍልህ ዘንድ መልካም ሁኖ ታየኝ።'),
  ('f089072a-b70e-5e09-a28f-b0ddaaa8ab1a', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'e27df299-011d-5153-a007-342cf7f8bee5', 4, 4, 'የተማርኸውን የነገሩን እውነት ጠንቅቀህ ታውቅ ዘንድ።'),
  ('9297d705-d7d7-5262-ab92-8b016d4e9156', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 1, 5, 'በይሁዳ ንጉሥ በሄሮድስ ዘመን ከአብያ ክፍል የሆነ ዘካርያስ የሚባል አንድ ካህን ነበረ፤ ሚስቱም ከአሮን ልጆች ወገን ነበረች፤ ስምዋም ኤልሳቤጥ ነበረ።'),
  ('fb7a25b7-b495-5e5b-ab46-0999c5564d8b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 2, 6, 'ሁለቱም በእግዚአብሔር ፊት ጻድቃን ነበሩ፤ በእግዚአብሔር ሥርዐትና በትእዛዙም ሁሉ ያለ ነውር የሚሄዱ ነበሩ።'),
  ('20673aeb-65a3-5e24-a91f-7ec75c26217e', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 3, 7, 'ልጅም አልነበራቸውም፤ ኤልሳቤጥ መካን ነበረችና፤ ሁለቱም አርጅተው ነበር፤ ዘመናቸውም አልፎ ነበር።'),
  ('786783f9-9ce3-500c-a916-7e4692180312', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 4, 8, 'እርሱም በእግዚአብሔር ፊት በተራው የክህነትን ሥራ በሚሠራበት ጊዜ፥'),
  ('72cf6201-6ee1-5a96-a35c-dca1e376ac4d', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 5, 9, 'ካህናት እንደሚያደርጉት የሚያጥንበት ጊዜ ደረሰ፤ ወደ እግዚአብሔር ቤተ መቅደስም ገባ።'),
  ('99f29721-1ad3-53a6-a314-f0f30d0a1ff3', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 6, 10, 'ዕጣን በሚያጥንበት ጊዜም ሕዝቡ በሙሉ በውጭ ይጸልዩ ነበር።'),
  ('6b94ecfd-d719-5a7a-ac97-4b43a73a4973', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 7, 11, 'የእግዚአብሔር መልአክም በዕጣን መሠውያው በስተቀኝ ቆሞ ታየው።'),
  ('a84cb5a9-4391-586f-a1cf-6775deba95f6', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 8, 12, 'ዘካርያስም ባየው ጊዜ ደነገጠ፤ ፍርሀትም ረዓድም ወረደበት።'),
  ('ee51a69a-903c-586b-acbc-f024b36151e3', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 9, 13, 'መልአኩም እንዲህ አለው፥ “ዘካርያስ ሆይ፥ አትፍራ፤ ጸሎትህ በእግዚአብሔር ፊት ተሰምቶአልና፤ ሚስትህ ኤልሣቤጥም ትፀንሳለች፤ ወንድ ልጅንም ትወልድልሃለች፤ ስሙንም ዮሐንስ ትለዋለህ።'),
  ('c29b40e9-7666-5822-a44b-55ed9ae0f54f', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 10, 14, 'ደስታና ሐሤትም ይሆንልሃል፤ በመወለዱም ብዙዎች ደስ ይላቸዋል።'),
  ('87a712e1-3d67-5a0a-a4d4-79c8a96cd1f8', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 11, 15, 'እርሱ በእግዚአብሔር ፊት ታላቅ ይሆናልና የወይን ጠጅና የሚያሰክርም መጠጥ ሁሉ አይጠጣም፤ ከእናቱ ማሕፀን ጀምሮም መንፈስ ቅዱስ ይመላበታል።'),
  ('260523e3-aeae-5a9e-a63d-999ba63ad56b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 12, 16, 'ከእስራኤልም ልጆች ብዙዎችን ወደ አምላካቸው ወደ እግዚአብሔር ይመልሳቸዋል።'),
  ('175b554e-4ead-5bee-a2ec-e8e83fe37b81', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 13, 17, 'እርሱም የአባቶችን ልብ ወደ ልጆች፥ የከሓድያንንም ዐሳብ ወደ ጻድቃን ዕውቀት ይመልስ ዘንድ፥ ሕዝብንም ለእግዚአብሔር የተዘጋጀ ያደርግ ዘንድ በኤልያስ መንፈስና ኀይል በፊቱ ይሄዳል።”'),
  ('cdd8173b-ddc7-5969-a5c1-ea6d0b57c644', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 14, 18, 'ዘካርያስም የእግዚአብሔርን መልአክ እንዲህ አለው፥ “ይህ እንደሚሆን በምን አውቃለሁ? እነሆ፥ እኔ አርጅችአለሁ፤ የሚስቴም ዘመንዋ አልፏል።”'),
  ('063cddaf-7890-5566-a5fb-f1140246f591', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 15, 19, 'መልአኩም መልሶ እንዲህ አለው፥ “እኔ በእግዚአብሔር ፊት የምቆመው ገብርኤል ነኝ፤ ይህንም እነግርህና አበሥርህ ዘንድ ወደ አንተ ተልኬአለሁ።'),
  ('94df7e54-7a49-524c-ad2d-958ed894c5f4', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 16, 20, 'አሁንም በጊዜው የሚሆነውንና የሚፈጸመውን ነገሬን አላመንኽኝምና ይህ እስኪሆን ድረስ ዲዳ ትሆናለህ፤ መናገርም ይሳንሃል።”'),
  ('02c34b45-abb0-5772-a5fe-cad0e515f460', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 17, 21, 'ሕዝቡ ግን ዘካርያስን ይጠብቁት ነበር፤ በቤተ መቅደስ ውስጥ ዘግይቶ ነበርና እጅግ ተደነቁ።'),
  ('651cdb48-75be-5c63-a5b3-c60dbd9a041e', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 18, 22, 'ወደ እነርሱ ወደ ውጭ በወጣ ጊዜም እነርሱን ማነጋገር ተሳነው፤ በቤተ መቅደስም የተገለጠለት እንዳለ ዐወቁ፤ እንዲሁም ዲዳ ሆኖ በእጁ እያመለከታቸው ኖረ።'),
  ('43bad980-7ba1-55ed-a247-825df91f7ecb', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 19, 23, 'ከዚህም በኋላ የማገልገሉ ወራት በተፈጸመ ጊዜ ወደ ቤቱ ገባ።'),
  ('f7081932-af5e-5f88-a3e3-99ad3379bcc1', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 20, 24, 'ከእነዚያም ቀኖች በኋላ ሚስቱ ኤልሳቤጥ ፀነሰች፤ ፅንስዋንም ለአምስት ወር ሸሸገች፤ እንዲህ ስትል፦'),
  ('97a3f3d6-7192-5c7f-a031-f16889e01b71', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'ca24533a-cfea-5e93-a066-a3cda5edb555', 21, 25, '“እግዚአብሔር በዚህ ወራት ከሰው ስድቤን ያርቅ ዘንድ በጐበኘኝ ጊዜ እንዲህ አደረገልኝ።”'),
  ('0d8ac8a4-e36e-5ff2-a941-b607eaa32a78', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 1, 26, 'በስድስተኛውም ወር መልአኩ ገብርኤል ከእግዚአብሔር ዘንድ ስሟ ናዝሬት ወደምትባለው ወደ አንዲት የገሊላ ከተማ ከዳዊት ወገን ለሚሆን ዮሴፍ ለሚባል ሰው ወደ ታጨችው ወደ አንዲት ድንግል ተላከ፤'),
  ('52873e2b-f75f-5d4e-a359-055d1d54bd5d', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 2, 27, 'የዚያችም ድንግል ስምዋ ማርያም ይባል ነበረ።'),
  ('bee1c170-b68b-5cb7-a32c-3635c3970117', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 3, 28, 'መልአኩም ወደ እርስዋ ገብቶ፥ “ደስ ያለሽ፥ ጸጋንም የተመላሽ ሆይ፥ ደስ ይበልሽ፤ እግዚአብሔር ካንቺ ጋር ነው፤ ከሴቶች ተለይተሽ አንቺ የተባረክሽ ነሽ” አላት።'),
  ('e526e6c1-85f9-594a-a4b9-8417333d10e2', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 4, 29, 'እርስዋም በአየችው ጊዜ ከአነጋገሩ የተነሣ ደነገጠችና “ይህ እንዴት ያለ ሰላምታ ነው?” ብላ ዐሰበች።'),
  ('dff823a5-60b6-584a-a093-80579d02644b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 5, 30, 'መልአኩም እንዲህ አላት፥ “ማርያም ሆይ፥ በእግዚአብሔር ዘንድ ባለሟልነትን አግኝተሻልና አትፍሪ።'),
  ('c82d741d-02aa-5560-a5c4-dcf50f7b1381', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 6, 31, 'እነሆ፥ ትፀንሻለሽ፤ ወንድ ልጅንም ትወልጃለሽ፤ ስሙንም ኢየሱስ ትይዋለሽ።'),
  ('cf8e1bd5-1c1e-58db-aa71-d6432e661826', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 7, 32, 'እርሱም ታላቅ ነው፤ የልዑል እግዚአብሔር ልጅም ይባላል፤ እግዚአብሔር አምላክም የአባቱን የዳዊትን ዙፋን ይሰጠዋል።'),
  ('a6de55a8-d30d-5ae5-acdc-80a32ec4467b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 8, 33, 'ለያዕቆብ ወገንም ለዘለዓለሙ ይነግሣል፤ ለመንግሥቱም ፍጻሜ የለውም።”'),
  ('4f47bed7-7515-5f86-aa69-fa7203f3f68a', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 9, 34, 'ማርያምም መልአኩን፥ “ወንድ ስለማላውቅ ይህ እንዴት ይሆንልኛል?” አለችው።'),
  ('ed512cb4-586b-5455-ac01-ff851e33aa0b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 10, 35, 'መልአኩም መልሶ እንዲህ አላት፥ “መንፈስ ቅዱስ ያድርብሻል፤ የልዑል ኀይልም ይጋርድሻል፤ ከአንቺ የሚወለደውም ቅዱስ ነው፤ የልዑል እግዚአብሔር ልጅም ይባላል።'),
  ('e8e5ba8e-fe88-5876-ade9-625a569ddbe3', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 11, 36, 'እነሆ፥ ከዘመዶችሽ ወገን የምትሆን ኤልሣቤጥም እርስዋ እንኳ በእርጅናዋ ወንድ ልጅን ፀንሳለች፤ መካን ትባል የነበረችው ከፀነሰች እነሆ፥ ይህ ስድስተኛ ወር ነው።'),
  ('55d853b2-114b-59ee-a9c1-f0ad67cda1f4', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 12, 37, 'ለእግዚአብሔር የሚሳነው ነገር የለምና”።'),
  ('da901a19-e0b5-5703-ad4c-1dced24299df', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'abfb66e7-1962-5db8-a9cf-513c1136efc0', 13, 38, 'ማርያምም መልአኩን፥ “እነሆኝ፥ የእግዚአብሔር ባሪያው አለሁ፤ እንደ ቃልህ ይሁንልኝ” አለችው፤ ከዚህ በኋላም መልአኩ ከእርስዋ ዘንድ ሄደ።'),
  ('7ef6589f-2535-53ae-a0dd-acb54b035f2c', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 1, 39, 'በዚያም ወራት ማርያም ፈጥና ተነሣች፤ ወደ ተራራማው ሀገር ወደ ይሁዳ ከተማም ደረሰች።'),
  ('396bf524-a420-55ea-a751-a6b0e6efdaf2', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 2, 40, 'ወደ ዘካርያስ ቤትም ገብታ ለኤልሣቤጥ ሰላምታ ሰጠቻት።'),
  ('6e9b6aef-286a-5992-a8d7-21ee35c70b34', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 3, 41, 'ኤልሳቤጥም የማርያምን ሰላምታ በሰማች ጊዜ ፅንሱ በማኅፀንዋ ዘለለ፤ በኤልሣቤጥም መንፈስ ቅዱስ መላባት።'),
  ('6b976991-de48-5fbb-a73d-0343855eef64', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 4, 42, 'በታላቅ ቃልም ጮሃ እንዲህ አለች፥ “ከሴቶች ተለይተሽ አንቺ የተባረክሽ ነሽ፤ የማኅፀንሽም ፍሬ ቡሩክ ነው።'),
  ('00ebd64b-96b6-59cb-a84d-77ceeb87a51f', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 5, 43, 'የጌታዬ እናት ወደ እኔ ትመጪ ዘንድ እኔ ምንድን ነኝ?'),
  ('89fb3951-1bca-51c3-afe1-ad0b9ca868b7', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 6, 44, 'እነሆ፥ ሰላምታ ስትሰጭኝ ቃልሽን በሰማሁ ጊዜ፥ ፅንሱ በማኅፀኔ በደስታ ዘሎአልና።'),
  ('cfed3f94-2b88-525d-a9a2-ff327397fb13', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 7, 45, 'ከእግዚአብሔር ዘንድ የነገሩሽ ቃል እንደሚሆን የምታምኚ አንቺ ብፅዕት ነሽ።”'),
  ('743aea0e-ce34-5102-a26b-d548137eae15', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 8, 46, 'ማርያምም እንዲህ አለች፥ “ሰውነቴ እግዚአብሔርን ታከብረዋለች።'),
  ('7f4934dd-b0c2-5ec0-a323-95714bb28282', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 9, 47, 'ልቡናዬም በአምላኬ በመድኀኒቴ ሐሤት ታደርጋለች።'),
  ('acf6ebc6-d361-5028-afe1-65ce3153ec70', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 10, 48, 'የባርያውን ትሕትና ተመልክቶአልና። እነሆ፥ ከዛሬ ጀምሮ ትውልድ ሁሉ ብፅዕት ይሉኛል።'),
  ('3c7d5ed0-4e4a-5174-aeab-4d5c3eef4773', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 11, 49, 'ታላቅ ሥራን ሠርቶልኛልና፤ ስሙም ቅዱስ ነው።'),
  ('0354b8be-69a5-540e-a7a1-0e2769ddd49f', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 12, 50, 'ይቅርታውም ለሚፈሩት ለልጅ ልጅ ነው።'),
  ('3c686896-b2c9-521c-ab09-2463d9b4e88b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 13, 51, 'በክንዱ ኀይልን አደረገ፤ በልባቸው ዐሳብ የሚታበዩትንም በተናቸው።'),
  ('3f01d3c7-c505-5a22-af76-468bf787ea65', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 14, 52, 'ኀያላኑን ከዙፋናቸው አዋረዳቸው፤ ትሑታኑንም ከፍ ከፍ አደረጋቸው።'),
  ('87548210-78d3-51b7-add1-a617e2d8728a', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 15, 53, 'የተራቡትን ከበረከቱ አጠገባቸው፤ ባለጠጎችንም ባዶ እጃቸውን ሰደዳቸው።'),
  ('5c35a8d9-72d2-542e-adfd-b21693f8e0a5', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 16, 54, 'ብላቴናውን እስራኤልን ተቀበለው፤ ይቅርታውንም ዐሰበ።'),
  ('eb267ce7-7e90-54d3-a69f-d35f4c13e693', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 17, 55, 'ለአባቶቻችን ለአብርሃምና ለዘሩ እስከ ዘለዓለም እንደ ተናገረው።”'),
  ('06e56816-336f-55cf-ae49-5ced45173db4', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'c04d73a7-5d17-54db-a5a2-492cf16502fc', 18, 56, 'ማርያምም ሦስት ወር ያህል በእርስዋ ዘንድ ተቀመጠች፤ ከዚህ በኋላም ወደ ቤቷ ተመለሰች።'),
  ('2e1f10f2-ea12-54ee-adf3-a70eaf67a573', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 1, 57, 'የኤልሣቤጥም የመውለጃዋ ጊዜ ደረሰ፤ ወንድ ልጅም ወለደች።'),
  ('672070f7-78d8-521a-ac54-1363cca85d11', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 2, 58, 'ዘመዶችዋና ጎረቤቶችዋም እግዚአብሔር ቸርነቱን እንዳበዛላት በሰሙ ጊዜ ከእርስዋ ጋር ደስ አላቸው።'),
  ('73ed44cc-c47c-5120-a385-401c6592fa6b', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 3, 59, 'ከዚህም በኋላ በስምንተኛው ቀን ሕፃኑን ሊገዝሩት መጡ፤ በአባቱም ስም ዘካርያስ ብለው ጠሩት።'),
  ('5d3f0521-3196-58f1-ae12-04e08fbfce78', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 4, 60, 'እናቱ ግን መልሳ፥ “አይሆንም፥ ዮሐንስ ይባል እንጂ” አለች።'),
  ('fc8d7075-6ac2-5dce-a338-137ec6825fa7', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 5, 61, 'እነርሱም፥ “ከዘመዶችሽ ስሙ እንደዚህ የሚባል የለም” አሉአት።'),
  ('2125fb9a-6038-5ed0-a49d-d8c6a05ca583', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 6, 62, 'አባቱንም ጠቅሰው፥ “ማን ሊሉት ትወዳለህ?” አሉት።'),
  ('d63b25c0-0076-5bb6-a7e2-2c00d3e9be86', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 7, 63, 'ብራናም ለመነና “ስሙ ዮሐንስ ይባል” ብሎ ጻፈ፤ ሁሉም አደነቁ።'),
  ('9156c434-16c8-501c-aee1-7868752bd252', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 8, 64, 'ያንጊዜም አፉ ተከፈተ፤ አንደበቱም ተናገረ፤ እግዚአብሔርንም አመሰገነ።'),
  ('413ab71c-fe91-5d3e-af93-9d959291c522', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 9, 65, 'በዚያም ሀገር ሰው ሁሉ ላይ ፍርሀት ሆነ፤ ይህም ነገር ሁሉ በይሁዳ በተራራማው ሀገር ሁሉ ተወራ።'),
  ('215bd863-3250-55e6-a5af-c036e180e062', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 10, 66, 'የሰሙትም ሁሉ፥ “እንግዲህ ይህ ሕፃን ምን ይሆን?” እያሉ በልባቸው አኖሩት፤ የእግዚአብሔር እጅ በእርሱ ላይ ነበረችና።'),
  ('9574a1d4-c5e8-5959-a71b-e7d420eb6c6f', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 11, 67, 'በአባቱ በዘካርያስም መንፈስ ቅዱስ መላበት፤ እንዲህም ብሎ ትንቢት ተናገረ፦'),
  ('8dc2b11e-0b1e-54e0-a6fe-a562087f2ea3', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 12, 68, '“ይቅር ያለን፥ ለወገኖቹም ድኅነትን ያደረገ የእስራኤል አምላክ እግዚአብሔር ይመስገን፤'),
  ('69dd50bd-9919-5a50-af0c-27f77eb0bc0a', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 13, 69, 'ከባርያው ከዳዊት ቤት የምንድንበትን ቀንድ አስነሣልን፤'),
  ('81cac28e-8f74-50dd-a569-351849a1d60f', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 14, 70, 'ከጥንት ጀምሮ በነበሩ በቅዱሳን በነቢያት አፍ እንደ ተናገረ።'),
  ('ca2f13af-c1da-5bc8-a054-9c28ead284fc', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 15, 71, 'ከጠላቶቻችን እጅ፥ ከሚጠሉንም ሁሉ እጅ ያድነን ዘንድ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('88b31c5c-1519-56bd-a0d8-65d6d31564e1', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 16, 72, 'ቸርነቱን ከአባቶቻችን ጋር ያደርግ ዘንድ፥ ቅዱስ ኪዳኑንም ያስብ ዘንድ።'),
  ('6d02944b-b9c1-5c1a-a096-1269275e0aef', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 17, 73, 'ለአባታችን ለአብርሃም የማለውን መሐላ ያስብ ዘንድ።'),
  ('349437a7-f95b-5fe0-ae30-a5b7798ba352', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 18, 74, 'ከጠላቶቻችን እጅ ድነን ያለ ፍርሀት፥'),
  ('494bb820-1a86-5841-abd4-c84806d7781e', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 19, 75, 'በቅድስናና በጽድቅ በፊቱ በዘመናችን ሁሉ እንድናመልከው ይሰጠን ዘንድ።'),
  ('fc8c61bb-e82c-5f4a-a078-841e5685ddc4', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 20, 76, 'አንተም ሕፃን፥ የልዑል ነቢይ ትባላለህ፤ መንገዱን ትጠርግ ዘንድ በፊቱ ትሄዳለህና።'),
  ('f9c21cd1-34a9-53c0-afc5-8c57a9f0d515', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 21, 77, 'ኀጢአታቸው ይሰረይላቸው ዘንድ መድኀኒታቸውን እንዲያውቁ ለአሕዛብ ትሰጣቸው ዘንድ።'),
  ('1c04deec-7fa4-5ed5-a78f-8e00ddbcb257', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 22, 78, 'ከአርያም በጐበኘን በአምላካችን በይቅርታውና በቸርነቱ።'),
  ('8b138935-3297-5a9f-a3d5-05c4411f8579', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 23, 79, 'በጨለማና በሞት ጥላ ለነበሩት ብርሃኑን ያሳያቸው ዘንድ፥ እግሮቻችንንም ወደ ሰላም ጎዳና ያቀና ዘንድ ወጣ።”'),
  ('dae0ae81-ffd5-55ad-a2c0-ec40d98c2081', '76532c7e-e056-5429-af3a-bacdf338cfb5', 'a388ad13-d3d7-58f0-ab19-cd7448088445', 24, 80, 'ሕፃኑም አደገ፤ በመንፈስ ቅዱስም ጸና፤ ለእስራኤልም እስከታየበት ቀን ድረስ በምድረ በዳ ኖረ።'),
  ('0cfad38d-4e6b-58ec-aae9-20eb5bbca508', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '352fddaf-90b5-5742-adf8-f30dd47bf7a5', 1, 1, 'በዚያም ወራት እንዲህ ሆነ፤ ሰው ሁሉ ይቈጠር ዘንድ ከአውግስጦስ ቄሣር ትእዛዝ ወጣ።'),
  ('e44f1280-5963-5159-a285-a9ff5c08f893', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '352fddaf-90b5-5742-adf8-f30dd47bf7a5', 2, 2, 'ቄሬኔዎስ ለሶርያ መስፍን በነበረ ጊዜ ይህ የመጀመርያ ቈጠራ ሆነ።'),
  ('e793bde0-b551-57aa-aa48-4c56286b6001', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '352fddaf-90b5-5742-adf8-f30dd47bf7a5', 3, 3, 'ሰው ሁሉ ሊቈጠር ወደየከተማው ሄደ።'),
  ('86bf7f1d-2d9d-54cd-a355-37694bf9c166', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '352fddaf-90b5-5742-adf8-f30dd47bf7a5', 4, 4, 'ዮሴፍም ከገሊላ አውራጃ ከናዝሬት ከተማ ወደ ይሁዳ፥ ቤተ ልሔም ወደምትባለው ወደ ዳዊት ከተማ ወጣ፤ እርሱ ከዳዊት ሀገርና ከዘመዶቹም ወገን ነበርና።'),
  ('49d6bb18-0f33-5b2e-a663-6d701f74e781', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '352fddaf-90b5-5742-adf8-f30dd47bf7a5', 5, 5, 'ፀንሳ ሳለች ከእጮኛው ከማርያም ጋር ይጻፍ ዘንድ ሄደ።'),
  ('8bda9a06-c700-5f78-a05c-2a5190f3c35c', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 1, 6, 'በዚያ ሳሉም የምትወልድበት ቀን ደረሰ።'),
  ('d68be655-e66c-59a2-ac0e-45decc27dd45', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 2, 7, 'የበኵር ልጅዋንም ወለደች፤ አውራ ጣቱንም አሰረችው፤ በጨርቅም ጠቀለለችው፤ በበረትም አስተኛችው፤ በማደርያቸው ቦታ አልነበራቸውምና።'),
  ('78a6b04e-086f-5eba-a4e9-a94da545ae69', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 3, 8, 'በዚያ ሀገር እረኞች ነበሩ፤ ሌሊቱንም ተግተው መንጋቸውን ይጠብቁ ነበር።'),
  ('ca6c4556-2680-51ee-a964-1adaa5b36a00', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 4, 9, 'እነሆም፥ የእግዚአብሔር መልአክ በአጠገባቸው ቆመ፤ የእግዚአብሔርም ብርሃን በዙሪያቸው አበራ፤ ታላቅ ፍርሀትንም ፈሩ።'),
  ('f1fcb2f2-aff9-511e-abae-ad856c487214', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 5, 10, 'መልአኩም እንዲህ አላቸው፥ “እነሆ፥ ለእናንተና ለሕዝቡ ሁሉ ደስታ የሚሆን ታላቅ የምሥራች እነግራችኋለሁና አትፍሩ።'),
  ('8a507421-d271-51d7-af2a-0fc16bcc3d5c', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 6, 11, 'እነሆ፥ ዛሬ በዳዊት ከተማ መድኅን ተወልዶላችኋል፤ ይኸውም ቡሩክ ጌታ ክርስቶስ ነው።'),
  ('4154f6dc-660b-55d8-af00-0635968ebb2d', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 7, 12, 'ለእናንተም ምልክቱ እንዲህ ነው፦ ሕፃን አውራ ጣቱን ታስሮ፥ በጨርቅም ተጠቅልሎ በበረት ውስጥ ተኝቶ ታገኛላቸሁ።”'),
  ('ee5a8718-0fbe-5a9d-ae0b-e3640a79ae36', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 8, 13, 'ድንገትም ከዚያ መልአክ ጋር ብዙ የሰማይ ሠራዊት እግዚአብሔርን እያመሰገኑ መጡ።'),
  ('25c5214e-74fc-5e46-ae81-755f269cf8cc', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 9, 14, '“ክብር ለእግዚአብሔር በሰማያት፥ ሰላምም በምድር፥ ለሰው ልጅም በጎ ፈቃድ ሆነ” ይሉ ነበር።'),
  ('59680cd0-f995-5fa9-af28-ee9b458c84c3', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 10, 15, 'ከዚህም በኋላ መላእክት ከእነርሱ ዘንድ ወደ ሰማይ በዐረጉ ጊዜ እነዚያ እረኞች ሰዎች እርስ በርሳቸው፥ “እስከ ቤተ ልሔም እንሂድ፤ እግዚአብሔርም የገለጠልንን ይህን ነገር እንወቅ” አሉ።'),
  ('333a2c0e-28c9-52ab-aa4d-4974a901c941', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 11, 16, 'ፈጥነውም ሄዱ፤ ማርያምንና ዮሴፍን አገኙአቸው፤ ሕፃኑንም በበረት ውስጥ ተኝቶ አገኙት።'),
  ('4846a8e1-2d48-52af-a7ea-3c9cd3212531', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 12, 17, 'በአዩም ጊዜ የነገሩአቸው ስለዚህ ሕፃን እንደ ሆነ ዐውቀው አወሩ።'),
  ('445ca01c-f48e-51c9-a4f5-c7dfb24bd731', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 13, 18, 'የሰሙትም ሁሉ እረኞቹ የነገሩአቸውን አደነቁ።'),
  ('9e9b8596-fbdc-5f5f-aa16-bb7d6e1a6d9f', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 14, 19, 'ማርያም ግን ይህን ሁሉ ትጠብቀው፥ በልብዋም ታኖረው ነበር።'),
  ('b4b7dd9f-09c4-5508-a43b-772ddafbb330', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fa0ea33e-8307-5a89-ab0a-6640b51e8943', 15, 20, 'እረኞችም እንደ ነገሩአቸው ባዩትና በሰሙት ሁሉ እግዚአብሔርን እያከበሩና እያመሰገኑ ተመለሱ።'),
  ('fd619f79-26dc-51bc-a1d5-c07304f93ed1', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fd298067-0b8d-593c-afa2-50da4362324a', 1, 21, 'ስምንት ቀን በተፈጸመ ጊዜም ሕፃኑን ሊገዝሩት ወሰዱት፤ በማኅፀንዋ ሳትፀንሰው መልአኩ እንዳወጣለትም ስሙን ኢየሱስ አሉት።'),
  ('d3f9a4cf-b088-59b6-a827-21484ebf97b0', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fd298067-0b8d-593c-afa2-50da4362324a', 2, 22, 'የመንጻታቸውም ወራት በተፈጸመ ጊዜ እንደ ሙሴ ሕግ በእግዚአብሔር ፊት ያቆሙት ዘንድ ወደ ኢየሩሳሌም ወሰዱት።'),
  ('a1e6f3a4-5c46-54a4-a61d-d1fb060d7a56', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fd298067-0b8d-593c-afa2-50da4362324a', 3, 23, '“በኵር ሆኖ የሚወለድ ወንድ ልጅ ሁሉ ለእግዚአብሔር የተቀደሰ ይባላል” ተብሎ በእግዚአብሔር ሕግ እንደ ተጻፈ፥'),
  ('e3b833ab-7f20-5884-aaac-b4601b81925f', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', 'fd298067-0b8d-593c-afa2-50da4362324a', 4, 24, 'በእግዚአብሔርም ሕግ እንደ ታዘዘ ሁለት ዋኖስ ወይም ሁለት የርግብ ግልገሎች ስለ እርሱ መሥዋዕት አድርገው ያቀርቡለት ዘንድ።'),
  ('da8642a2-f122-5098-a327-dd0a1f6e1547', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 1, 25, 'በኢየሩሳሌምም ስሙ ስምዖን የሚባል አንድ ሰው ነበር፤ እርሱም ጻድቅና ደግ ሰው ነበር፤ እርሱም የእስራኤልን ደስታቸውን ያይ ዘንድ ተስፋ ያደርግ ነበር፤ መንፈስ ቅዱስም ያደረበት ነበር።'),
  ('b4bb5c36-8b76-5659-a81d-fe2f9f8018b9', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 2, 26, 'የእግዚአብሔርንም መሲሕ ሳያይ እንደማይሞት መንፈስ ቅዱስ ገልጦለት ነበር።'),
  ('e9c34570-065b-5296-a61b-4052be41bc3b', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 3, 27, 'መንፈስም ወደ ቤተ መቅደስ ወሰደው፤ ዘመዶቹም በሕግ የተጻፈውን ያደርጉለት ዘንድ ሕፃኑን ጌታችን ኢየሱስን ወደ ቤተ መቅደስ በአገቡት ጊዜ፥'),
  ('278b88db-2060-5998-a6f0-60377600b3ba', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 4, 28, 'እርሱ ደግሞ ተቀብሎ በክንዱ ታቀፈው፤ እግዚአብሔርንም አመሰገነው።'),
  ('0de78cca-e8af-5f5a-a7b6-e9d24ca64c16', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 5, 29, 'እንዲህም አለ፤ “አቤቱ፥ እንደ አዘዝህ ዛሬ ባርያህን በሰላም ታሰናብተዋለህ።'),
  ('1ac3deec-cb01-54b6-a2c6-683c603b0901', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 6, 30, 'ዐይኖች ትድግናህን አይተዋልና።'),
  ('2d8a8536-2980-51d5-ad17-c6b106700c12', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 7, 31, 'በወገንህ ሁሉ ፊት ያዘጋጀኸውን፥'),
  ('52c2fe62-adeb-5f6e-a24a-b13129ed503d', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 8, 32, 'ለአሕዛብ ብርሃንን፥ ለወገንህ ለእስራኤልም ክብርን ትገልጥ ዘንድ።”'),
  ('2c000f8d-93ed-5ccb-a026-5769610c5a11', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 9, 33, 'ዮሴፍና እናቱ ግን በእርሱ ላይ ስለሚናገረው ያደንቁ ነበር።'),
  ('c89baa51-7e7c-5720-af2a-81d51b3f3b05', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 10, 34, 'ስምዖንም ባረካቸው፤ እናቱን ማርያምንም እንዲህ አላት፤ “እነሆ፥ ይህ ሕፃን ከእስራኤል መካከል ለብዙዎች ለመውደቃቸውና ለመነሣታቸው፥ ለሚቃወሙትም ምልክት ይሆን ዘንድ የተሠየመ ነው፤'),
  ('f6a87678-6470-5fb2-ace3-f13534e3c163', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '55ec30a5-5f4b-5b33-ad38-b31cea742e0e', 11, 35, 'ባንቺ ግን በልብሽ ፍላጻ ይገባል፤ የብዙዎቹን ዐሳብ ይገልጥ ዘንድ።”'),
  ('4c300a08-9790-5aff-a9fd-af5f55668dac', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '902bed8b-d947-5114-a3c6-83148f084e39', 1, 36, 'ከአሴር ወገን የምትሆን የፋኑኤል ልጅ ሐና የምትባል ነቢይት ነበረች፤ አርጅታም ነበር፤ ከድንግልናዋም በኋላ ከባል ጋር ሰባት ዓመት ኖረች።'),
  ('383e8ccc-c250-5e74-a4bb-c3dde07ffd46', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '902bed8b-d947-5114-a3c6-83148f084e39', 2, 37, 'ሰማንያ አራት ዓመትም መበለት ሆና ኖረች፤ በጾምና በጸሎትም እያገለገለች፥ ቀንም ሆነ ሌሊት ከቤተ መቅደስ አትወጣም ነበር።'),
  ('d59863ff-988a-5210-ac14-d339e8175e54', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '902bed8b-d947-5114-a3c6-83148f084e39', 3, 38, 'ያንጊዜም ተነሥታ እግዚአብሔርን አመሰገነች፤ የኢየሩሳሌምንም ድኅነት ተስፋ ለሚያደርጉ ሁሉ ስለ እርሱ ተናገረች።'),
  ('4a82b400-7373-595b-a4b6-65b3b442872f', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '902bed8b-d947-5114-a3c6-83148f084e39', 4, 39, 'በእግዚአብሔርም ሕግ የተጻፈውን ሁሉ ከፈጸሙ በኋላ ወደ ገሊላ ወደ ከተማቸው ወደ ናዝሬት ተመለሱ።'),
  ('6bad0380-272d-5a5e-a676-616b80701e2d', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '902bed8b-d947-5114-a3c6-83148f084e39', 5, 40, 'ሕፃኑም አደገ፤ በመንፈስም ጠነከረ፤ ጥበብንም የተመላ ነበር፤ የእግዚአብሔርም ጸጋ በእርሱ ላይ ነበረች።'),
  ('bb8c2928-1aad-5c20-a452-603503c50b5b', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 1, 41, 'ዘመዶቹም በየዓመቱ ለፋሲካ በዓል ወደ ኢየሩሳሌም ይሄዱ ነበር።'),
  ('9333da48-29c8-570b-a2ca-be9272f9443e', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 2, 42, 'ዐሥራ ሁለት ዓመትም በሞላው ጊዜ እንደ አስለመዱ ወደ ኢየሩሳሌም ለበዓል ወጡ።'),
  ('42811fff-d1b7-5baa-ac9f-5f455b5d3f5e', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 3, 43, 'ሥራቸውንም ጨርሰው ተመለሱ፤ ሕፃኑ ጌታችን ኢየሱስ ግን በኢየሩሳሌም ቀርቶ ነበር፤ ዮሴፍና እናቱም አላወቁም ነበር።'),
  ('f8b96272-4dc0-5f2f-a85c-63a316075e02', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 4, 44, 'በመንገድም ከሰዎች ጋር ያለ መስሎአቸው ነበር፤ ያንድ ቀን መንገድንም ከሄዱ በኋላ ዕለቱን ከዘመዶቹ፥ ከሚያውቁትም ዘንድ ፈለጉት።'),
  ('b140797e-c23d-589a-acd5-3da16fb1e7e4', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 5, 45, 'ባላገኙትም ጊዜ እየፈለጉት ወደ ኢየሩሳሌም ተመለሱ።'),
  ('6ca58939-8680-55fe-a0da-f52bec0737f2', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 6, 46, 'ከዚህም በኋላ በሦስተኛው ቀን በቤተ መቅደስ በሊቃውንት መካከል ተቀምጦ ሲሰማቸውና ሲጠይቃቸው አገኙት።'),
  ('3fb0d38a-eb05-53ac-a8d9-d867fb926bfc', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 7, 47, 'የሰሙትም ሁሉ አስተዋይነቱንና አመላለሱን ያደንቁ ነበር።'),
  ('981a08cd-c1c7-527c-a851-7aa61446c416', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 8, 48, 'በአዩትም ጊዜ ደነገጡ፤ እናቱም፥ “ልጄ፥ ለምን እንዲህ አደረግኸን? እነሆ አባትህም፥ እኔም ስንፈልግህ ደከምን” አለችው።'),
  ('d877f924-a43e-58b7-a97b-47b951a6f96a', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 9, 49, 'እርሱም፥ “ለምን ትፈልጉኛላችሁ? በአባቴ ቤት ልኖር እንደሚገባኝ አላወቃችሁምን?” አላቸው።'),
  ('ed209a2c-ac19-5cf3-a30b-48b4b1fda770', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 10, 50, 'እነርሱ ግን የነገራቸውን ቃል አላስተዋሉም።'),
  ('a68ed66c-b38e-5614-a4fc-71890cdeaa86', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 11, 51, 'ከእነርሱም ጋር ሂዶ ወደ ናዝሬት ወረደ፤ ይታዘዝላቸውም ነበር፤ እናቱ ግን ይህን ሁሉ ነገር ትጠብቀው፥ በልብዋም ታኖረው ነበር።'),
  ('6dc37fc5-af6c-561a-ab6e-9f913ddcbea0', 'ea51ebb2-dfd8-5278-ac70-d8ac91abbf13', '8a077dbf-cb20-5a9f-a880-12726a175f5e', 12, 52, 'ጌታችን ኢየሱስም በእግዚአብሔር ዘንድ፥ በሰውም ዘንድ፥ በጥበብና በአካል በሞገስም አደገ።'),
  ('03380c9e-e047-5238-a0e8-d15b34145937', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 1, 1, 'ጢባርዮስ ቄሣር በነገሠ በዐሥራ አምስት ዓመት ጴንጤናዊው ጲላጦስ የይሁዳ ገዢ ሆኖ ሳለ፥ ሄሮድስም በገሊላ የአራተኛው ክፍል ገዢ ሳለ፥ ወንድሙ ፊልጶስም የኢጡርያስና የጥራኮኒዶስ አራተኛ ክፍል ገዢ፥ ሊሳንዮስም የሳብላኒስ አራተኛ ክፍል ገዢ ሆነው ሳሉ፥'),
  ('e83e2255-3b51-57ba-a464-25ad28d51af6', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 2, 2, 'ሐናና ቀያፋም ሊቃነ ካህናት በነበሩበት ወራት የእግዚአብሔር ቃል በምድረ በዳ ወደ ዘካርያስ ልጅ ወደ ዮሐንስ መጣ።'),
  ('7dfd9f00-db8a-53c6-a74d-6114e46097da', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 3, 3, 'ስለ ኀጢአት ስርየት ለንስሓ የሚያበቃ ጥምቀትን እየሰበከ በዮርዳኖስ አውራጃ ዞረ።'),
  ('6f141121-32e8-5eb9-a758-dd373d898832', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 4, 4, 'በምድረ በዳ የሚጮኽ የአዋጅ ነጋሪ ድምፅ በነቢዩ በኢሳይያስ መጽሐፍ ቃል እንደ ተጻፈ፥ እንዲህ ሲል፥ “የእግዚአብሔርን መንገድ ጥረጉ፤ ጥርጊያውንም አስተካክሉ።'),
  ('141e667a-10c1-5fc8-a91b-92fc04384bce', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 5, 5, 'ጐድጓዳው ሁሉ ይምላ፤ ተራራውም፥ ኮረብታውም ሁሉ ዝቅ ይበል፤ ሰንከልካላውም የቀና ጥርጊያ ይሁን፤ ወጣ ገባው መንገድም ይስተካከል።'),
  ('7185262d-669b-574c-a356-18b7656a340c', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 6, 6, 'ሰውም ሁሉ የእግዚአብሔርን ትድግና ይይ።”'),
  ('29ca0604-b56f-5c37-ae3e-3116b8785436', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 7, 7, 'ዮሐንስም ሊያጠምቃቸው የመጡትን ሰዎች እንዲህ አላቸው፥ “እናንት የእፉኝት ልጆች፥ ከሚመጣው መቅሠፍት ታመልጡ ዘንድ ማን ነገራችሁ?'),
  ('8115def1-f77f-5c15-aa2f-4e3912a6363a', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 8, 8, 'እንግዲህ ለንስሓ የሚያበቃችሁን ሥራ ሥሩ፤ አብርሃም አባታችን አለን በማለት የምታመልጡ አይምሰላችሁ፤ እግዚአብሔር ከእነዚህ ድንጋዮች ለአብርሃም ልጆችን ማስነሣት እንደሚችል እነግራችኋለሁ።'),
  ('6dc98889-3335-5ef1-a173-e0fc035ec3ab', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 9, 9, 'እነሆ፥ ምሳር በዛፎች ላይ ተቃጥቶአል፤ መልካም ፍሬ የማያፈራውንም ዛፍ ሁሉ ይቈርጡታል፤ ወደ እሳትም ይጥሉታል።”'),
  ('d7a71dbb-abcb-5468-a26e-858516710f53', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 10, 10, 'ሕዝቡም፥ “እንግዲህ ምን እናድርግ?” ብለው ጠየቁት።'),
  ('c03b4e92-e9da-5876-ae9d-caf7ace23d07', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 11, 11, 'እርሱም መልሶ እንዲህ አላቸው፥ “ሁለት ልብስ ያለው አንዱን ለሌለው ይስጥ፤ ምግብ ያለውም እንዲሁ ያድርግ።”'),
  ('b620180c-9650-5e42-a147-01e77b96d633', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 12, 12, 'ቀራጮችም ሊያጠምቃቸው መጡና፥ “መምህር፥ ምን እናድርግ?” ብለው ጠየቁት።'),
  ('0f803209-c937-5b5b-a37b-1c3e63a81250', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 13, 13, 'እርሱም፥ “ከታዘዛችሁት አትርፋችሁ አትውሰዱ” አላቸው።'),
  ('a56b948f-eb19-5dd1-a18f-d9a08235ef43', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 14, 14, 'ጭፍሮችም መጥተው፥ “እኛሳ ምን እናድርግ?” አሉት፤ “በደመወዛችሁ ኑሩ እንጂ በማንም ግፍ አትሥሩ፤ ማንንም አትቀሙ፤ አትበድሉም” አላቸው።'),
  ('8d14d168-3a1d-517a-ac20-69f4723903c0', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 15, 15, 'ሕዝቡም ሁሉ በልባቸው ዐሰቡ፤ ዮሐንስም ክርስቶስ እንደ ሆነ መሰላቸው።'),
  ('20255ac5-64c8-560d-a976-eff0549d7264', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 16, 16, 'ዮሐንስም መልሶ ሁሉንም እንዲህ አላቸው፥ “እኔ በውኃ አጠምቃችኋለሁ፤ ግን የሚበልጠኝ የጫማውን ማሰሪያ እንኳ ልፈታለት የማይገባኝ ይመጣል፤ እርሱ በመንፈስ ቅዱስ፥ በእሳትም ያጠምቃችኋል።'),
  ('525a0742-e9f3-5cb0-a7c0-4a789517d50b', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 17, 17, 'መንሹ በእጁ ነው፤ የዐውድማውንም እህል ያጠራል፤ ስንዴውንም በጎተራው ይሰበስባል፤ ገለባውን ግን በማይጠፋ እሳት ያቃጥላል።”'),
  ('ad3c5e90-865e-5834-a6a9-0c7a663f564b', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'da026f78-b93a-5114-ac9f-429c1d02285a', 18, 18, 'ሕዝቡንም ይገስጻቸውና በሌላም በብዙ ነገር የምሥራች ይነግራቸው ነበር።'),
  ('b7c47770-42e9-5054-a065-78607332ea45', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '1ef6e0cf-fece-5da5-a2e3-00fa0d55cb8d', 1, 19, 'ዮሐንስም የአራተኛው ክፍል ገዢ ሄሮድስን የወንድሙን የፊልጶስን ሚስት ሄሮድያዳን ስለማግባቱና ሄሮድስ ያደርገው ስለነበረው ክፉ ነገር ሁሉ ይገሥጸው ነበር።'),
  ('ed2d9119-195a-54e7-ab65-bf399d39eafd', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '1ef6e0cf-fece-5da5-a2e3-00fa0d55cb8d', 2, 20, 'ደግሞም ከዚህ ሁሉ በላይ ጨምሮ ዮሐንስን ተቀየመውና በግዞት ቤት አስገባው።'),
  ('22e8ede0-14e1-5b0e-aa67-706a2683b6b4', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'aebb5dd1-2b88-5049-a9d4-9482c51f1403', 1, 21, 'ሕዝቡም ሁሉ ከተጠመቁ በኋላ ጌታችን ኢየሱስም ተጠመቀ፤ ሲጸልይም ሰማይ ተከፈተ።'),
  ('4a2b8c52-a33a-56c7-a3e7-97ebd697b3a9', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', 'aebb5dd1-2b88-5049-a9d4-9482c51f1403', 2, 22, 'መንፈስ ቅዱስም የርግብ መልክ ባለው አካል አምሳል በእርሱ ላይ ወረደ፤ ከሰማይም፥ “የምወድህ፥ በአንተም ደስ የሚለኝ ልጄ አንተ ነህ” የሚል ቃል መጣ። ሉቃ. 9፥35።'),
  ('42e2afc6-f604-54f9-aa06-c32d4ad00fd6', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 1, 23, 'የጌታችን ኢየሱስም ዕድሜዉ ሠላሳ ዓመት ያህል ነበር፤ የዮሴፍ ልጅም ይመስላቸው ነበር።'),
  ('e7f1659d-fd52-5378-aae5-aa42549f6577', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 2, 24, 'የኤሊ ልጅ፥ የማቲ ልጅ፥ የሌዊ ልጅ፥ የሜልኪ ልጅ፥ የዮና ልጅ፥ የዮሴፍ ልጅ፥'),
  ('94ede7a9-a779-5886-ab63-211be7c32476', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 3, 25, 'የማታትዩ ልጅ፥ የአሞጽ ልጅ፥ የናሆም ልጅ፥ የኤስሎም ልጅ፥ የናጌ ልጅ፥'),
  ('02f032cf-a67a-59fd-ace3-e5e6afc19ce3', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 4, 26, 'የማአት ልጅ፥ የማታትዩ ልጅ፥ የሴሜይ ልጅ፥ የዮሴፍ ልጅ፥ የዮዳ ልጅ፥'),
  ('5a28ed55-17cf-5fac-a125-8bab48fbcdd1', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 5, 27, 'የዮናን ልጅ፥ የሬስ ልጅ፥ የዘሩባቤል ልጅ፥ የሰላትያል ልጅ፥ የኔሪ ልጅ፥'),
  ('e9b495a7-fc76-558e-ab5d-b6576e850552', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 6, 28, 'የሜልኪ ልጅ፥ የሐዲ ልጅ፥ የዮሳ ልጅ፥ የቆሳም ልጅ፥ የኤልሞዳም ልጅ፥ የኤር ልጅ፥'),
  ('e3f1cb41-4a82-5608-a8a2-96002f88c8e8', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 7, 29, 'የዮሴዕ ልጅ፥ የአልዓዛር ልጅ፥ የዮራም ልጅ፥ የማጣት ልጅ፥ የሌዊ ልጅ፥'),
  ('e7cd165b-67bb-56a7-a45e-cc04a04aaf84', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 8, 30, 'የስምዖን ልጅ፥ የይሁዳ ልጅ፥ የዮሴፍ ልጅ፥ የዮናን ልጅ፥ የኤልያቄም ልጅ፥'),
  ('e2be7439-46a4-5f46-adef-067aa120bfcc', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 9, 31, 'የሜልያ ልጅ፥ የማይናን ልጅ፥ የማጣት ልጅ፥ የናታን ልጅ፥ የዳዊት ልጅ፥'),
  ('b800fd33-d143-57e2-a4d9-8b41fc02faee', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 10, 32, 'የዕሤይ ልጅ፥ የኢዮቤድ ልጅ፥ የቦዔዝ ልጅ፥ የሰልሞን ልጅ፥ የነዓሶን ልጅ፥'),
  ('2e5c49c8-f710-5990-a7a7-109bcfef51fa', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 11, 33, 'የአሚናዳብ ልጅ፥ የአራም ልጅ፥ የኦርኒ ልጅ፥ የኤስሮም ልጅ፥ የፋሬስ ልጅ፤ የይሁዳ ልጅ፥'),
  ('26613480-e947-559d-ac0d-5e19b116da98', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 12, 34, 'የያዕቆብ ልጅ፥ የይስሐቅ ልጅ፥ የአብርሃም ልጅ፥ የታራ ልጅ፥ የናኮር ልጅ፥'),
  ('c85ba79e-186f-54b3-a206-73b5b6815ead', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 13, 35, 'የሴሩኅ ልጅ፥ የራግው ልጅ፥ የፋሌቅ ልጅ፥ የኤቦር ልጅ፥ የሳላ ልጅ፥'),
  ('3b88f5d3-f522-5393-a98e-1cd932ffd4c7', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 14, 36, 'የቃይናን ልጅ፥ የአርፋክስድ ልጅ፥ የሴም ልጅ፥ የኖኅ ልጅ፥ የላሜሕ ልጅ፥'),
  ('9a9a42cb-d8ac-5e7d-a9fa-c4ddabde7753', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 15, 37, 'የማቱሳላ ልጅ፥ የሄኖክ ልጅ፥ የያሬድ ልጅ፥ የመላልኤል ልጅ፥ የቃይናን ልጅ፥'),
  ('be53104b-97a0-5c89-a575-b06d49344fab', '25d5f16b-7ca4-5e18-acf9-e04c43ec2cbe', '6799cf14-3808-50a1-a396-2fc776dd1ee3', 16, 38, 'የሄኖስ ልጅ፥ የሴት ልጅ፥ የአዳም ልጅ፥ የእግዚአብሔር ልጅ።'),
  ('2e07c5d5-5460-5e49-ac34-a125aadb914e', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 1, 1, 'ጌታችን ኢየሱስም መንፈስ ቅዱስን ተመልቶ ከዮርዳኖስ ተመለሰ፤ መንፈስም ወደ ምድረ በዳ ወሰደው።'),
  ('2243574f-17a1-590b-a9c3-031436df5ce2', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 2, 2, 'አርባ መዓልትና አርባ ሌሊት ከዲያብሎስ ተፈተነ፥ በእነዚያም ቀኖች ምንም አልበላም፤ እነዚያም ቀኖች ከተፈጸሙ በኋላ ተራበ።'),
  ('95fbb7f9-6fe2-5ef8-aca0-f8923ed9ed37', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 3, 3, 'ዲያብሎስም፥ “አንተ የእግዚአብሔር ልጅ ከሆንህስ ይህ ድንጋይ እንጀራ ይሁን በል” አለው።'),
  ('9706c0b1-bfe0-5879-a339-16777c5f5ec8', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 4, 4, 'ጌታችን ኢየሱስም መልሶ፥ “ሰው የሚኖረው ከእግዚአብሔር አፍ በሚወጣው ቃል ነው እንጂ በእንጀራ ብቻ አይደለም የሚል ተጽፎአል” አለው።'),
  ('e813341e-13c5-5c65-af40-2c66bc8b563c', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 5, 5, 'ዲያብሎስም ወደ ረዥም ተራራ አወጣው፤ የዓለምን መንግሥታትም ሁሉ በቅፅበት አሳየው።'),
  ('e867774f-2c0c-5535-aca8-a6187a2ca0e5', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 6, 6, 'ዲያብሎስም እንዲህ አለው፥ “ይህን ሁሉ ግዛት፥ ይህንም ክብር ለአንተ እሰጥሃለሁ፤ ለእኔ ተሰጥቶአልና፤ ለወደድሁትም እሰጠዋለሁና።'),
  ('d4024456-63ad-50e3-aee6-9ade7538a367', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 7, 7, 'ስለዚህ አንተ በፊቴ ብትሰግድልኝ ይህ ሁሉ ለአንተ ይሁንልህ።”'),
  ('a2d15321-50c1-5083-a3ee-29ca63d1dbea', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 8, 8, 'ጌታችን ኢየሱስም መልሶ፥ “ሰይጣን ከኋላዬ ሂድ ለእግዚአብሔር ለአምላክህ ልትሰግድ፥ እርሱንም ብቻ ልታመልክ ተጽፎአል” አለው።'),
  ('791294ef-5cb9-599d-a9fc-8fe6c7aefa75', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 9, 9, 'ወደ ኢየሩሳሌምም ወስዶ በቤተ መቅደሱ የማዕዘን ጫፍ ላይ አቆመው፤ እንዲህም አለው፥ “የእግዚአብሔር ልጅ ከሆንህስ አንተ ራስህ ወደ ታች መር ብለህ ውረድ።'),
  ('410eb928-fc21-5354-adb6-38dcb17ddb65', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 10, 10, 'በመንገድህ ይጠብቁህ ዘንድ መላእክትን ስለ አንተ ያዝዛቸዋል፤'),
  ('b575b256-5061-5027-a198-89fcd80e021c', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 11, 11, 'እግርህም በድንጋይ እንዳትሰነካከል በእጃቸው ያነሡሃል” ተብሎ ተጽፎአልና።'),
  ('0c6a3ae5-e083-5339-a467-d4545b237f37', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 12, 12, 'ጌታችን ኢየሱስም መልሶ፥ “ፈጣሪህ እግዚአብሔርን አትፈታተነው” ተብሎአል አለው።'),
  ('4ea5067b-a5ad-5ede-a03a-583d1d44f885', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '80ebfa26-821f-5b84-a6e3-b36b8a07656f', 13, 13, 'ዲያብሎስም በዚህ ሁሉ እርሱን መፈታተኑን ከፈጸመ በኋላ እስከ ጊዜው ከእርሱ ተለየ።'),
  ('1ef934f0-22b4-5918-ac86-c83cc58ea58b', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '86434879-3c51-5e71-a4ee-74c985a5fb7a', 1, 14, 'ጌታችን ኢየሱስም በመንፈስ ቅዱስ ኀይል ተመልሶ ወደ ገሊላ ሄደ፤ ዝናውም በሀገሩ ሁሉ ተሰማ።'),
  ('fc95e86c-aba7-5ce8-a841-8d6001e59e42', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '86434879-3c51-5e71-a4ee-74c985a5fb7a', 2, 15, 'በየምኵራባቸውም ሁሉ ያስተምራቸው ነበር፤ ትምህርቱንም ያደንቁ ነበር፤ ሁሉም ያመሰግኑት ነበር።'),
  ('8cc328ae-52e4-528c-af33-18eb5d18e607', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 1, 16, 'ወደ አደገበት ወደ ናዝሬትም ሄደ፤ በሰንበት ቀንም እንዳስለመደ ወደ ምኵራብ ገባ፤ ሊያነብም ተነሣ።'),
  ('8515be44-b9a4-56b9-a37f-658b79223c77', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 2, 17, 'የነቢዩን የኢሳይያስንም መጽሐፍ ሰጡት፤ መጽሐፉንም በገለጠ ጊዜ እንዲህ የሚል የተጻፈበትን ስፍራ አገኘ።'),
  ('8d5494a4-5f2f-5a06-ad11-a18025e148ab', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 3, 18, '“የእግዚአብሔር መንፈስ በላዬ ነው፤ ስለዚህ ቀብቶ ለድሆች የምሥራችን እነግራቸው ዘንድ፥ ለተማረኩትም ነጻነትን እሰብክላቸው ዘንድ፥ ያዘኑትንም ደስ አሰኛቸው ዘንድ፥ ዕውሮችም ያዩ ዘንድ፥ የተገፉትንም አድናቸው ዘንድ፥ የታሰሩትንም እፈታቸው ዘንድ፥ የቈሰሉትንም አድናቸው ዘንድ፥'),
  ('536a2a0a-1c9c-566a-a14e-e11d060ba3b6', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 4, 19, 'የተመረጠችውንም የእግዚአብሔርን ዓመት እሰብክ ዘንድ ላከኝ።”'),
  ('faf0dd84-cee1-56c3-ab85-51ac2fd166ef', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 5, 20, 'መጽሐፉንም አጥፎ ለተላላኪው ሰጠውና ተቀመጠ፤ በምኲራብም የነበሩት ሁሉ ዐይናቸውን አትኲረው ተመለከቱት።'),
  ('6ddeb024-8c56-58f2-ab2f-88ec37ab2e69', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 6, 21, 'እርሱም፥ “የዚህ የመጽሐፍ ነገር ዛሬ በጆሮአችሁ ደረሰ፤ ተፈጸመም” ይላቸው ጀመር።'),
  ('d23f0684-c069-5980-a585-c6713a572ca5', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 7, 22, 'ሁሉም የንግግሩን መከናወን መሰከሩለት፤ የአንደበቱንም ቅልጥፍና እያደነቁ፥ “ይህ የዮሴፍ ልጅ አይደለምን?” ይሉ ነበር።'),
  ('4eeb3354-b735-5146-a97a-a3660ebe0fef', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 8, 23, 'እርሱም፥ “በውኑ ባለ መድኀኒት ራስህን አድን፤ በቅፍርናሆም ያደረግኸውንና የሰማነውን ሁሉ በዚህም በሀገርህ ደግሞ አድርግ ብላችሁ ይህችን ምሳሌ ትመስሉብኛላችሁ” አላቸው።'),
  ('dcf3a0d1-3fbe-549c-a34d-525927e74750', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 9, 24, 'እንዲህም አላቸው፥ “እውነት እላችኋለሁ፤ ነቢይ በሀገሩ አይከብርም።'),
  ('abac941a-c262-54df-a57e-9d2e2b7b7ed4', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 10, 25, 'እውነት እላችኋለሁ፤ በነቢዩ በኤልያስ ዘመን በምድር ሁሉ ብርቱ ረኃብ እስኪሆን ድረስ ሰማይ ሦስት ዓመት ከስድስት ወር በተዘጋበት ጊዜ ብዙ መበለቶች በእስራኤል ውስጥ ነበሩ።'),
  ('ba68ddbd-eac8-565c-a4c2-2bce47808b02', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 11, 26, 'ኤልያስ የሲዶና ክፍል በምትሆን በስራጵታ ወደምትኖር ወደ አንዲት መበለት ሴት እንጂ ከእነዚህ ወደ አንዲቱ እንኳን አልተላከም።'),
  ('1d8ef159-7899-5c93-a1ec-32abf3170fc8', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 12, 27, 'በነቢዩ በኤልሳዕ ዘመንም ብዙ ለምጻሞች በእስራኤል ውስጥ ነበሩ፤ ነገር ግን ከሶርያዊው ከንዕማን በቀር ከእነዚያ አንድ እንኳን አልነጻም።”'),
  ('faaea861-2e9f-5039-a625-5a960f34c129', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 13, 28, 'በምኵራብም የነበሩት ሁሉ ይህን ሰምተው ተቈጡ።'),
  ('7d46f361-5df7-5340-a629-f8090cf8feb2', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 14, 29, 'ያንጊዜም ተነሥተው ከከተማ ወደ ውጭ አወጡት፤ ገፍተውም ይጥሉት ዘንድ ከተማቸው ተሠርታባት ወደ ነበረች ተራራ ጫፍ ወሰዱት።'),
  ('c4354581-dd85-5fcb-a863-ab472481c0d1', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e4c34d8c-921d-5c76-aa8d-042e92bb02e7', 15, 30, 'እርሱ ግን በመካከላቸው አልፎ ሄደ።'),
  ('63447f11-5170-56d2-a7ff-17c38e2a98a7', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '3d9ab5c7-3f8b-5a86-adb4-ac242ee6b320', 1, 31, 'ወደ ገሊላ ከተማም ወደ ቅፍርናሆም ወረደ፤ በሰንበትም ያስተምራቸው ነበር።'),
  ('22104647-5df2-520b-a7e2-787fd7fc2d72', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', '3d9ab5c7-3f8b-5a86-adb4-ac242ee6b320', 2, 32, 'አነጋገሩም በትእዛዝ ነበርና ትምህርቱን ያደንቁ ነበር።'),
  ('9f483e34-b382-5f62-a122-eeed0ab11108', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e5835fb6-c655-5eef-abcb-395bbe76b0b3', 1, 33, 'በምኵራብም ርኩስ መንፈስ የያዘው አንድ ሰው ነበር፤ በታላቅ ቃልም ጮኾ፦'),
  ('426597c0-f92d-5bc2-abbb-c93a392c63e9', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e5835fb6-c655-5eef-abcb-395bbe76b0b3', 2, 34, '“የናዝሬቱ ኢየሱስ ሆይ፥ ከአንተ ጋር ምን አለን? ያለጊዜአችን ልታጠፋን መጣህን? የእግዚአብሔር ቅዱስ ሆይ፥ አንተ ማን እንደሆንህ ዐውቅሃለሁ” አለ።'),
  ('e306d166-02f1-551e-a5da-5dd192924631', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e5835fb6-c655-5eef-abcb-395bbe76b0b3', 3, 35, 'ጌታችን ኢየሱስም፥ “ዝም በልና ከእርሱ ውጣ” ብሎ ገሠጸው፤ ጋኔኑም በምኵራቡ መካከል ጣለውና ከእርሱ ወጣ፤ ነገር ግን ምንም አልጐዳውም።'),
  ('41243009-0daf-5518-a6ef-9f6363d43207', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e5835fb6-c655-5eef-abcb-395bbe76b0b3', 4, 36, 'ሁሉም ደነገጡ፤ እርስ በርሳቸውም ተነጋገሩ፤ እንዲህም አሉ፥ “ይህ ነገር ምንድን ነው? ክፉዎችን አጋንንት በሥልጣንና በኀይል ያዝዛቸዋልና፥ እነርሱም ይወጣሉና።”'),
  ('c6621dc1-bd40-5802-a5cb-74e266ed361a', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'e5835fb6-c655-5eef-abcb-395bbe76b0b3', 5, 37, 'ዝናውም በዙሪያዉ ባሉ መንደሮች ሁሉ ወጣ፤ ተሰማም።'),
  ('29696410-90b9-5938-a371-95fbdb53b6a6', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 1, 38, 'ከምኵራቡም ወጥቶ ወደ ስምዖን ቤት ገባ፤ የስምዖን አማትም በብርቱ ንዳድ ታማ ነበርና ስለ እርስዋ ነገሩት።'),
  ('89266dcf-539f-5342-ac8d-c6026902d09b', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 2, 39, 'በአጠገብዋም ቁሞ ንዳድዋን ገሠጸውና ተዋት፤ ወዲያውም ተነሥታ አገለገለቻቸው።'),
  ('f13d178c-4cd6-53fe-a7f9-38314a0e05dc', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 3, 40, 'ፀሐይም በገባ ጊዜ ልዩ ልዩ ደዌ ያለባቸውን ድውያን ሁሉ አመጡለት፤ ከእነርሱም በእያንዳንዱ ላይ እጁን ጭኖ ፈወሳቸው።'),
  ('87b0fd39-3e5d-5f05-af75-0f7b8b58c797', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 4, 41, 'ብዙ አጋንንትም፥ “አንተ የእግዚአብሔር ልጅ ክርስቶስ ነህ” እያሉና እየጮሁ ይወጡ ነበር፤ እርሱም ይገሥጻቸው ነበር፤ ክርስቶስም እንደ ሆነ ያውቁ ነበርና እንዲናገሩ አይፈቅድላቸውም ነበር።'),
  ('aa161e27-8958-57db-a237-08f32f22e081', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 5, 42, 'በነጋ ጊዜም ወጥቶ ወደ ምድረ በዳ ሄደ፤ ሕዝቡም እየፈለጉት ወደ እርሱ ሄዱ፤ አልፎአቸው እንዳይሄድም አቆሙት።'),
  ('231dda1c-723b-5a92-a3a5-8646cf089811', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 6, 43, 'እርሱ ግን፥ “ስለዚህ ተልኬአለሁና ለሌሎች ከተሞች ደግሞ ስለ እግዚአብሔር መንግሥት ወንጌል እነግራቸው ዘንድ ይገባኛል” አላቸው።'),
  ('58d0bb08-cfdc-5d72-a513-db48dbe6885b', '4c5c6c4d-675e-5b4c-aec0-8da2c95374ca', 'd0f29ecf-403e-5974-a0fb-bea4ce3b83d9', 7, 44, 'በገሊላ ምኲራቦችም ይሰብክ ነበር።'),
  ('02d0bef9-a051-5558-a84d-373d5fb76fe1', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 1, 1, 'ብዙ ሰዎችም በእርሱ ዘንድ ነበሩ፤ የእግዚአብሔርንም ቃል ይሰሙ ነበር፤ እርሱ ግን በጌንሴሬጥ ባሕር ወደብ ቁሞ ነበር።'),
  ('2ef52bc5-b199-5257-a9a1-da532bab2a44', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 2, 2, 'በባሕሩም ዳር ሁለት ታንኳዎች ቁመው አየ፤ ከእነርሱም ውስጥ ዓሣ አጥማጆች መረባቸውን ሊያጥቡ ወረዱ።'),
  ('6fabf07d-0eae-505b-a3a2-1badd8ebef16', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 3, 3, 'ከሁለቱ ታንኳዎች ወደ አንዲቱ ታንኳ ወጣ፤ ይቺውም ታንኳ የስምዖን ነበረች፤ “ከምድር ጥቂት እልፍ አድርጋት” አለው፤ በታንኳዪቱም ውስጥ ተቀምጦ ሕዝቡን አስተማራቸው።'),
  ('68659995-9693-5fc4-a11f-1eb0aa20c01e', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 4, 4, 'ትምህርቱንም ከፈጸመ በኋላ ስምዖንን፥ “ወደ ጥልቁ ባሕር ፈቀቅ በል፤ መረቦቻችሁንም ለማጥመድ ጣሉ” አለው።'),
  ('923bfaf5-9337-57f8-a3e8-af3a49fefe8a', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 5, 5, 'ስምዖንም መልሶ፥ “መምህር፥ ሌሊቱን ሁሉ ደክመናል፤ የያዝነውም የለም፤ ነገር ግን ስለ አዘዝኸን መረቦቻችንን እንጥላለን” አለው።'),
  ('3d93a528-1483-56f4-ac02-0dbe7805006e', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 6, 6, 'እንዳዘዛቸውም ባደረጉ ጊዜ፥ መረቡ እስኪቀደድ ድረስ ብዙ ዓሣ ተያዘ።'),
  ('ac2b386e-4222-5e09-abb1-cbf79b2e9725', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 7, 7, 'መጥተውም ይረዱአቸው ዘንድ በሌላ ታንኳ የነበሩትን ባልንጀሮቻቸውን ጠሩ፤ መጥተውም እስኪጠልቁ ድረስ ሁለቱን ታንኳዎች ሞሉ።'),
  ('f63e0a1c-0c2a-5b39-aff7-06e85a817c66', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 8, 8, 'ስምዖን ጴጥሮስም ይህን አይቶ ከጌታችን ከኢየሱስ እግር በታች ሰገደና፥ “እኔ ኀጢአተኛ ሰው ነኝና አቤቱ ከእኔ ፈቀቅ በል፤” አለው።'),
  ('0a118c44-177a-5201-a679-79555bbd9e11', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 9, 9, 'እርሱና ከእርሱ ጋር የነበሩት ሁሉ ስለ ተያዘው ዓሣ ተደንቀው ነበርና።'),
  ('a3211f9d-dcde-5526-aec4-2b46f77607ec', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 10, 10, 'እንዲሁም የስምዖን ባልንጀራዎች የነበሩ የዘብዴዎስ ልጆች ያዕቆብና ዮሐንስ ተደነቁ፤ ጌታችን ኢየሱስም ስምዖንን፥ “አትፍራ፤ ከእንግዲህ ወዲህስ ሰውን ታጠምዳለህ” አለው።'),
  ('5d9e0087-5502-5120-a94d-d16e63ec9868', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '751325fc-81e5-5111-acf8-b5fbce7877d0', 11, 11, 'ታንኳዎቻቸውንም ወደ ምድር አወጡና ሁሉን ትተው ተከተሉት።'),
  ('57b220b8-fded-5ebf-a27b-75ad2b42e52b', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '99fdfca2-f67b-5eab-ac0a-0ce45f5d7e2f', 1, 12, 'በአንዲት ከተማ ሳለም ሁለመናው ለምጻም የሆነ ሰው መጣ፤ ጌታችን ኢየሱስንም ባየው ጊዜ በፊቱ ወድቆ ሰገደለትና፥ “አቤቱ ብትወድስ ልታነጻኝ ትችላለህ” እያለ ማለደው።'),
  ('7fea49bb-84e5-5cb2-ae30-2abb222debfb', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '99fdfca2-f67b-5eab-ac0a-0ce45f5d7e2f', 2, 13, 'እጁንም ዘርግቶ ዳሰሰውና፥ “እወዳለሁ ንጻ” አለው፤ ያንጊዜም ለምጹ ለቀቀው።'),
  ('46f335f7-f242-53e4-a9c2-28bbe3869297', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '99fdfca2-f67b-5eab-ac0a-0ce45f5d7e2f', 3, 14, 'ለማንም እንዳይናገር ከለከለው፤ “ነገር ግን ሄደህ ራስህን ለካህን አስመርምር፤ ምስክርም ይሆንባቸው ዘንድ ስለ ነጻህ ሙሴ እንደ አዘዘ መባህን አቅርብ” ብሎ አዘዘው።'),
  ('0a8b1174-599e-50ab-aafc-fe4bc1fdd2e3', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '99fdfca2-f67b-5eab-ac0a-0ce45f5d7e2f', 4, 15, 'ዜናውም በሁሉ ተሰማ፤ ብዙ ሰዎችም ትምህርቱን ሊሰሙ፥ ከደዌአቸውም ሊፈወሱ ይመጡ ነበር።'),
  ('7dadbe33-8e38-5dda-a142-fa37934cdba5', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '99fdfca2-f67b-5eab-ac0a-0ce45f5d7e2f', 5, 16, 'እርሱ ግን ወደ ምድረ በዳ እየወጣ ይጸልይ ነበር።'),
  ('435bb624-7d52-5a51-a6e8-389a04363807', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 1, 17, 'ከዚህም በኋላ፥ ከዕለታት በአንድ ቀን ሲያስተምራቸው እንዲህ ሆነ፤ ከገሊላና ከይሁዳ መንደሮች፥ ከኢየሩሳሌምም የመጡ ፈሪሳውያንና የኦሪት መምህራን ነበሩ፤ እርሱም ይፈውስ ዘንድ የእግዚአብሔር ኀይል ነበረ።'),
  ('2b234a71-dcf7-50b0-a572-c4439c57f205', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 2, 18, 'እነሆ፥ ሰዎች በአልጋ ተሸክመው ሽባ የሆነ ሰው ወደ እርሱ አመጡ፤ እንዲፈውሰውም ወደ እርሱ ሊያስገቡት ወደዱ።'),
  ('4474cbcd-b099-59f4-ae95-c494ebc1747f', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 3, 19, 'ሰውም ተጨናንቆ ነበርና የሚያስገቡበት አጡ፤ ወደ ሰገነትም ወጡ፤ ጣራውንም አፍርሰው ወደ ቤቱ ውስጥ በጌታችን በኢየሱስ ፊት ከነአልጋው አወረዱት።'),
  ('47ebc090-770f-571f-ac28-5f8da48aa871', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 4, 20, 'እምነታቸውንም አይቶ ያን ሰው፥ “ኀጢአትህ ተሰረየልህ” አለው።'),
  ('1dc1cdd5-d532-536f-a7eb-1921e1897301', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 5, 21, 'ጻፎችና ፈሪሳውያንም፥ “የሚሳደብ ይህ ማን ነው? ከአንዱ ከእግዚአብሔር በቀር ኀጢአትን ማስተስረይ ማን ይችላል?” ብለው ያስቡ ጀመር።'),
  ('d78eb364-06e2-56c9-a52d-3cc2cc14aa82', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 6, 22, 'ጌታችን ኢየሱስም የሚያስቡትን ዐወቀባቸውና እንዲህ አላቸው፥ “በልባችሁ ምን ታስባላችሁ?'),
  ('c40f8544-7ff6-5b24-afd5-5addaa562233', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 7, 23, 'ኀጢአትህ ተሰረየልህ ከማለትና ተነሥተህ ሂድ ከማለት ማናቸው ይቀላል?'),
  ('e927b601-33d2-57f2-a116-276371e64e14', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 8, 24, 'ለሰው ልጅ በምድር ላይ ኀጢአትን ያስተሰርይ ዘንድ ሥልጣን እንዳለው እንድታውቁ፤ ያን ሽባ፦ ተነሣና አልጋህን ተሸክመህ ወደ ቤትህ ሂድ ብዬሃለሁ” አለው።'),
  ('c16044da-9e8b-5fcc-ab04-948e0c8ae8ae', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 9, 25, 'ያንጊዜም ተነሥቶ ተኝቶበት የነበረውን አልጋ በፊታቸው ተሸክሞ እግዚአብሔርን እያመሰገነ ወደ ቤቱ ሄደ።'),
  ('6a5946fb-d1ff-52d1-a22c-ef34e352ee47', '988ce8ec-9bf0-5441-aab9-15d099bd876f', '30d8bf26-0654-5662-afc4-4824bfbbb1a8', 10, 26, 'ሁሉም ተደነቁ፤ እግዚአብሔርንም አመሰገኑት፤ እጅግም እየፈሩ፥ “ዛሬ ድንቅ ነገር አየን” አሉ።'),
  ('cb2280cd-545c-560b-a7b3-d11e8c341b9e', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'f610e8cb-2132-5c0d-afd7-76a26e7e1666', 1, 27, 'ከዚህም በኋላ ከዚያ ወጥቶ ሌዊ የሚባል ቀራጭ ሰው በቀረጥ መቀበያው ቦታ ተቀምጦ አየና፥ “ተከተለኝ” አለው።'),
  ('87896c0f-8ce8-5491-acef-94eb5a8185c6', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'f610e8cb-2132-5c0d-afd7-76a26e7e1666', 2, 28, 'ሁሉንም ተወና ተነሥቶ ተከተለው።'),
  ('5226126e-314e-5858-a804-555a5bb97609', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'f610e8cb-2132-5c0d-afd7-76a26e7e1666', 3, 29, 'ሌዊም በቤቱ ታላቅ ግብዣ አደረገለት፤ ብዙ ሰዎችም ከእርሱ ጋር ነበሩ፤ ከእርሱም ጋር ለምሳ ተቀምጠው የነበሩ ቀራጮችና ኀጢአተኞች፥ ሌሎችም ብዙዎች ነበሩ።'),
  ('83dc4475-04dd-5cf7-a735-f81bc06a6607', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'f610e8cb-2132-5c0d-afd7-76a26e7e1666', 4, 30, 'ጻፎችና ፈሪሳውያንም፥ “ከቀራጮችና ከኃጥኣን ጋር ለምን ትበላላችሁ? ትጠጡማላችሁ?” ብለው በደቀ መዛሙርቱ ላይ አንጐራጐሩ።'),
  ('129b0e9c-0857-5723-a6c5-521ac4afa81f', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'f610e8cb-2132-5c0d-afd7-76a26e7e1666', 5, 31, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “ባለ መድኀኒትን በሽተኞች እንጂ ጤነኞች አይሹትም።'),
  ('8d12622c-f286-5383-a485-19f271b5c983', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'f610e8cb-2132-5c0d-afd7-76a26e7e1666', 6, 32, 'ኃጥኣንን ወደ ንስሓ እንጂ ጻድቃንን ልጠራ አልመጣሁም።”'),
  ('89762ff2-5d12-5c5e-a807-b6d509e1a152', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 1, 33, 'እነርሱም፥ “የዮሐንስ ደቀ መዛሙርት ስለምን በብዙ ይጾማሉ? ጸሎትስ ስለምን ያደርጋሉ? የፈሪሳውያን ወገኖች የሆኑትም ስለምን እንዲሁ ያደርጋሉ? ያንተ ደቀ መዛሙርት ግን ለምን ይበላሉ? ይጠጣሉም?” አሉት።'),
  ('0195cb11-3633-5f44-aa45-005284b27fb0', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 2, 34, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “የሙሽራው ሚዜዎች ሙሽራው ከእነርሱ ጋር ሳለ መጾም አይችሉም።'),
  ('ced5f07b-2009-5fc6-a4c2-662e3e7a1dac', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 3, 35, 'ነገር ግን ሙሽራውን ከእነርሱ የሚወስዱበት ቀን ይመጣል፤ ያንጊዜም ይጾማሉ።”'),
  ('1c86febb-2a88-5a94-ab26-4393084ed8e4', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 4, 36, 'በምሳሌም እንዲህ አላቸው፥ “በአሮጌ ልብስ ቀዳዳ ላይ የአዲስ ልብስ እራፊ የሚጥፍ የለም፤ ያለዚያ ግን አዲሱ አሮጌውን ይቀድደዋል፤ አዲሱ እራፊም ከአሮጌው ጋር አይስማማም።'),
  ('b7306b1b-4da0-572f-aa9c-25146f82c2c7', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 5, 37, 'አዲስ ጠጅንም በአሮጌ ረዋት የሚያደርግ የለም፤ ያለዚያ ግን ይቀድደዋል፤ ወይኑም ይፈስሳል፤ ረዋቱም ይቀደዳል።'),
  ('f384558d-cd6d-5832-aaa1-dc8b3276cc9c', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 6, 38, 'ነገር ግን አዲሱን ጠጅ በአዲስ ረዋት ያደርጉታል፤ እርስ በርሳቸውም ይጠባበቃሉ።'),
  ('81e420e0-c280-5486-a439-33eab36269bd', '988ce8ec-9bf0-5441-aab9-15d099bd876f', 'e76435db-5f6e-5539-a884-7f9e7283bb9c', 7, 39, 'የከረመውን የወይን ጠጅ ሊጠጣ ወድዶ አዲሱን የሚሻ የለም፤ የከረመው ይሻላል ይላልና።”'),
  ('a7131664-aefa-5c75-aa8e-a84fee08107b', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '48424fd6-75ed-5a5e-a193-5137a3eed567', 1, 1, 'ከዚህም በኋላ ደግሞ ጌታችን ኢየሱስ በሰንበት ቀን በእርሻ መካከል ሄደ፤ ደቀ መዛሙርቱም እሸት ቈርጠው በእጃቸው እያሹ በሉ።'),
  ('a27fed83-0981-5ada-a068-ae0286570e47', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '48424fd6-75ed-5a5e-a193-5137a3eed567', 2, 2, 'ፈሪሳውያንም፥ “በሰንበት ሊደረግ የማይገባውን ለምን ታደርጋላችሁ?” አሉአቸው።'),
  ('cc197a91-27c9-5409-aaa2-41d0656b2b4a', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '48424fd6-75ed-5a5e-a193-5137a3eed567', 3, 3, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እርሱና ከእርሱ ጋር የነበሩትም በተራቡ ጊዜ ዳዊት ያደረገውን አላነበባችሁምን?'),
  ('7a288b2b-da9e-5cda-a1ea-dff19395e7d8', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '48424fd6-75ed-5a5e-a193-5137a3eed567', 4, 4, 'ወደ ቤተ እግዚአብሔር እንደ ገባ፥ ከካህናቱም ብቻ በቀር ሊበሉት የማይገባውን የመሥዋዕቱን ኅብስት ወስዶ እንደ በላ፥ አብረውት ለነበሩትም እንደ ሰጣቸው አላነበባችሁምን?'),
  ('17fafe53-8977-5ac5-add3-3d8623c82881', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '48424fd6-75ed-5a5e-a193-5137a3eed567', 5, 5, 'የሰው ልጅ ለሰንበት ጌታዋ ነው” አላቸው።'),
  ('f0b5aace-bca3-55d4-addf-363201a66268', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '35a303fb-70b6-5196-a56a-defca74f2de2', 1, 6, 'ከዚህም በኋላ በሌላይቱ ሰንበት ወደ ምኵራቡ ገባና አስተማራቸው፤ በዚያም ቀኝ እጁ የሰለለች ሰው ነበረ።'),
  ('fad4bfe6-1e48-55fa-abe9-f039f191dc42', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '35a303fb-70b6-5196-a56a-defca74f2de2', 2, 7, 'ጻፎችና ፈሪሳውያንም የሚከሱበት ምክንያት ያገኙ ዘንድ፥ በሰንበት ይፈውሰው እንደ ሆነ ብለው ይጠባበቁት ነበር።'),
  ('f092a901-d77e-5f76-ae6a-bcb8cdf16001', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '35a303fb-70b6-5196-a56a-defca74f2de2', 3, 8, 'እርሱ ግን ዐሳባቸውን ያውቅባቸው ነበርና እጁ የሰለለችውን ሰው፥ “ተነሥተህ በመካከል ቁም” አለው፤ ተነሥቶም ቆመ።'),
  ('de78cf6b-009d-52eb-a0f0-88cbc4166d3b', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '35a303fb-70b6-5196-a56a-defca74f2de2', 4, 9, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “እጠይቃችኋለሁ፤ በሰንበት ሊደረግ የሚገባው ምንድነው? መልካም መሥራት ነውን? ወይስ ክፉ መሥራት? ነፍስን ማዳን ነውን? ወይስ መግደል?”'),
  ('28191766-bd0b-5c01-a61b-5ce150a9606c', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '35a303fb-70b6-5196-a56a-defca74f2de2', 5, 10, 'እነርሱም ዝም አሉ፤ ወደ እነርሱም ዙሮ ከተመለከተ በኋላ፦ ያን ሰው፥ “እጅህን ዘርጋ” አለው፤ ሰውዬውም ዘረጋት፤ እጁም ዳነችና እንደ ሁለተኛይቱ ሆነች።'),
  ('63e56fe8-cfc0-53b7-a8b4-f458406af54c', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '35a303fb-70b6-5196-a56a-defca74f2de2', 6, 11, 'እነርሱ ግን፥ እጅግ ተቈጡ፤ በጌታችን በኢየሱስም ምን እንድሚያደርጉበት እርስ በርሳቸው ተማከሩ።'),
  ('68c3a551-2ccb-5602-a7c1-ad562b00110c', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 1, 12, 'በዚያም ወራት ጌታችን ኢየሱስ ሊጸልይ ወደ ተራራ ወጣ፤ ሌሊቱን ሁሉ ወደ እግዚአብሔር ይጸልይ ነበር፤'),
  ('9475ac9d-9da9-565a-a86c-818e67fdfd4c', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 2, 13, 'ሲነጋም ደቀ መዛሙርቱን ወደ እርሱ ጠራቸው፤ ከውስጣቸውም ዐሥራ ሁለቱን መረጠ፤ ሐዋርያት ብሎም ሰየማቸው።'),
  ('5455bc0b-ddef-5c16-ae82-f2916d393ee6', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 3, 14, 'እነርሱም እነዚህ ናቸው፦ ጴጥሮስ የተባለው ስምዖን፥ ወንድሙም እንድርያስ፥ ያዕቆብና ዮሐንስ፥ ፊልጶስና በርተሎሜዎስ።'),
  ('16646114-ebad-5122-a74c-a00f26ec23d2', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 4, 15, 'ማቴዎስና ቶማስ፥ የእልፍዮስ ልጅ ያዕቆብና ቀናዒ የሚባለው ስምዖን።'),
  ('a7493da4-7a33-5722-ab3a-ab48132f2ac8', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 5, 16, 'የያዕቆብ ወንድም ይሁዳ፥ የከዳውና አሳልፎ የሰጠው ያስቆሮቱ ሰው ይሁዳም ናቸው።'),
  ('826e00b7-2255-5f1b-a409-b7cc9b2bbdbe', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 6, 17, 'ከእነርሱም ጋር ወርዶ በሰፊ ቦታ ቆመ፤ ከደቀ መዛሙርቱም ወገን ብዙ ሰዎች ነበሩ፤ ከመላው ይሁዳና ከኢየሩሳሌም፥ ከጢሮስና ከሲዶና ባሕር ዳርቻ ትምህርቱን ሊሰሙ፥ ከደዌአቸውም ሊፈወሱ የመጡት ከሕዝቡ ወገን እጅግ ብዙዎች ነበሩ።'),
  ('0b08676a-656a-5a3b-acfa-1e123e81cd44', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 7, 18, 'ክፉዎች አጋንንት ያደሩባቸውም ይፈወሱ ነበር።'),
  ('e1cfd7b5-56c9-5e93-a202-20415017d995', '35732580-957b-58ec-aa09-1c73c4a5a7dc', '53325a2d-c620-51f3-a3da-acbfb9a1298b', 8, 19, 'ሕዝቡ ሁሉ ሊዳስሱት ይሹ ነበር፤ ኀይል ከእርሱ ይወጣ ነበርና፥ ሁሉንም ይፈውሳቸው ነበር።'),
  ('c231f031-4b1b-54e0-ab4f-0b0b940ec6fc', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 1, 20, 'እርሱም ወደ ደቀ መዛሙርቱ ዐይኖቹን አንሥቶ እንዲህ አላቸው፥ “እናንተ ድሆች፥ ብፁዓን ናችሁ፤ የእግዚአብሔር መንግሥት የእናንተ ናትና።'),
  ('9cba74df-6800-51ae-ab40-47b50dea2f78', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 2, 21, 'ዛሬ የምትራቡ፥ ብፁዓን ናችሁ፤ ትጠግባላችሁና፤ ዛሬ የምታለቅሱ፥ ብፁዓን ናችሁ፤ ትስቃላችሁና።'),
  ('1ff3b5c9-ee44-59d0-a4bc-c9645182006f', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 3, 22, 'ሰዎች ስለ ሰው ልጅ ቢጠሉአችሁ፥ ከሰው ለይተው ቢአሳድዱአችሁ፥ ቢሰድቡአችሁ፥ ክፉ ስምም ቢአወጡላችሁ ብፁዓን ናችሁ።'),
  ('f61a6cdf-dfd9-53eb-ae76-daff0162294b', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 4, 23, 'ያንጊዜ ደስ ይበላችሁ፤ በደስታም ዝለሉ፤ ዋጋችሁ በሰማይ ብዙ ነውና፤ አባቶቻቸውም ነቢያትን እንዲሁ አድርገዋቸው ነበርና።'),
  ('0e0fe7cb-7a0a-51e7-a188-79d8d9b73d00', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 5, 24, 'ነገር ግን እናንተ ባለጠጎች፥ ወዮላችሁ፥ ደስታችሁን ጨርሳችኋልና።'),
  ('df6588cf-8266-5a85-a19b-9c60ae54f69e', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 6, 25, 'ዛሬ ለምትጠግቡ፥ ወዮላችሁ፥ ትራባላችሁና፤ ዛሬ ለምትስቁም ወዮላችሁ፥ ታዝናላችሁና፤ ታለቅሳላችሁምና።'),
  ('81910cfd-06be-5e23-a22c-d4c59c38ce45', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 7, 26, 'ሰዎች ሁሉ ስለ እናንተ መልካሙን ነገር ቢናገሩላችሁ ወዮላችሁ፥ አባቶቻቸው ለሐሰተኞች ነቢያት እንዲህ ያደርጉ ነበርና።'),
  ('033321f7-c1e7-557b-af7e-9b086cb305b9', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 8, 27, '“ለምትሰሙኝ ለእናንተ ግን እንዲህ እላችኋለሁ፦ ጠላቶቻችሁን ውደዱ፤ ለሚጠሉአችሁም መልካም አድርጉ።'),
  ('90ecb536-d635-523a-a585-fa61c73e3218', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 9, 28, 'የሚረግሙአችሁን መርቁአቸው፤ ለሚበድሉአችሁም ጸልዩላቸው።'),
  ('ab234d03-2d2b-5837-a2b9-5d0afe99cbfc', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 10, 29, 'ጕንጭህን ለሚመታህም ሁለተኛይቱን ስጠው፤ መጐናጸፊያህን ለሚወስድም ቀሚስህን ደግሞ አትከልክለው።'),
  ('cb267395-1fc6-5852-a5d2-f929396b36e1', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 11, 30, 'ለሚለምንህም ሁሉ ስጥ፤ ገንዘብህን የሚወስደውንም እንዲመልስ አትጠይቀው።'),
  ('2304cfc7-3c8e-5e5e-ab87-d16b96437486', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 12, 31, 'ሰዎች ሊያደርጉላችሁ እንደምትወዱትም እንዲሁ እናንተ አድርጉላቸው።'),
  ('393a5908-052b-5c86-aa76-64338683230c', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 13, 32, 'የሚወድዱአችሁን ብቻ ብትወዱማ እንግዲህ ዋጋችሁ ምንድን ነው? ይህንስ ኃጥኣንም ያደርጋሉ፤ የሚወድዳቸውንም ይወድዳሉ።'),
  ('7204b8e7-6750-58dc-ae03-f50547a37230', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 14, 33, 'በጎ ለሚያደርጉላችሁ በጎ ብታደርጉ እንግዲህ ዋጋችሁ ምንድን ነው? እንዲህስ ኃጥኣንም ያደርጋሉ።'),
  ('4088a8d1-5fe0-58d4-a371-b56357bcc30a', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 15, 34, 'እንዲከፍላችሁ ተስፋ ለምታደርጉት ብታበድሩ እንግዲህ ዋጋችሁ ምንድን ነው? ኃጥኣንም በአበደሩት ልክ ይከፍሉአቸው ዘንድ ለኃጥኣን ያበድራሉና።'),
  ('3308f555-1e1c-57fd-a227-1d8914fed778', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 16, 35, 'አሁንም ጠላቶቻችሁን ውደዱ፤ መልካምም አድርጉላቸው፤ እንዲመልሱላችሁ ተስፋ ሳታደርጉ አበድሩ፤ ዋጋችሁም ብዙ ይሆናል፤ የልዑልም ልጆች ትሆናላችሁ፤ እርሱ ለበጎዎችና ለክፉዎች ቸር ነውና።'),
  ('0618c44a-f3e6-52a4-a80a-0ae006270722', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 17, 36, 'ሰማያዊ አባታችሁ የሚራራ እንደ ሆነ እናንተም የምትራሩ ሁኑ።'),
  ('49160f63-1be1-55bb-a29c-7906b95da832', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 18, 37, 'አትፍረዱ፥ አይፈረድባችሁምም፤ አትበድሉ፥ አይበድሉአችሁምም፤ ይቅር በሉ፥ ይቅርም ይሉአችኋል።'),
  ('457d8729-d5c6-570c-ac6d-8b8cbaf456af', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 19, 38, 'ስጡ፥ ይሰጣችኋልም፤ የሞላና የበዛ፥ የተትረፈረፈም መልካም መስፈሪያ በዕቅፋችሁ ይሰጡአችኋል፤ በሰፈራችሁበትም መስፈሪያ ይሰፍሩላችኋል።”'),
  ('5bcb106e-e19a-5d94-a116-f06745ba784d', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 20, 39, 'ምሳሌም መሰለላቸውና እንዲህ አላቸው፥ “ዕውር ዕውርን ሊመራ ይችላልን? ሁለቱስ በጕድጓድ ውስጥ ይወድቁ የለምን?'),
  ('dbf74eb8-05ab-5344-a5de-2c6abd8c1dec', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 21, 40, 'ከመምህሩ የሚበልጥ ደቀ መዝሙር የለም፤ ለሁሉም መጠኑ እንደ መምህሩ ይሆናል።'),
  ('5e4b87e2-b9b8-5fba-acd0-610b0f569181', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 22, 41, 'በወንድምህ ዐይን ውስጥ ያለውን ጕድፍ ለምን ታያለህ? በዐይንህ ውስጥ ያለውን ምሰሶ አታይምን?'),
  ('fe469a82-167f-5f2e-ade3-7950eaa3ed32', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 23, 42, 'ወንድምህንም፦ ወንድሜ ሆይ፥ ታገሥ፤ በዐይንህ ያለውን ጕድፍ ላውጣልህ ልትለው እንደምን ትችላለህ? አንተ ግን በዐይንህ ውስጥ ያለውን ምሰሶ አታይም፤ አንተ ግብዝ፥ አስቀድሞ ከዐይንህ ምሰሶውን አውጣ፤ ከዚህ በኋላ በባልንጀራህ ዐይን ውስጥ ያለውን ጕድፍ ታወጣ ዘንድ አጥርተህ ታያለህ።'),
  ('31812fde-bdee-53c9-a970-4168c1086ba7', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 24, 43, 'ክፉ ፍሬን የሚያፈራ መልካም ዛፍ የለም፤ መልካም ፍሬ የሚያፈራ ክፉ ዛፍም የለም።'),
  ('a4739260-852e-50e4-a11d-1f375409039c', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 25, 44, 'ዛፍ ሁሉ ከፍሬው ይታወቃል፤ ከእሾህ በለስን አይለቅሙም፤ ከደንደርም ወይንን አይለቅሙም።'),
  ('1576c827-80aa-5e91-a18a-b9df8ccf44bd', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 26, 45, 'መልካም ሰው ከልቡ መልካም መዝገብ መልካምን ያወጣል፤ ክፉ ሰውም ከልቡ ክፉ መዝገብ ክፉ ነገርን ያወጣል፤ ከልብ የተረፈውን አፍ ይናገራልና።'),
  ('894ee59b-a5ac-5890-a7d7-661aea350255', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 27, 46, '“ለምን አቤቱ፥ አቤቱ፥ ትሉኛላችሁ? የምላችሁንም አታደርጉም።'),
  ('bad164ef-9834-5ab9-a475-cc99fd7b95dc', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 28, 47, 'ወደ እኔ የሚመጣና ቃሌን ሰምቶ የሚያደርገውም ሁሉ የሚመስለውን አሳያችኋለሁ።'),
  ('a7dd0b91-6ce1-531c-a54e-9f9bdb7785f0', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 29, 48, 'መሠረቱን አጥልቆ ቈፍሮ የመሠረተና ቤቱን በዐለት ላይ የሠራ ሰውን ይመስላል፤ ብዙ ፈሳሾች በመጡ ጊዜ ጎርፎች ያን ቤት ገፉት፤ ሊያነዋውጡትም አልቻሉም፤ በዐለት ተሠርቶአልና።'),
  ('3748d6ef-2b03-541f-a0dd-658ee0239451', '35732580-957b-58ec-aa09-1c73c4a5a7dc', 'e774b26e-c6f3-5491-a42e-bfedd93941d8', 30, 49, 'ቃሌን ሰምቶ የማያደርገው ሰው ግን ቤቱን ያለ መሠረት በአፈር ላይ የሠራ ሰውን ይመስላል፤ ጎርፎች ገፉት፤ ወዲያውኑም ወደቀ፤ የዚያም ቤት አወዳደቁ ታላቅ ሆነ።”'),
  ('e3bde3be-f128-5fcc-aa84-6f813a730888', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 1, 1, 'ለሕዝቡም ቃሉን ነግሮ ከፈጸመ በኋላ ወደ ቅፍርናሆም ገባ።'),
  ('0e9a831c-cdee-53f2-a8fe-37bf8a7c33d2', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 2, 2, 'አንድ የመቶ አለቃም ነበረ፤ አገልጋዩም ታሞ ሊሞት ቀርቦ ነበር፤ እርሱም በእርሱ ዘንድ የተወደደ ነበር።'),
  ('d33acfde-814a-5cea-afc1-a6593bb1bcc8', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 3, 3, 'የጌታችን የኢየሱስንም ነገር በሰማ ጊዜ፥ መጥቶ አገልጋዩን እንዲያድንለት ይማልዱት ዘንድ የአይሁድን ሽማግሎች ወደ እርሱ ላከ።'),
  ('57d79786-2255-530d-ac7e-58824ce3e22a', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 4, 4, 'ወደ ጌታችን ወደ ኢየሱስም መጥተው ማለዱት፤ እንዲህም አሉት፥ “ፈጥነህ ውረድ፤ ይህን ልታደርግለት ይገባዋልና።'),
  ('60cab8e0-a144-58df-ae37-f485b3668162', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 5, 5, 'እርሱ ወገናችንን ይወዳልና፤ ምኵራባችንንም ሠርቶልናልና።”'),
  ('e2a63889-7568-5592-a6ed-0ff96854dc85', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 6, 6, 'ጌታችን ኢየሱስም ከእነርሱ ጋር ሄደ፤ ወደ ቤቱም በቀረበ ጊዜ፥ የመቶ አለቃዉ ወዳጆቹን እንዲህ ብሎ ላከ፥ “አቤቱ፥ አትድከም፤ ከቤቴ ጣራ በታች ልትገባ አይገባኝምና።'),
  ('970a999b-0967-5144-aa68-b0c2590cf5d8', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 7, 7, 'እኔም ወደ አንተ ልመጣ አይገባኝም፤ ነገር ግን በቃልህ እዘዝ፤ ብላቴናዬም ይድናል።'),
  ('ab9dec66-c1fa-53c0-ab5a-969f4fab23a6', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 8, 8, 'እኔም እኮ ገዢ ሰው ነኝ፤ ወታደሮችም አሉኝ፤ አንዱን ሂድ ብለው ይሄዳል፤ ሌላውንም ና ብለው ይመጣል፤ አገልጋዬንም እንዲህ አድርግ ብለው ያደርጋል።”'),
  ('59d12754-4379-5a75-a373-70d1e74a58af', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 9, 9, 'ጌታችን ኢየሱስም ይህን ከእርሱ በሰማ ጊዜ አደነቀው፤ ዘወር ብሎም ይከተሉት ለነበሩት ሕዝብ፥ “እላችኋለሁ፥ በእስራኤልስ እንኳ እንዲህ ያለ እምነት ያለው ሰው አላገኘሁም” አላቸው።'),
  ('52fd5fb2-d400-5a8e-a204-65acab55d609', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '5f78e541-ef03-5846-af1b-7dd1d0e2d72c', 10, 10, 'የተላኩትም በተመለሱ ጊዜ ብላቴናውን ድኖ አገኙት።'),
  ('e76081b2-d48b-576d-a5e9-34761e8fa52b', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 1, 11, 'በማግሥቱም ናይን ወደምትባል ወደ አንዲት ከተማ ሄደ፤ ደቀ መዛሙርቱም ብዙ ሕዝብም አብረውት ሄዱ።'),
  ('41b24f71-ac42-541a-a04d-4c6bb1c94571', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 2, 12, 'ወደ ከተማው በር በደረሰ ጊዜም እነሆ፥ ያንዲት መበለት ሴት ልጅ ሙቶ ሬሳውን ተሸክመው ሲሄዱ አገኘ፤ ይኸውም ለእናቱ አንድ ነበረ፤ ብዙዎችም የከተማ ሰዎች አብረዋት ነበሩ።'),
  ('8d7b85da-279c-5986-a746-efaca8b76d76', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 3, 13, 'ጌታችንም በአያት ጊዜ አዘነላትና፥ “አታልቅሺ” አላት።'),
  ('e9c2638d-5e11-59b8-ae4f-6655f4e4a9f0', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 4, 14, 'ቀርቦም ቃሬዛውን ያዘ፤ የተሸከሙትም ቆሙ፤ እርሱም፥ “አንተ ጐበዝ ተነሥ እልሃለሁ” አለው።'),
  ('dede9dd6-e2aa-5678-a392-96ea92a8db07', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 5, 15, 'የሞተውም ተነሥቶ ተቀመጠ፤ መናገርም ጀመረ፤ ለእናቱም ሰጣት።'),
  ('cb078c4d-7c95-52fd-afd4-4e6f755c10db', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 6, 16, 'ሁሉም ፈሩ፤ እግዚአብሔርንም አመሰገኑ፤ እንዲህም አሉ፥ “ታላቅ ነቢይ ተነሣልን፤ እግዚአብሔር ሕዝቡን ጐብኝቶአልና።”'),
  ('236a153a-8f3d-576e-a994-75a878f556c5', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '655235dc-f992-5eeb-aada-75cc42c613a4', 7, 17, 'ይህም የእርሱ ዜና በይሁዳ ሀገሮች ሁሉና በአውራጃዋ ሁሉ ተሰማ።'),
  ('975fab67-9823-5bb9-aa8b-25df870f89ba', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'da44f64e-0187-5c78-afee-7b99fa23101a', 1, 18, 'ይህንም ሁሉ ደቀ መዝሙርቱ ለዮሐንስ ነገሩት።'),
  ('c3005a7e-8311-588a-a843-95f3ed63494e', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'da44f64e-0187-5c78-afee-7b99fa23101a', 2, 19, 'ዮሐንስም ከደቀ መዛሙርቱ ሁለቱን ጠርቶ፥ “የሚመጣው አንተ ነህን? ወይስ ተስፋ የምናደርገው ሌላ አለ?” ብሎ ወደ ጌታችን ወደ ኢየሱስ ላካቸው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5e626b90-1136-5e4e-aa26-66552842f7ed', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'da44f64e-0187-5c78-afee-7b99fa23101a', 3, 20, 'መልእክተኞችም ወደ እርሱ ደርሰው፥ “የሚመጣው አንተ ነህን? ወይስ ተስፋ የምናደርገው ሌላ አለ? ብሎ መጥምቁ ዮሐንስ ወደ አንተ ልኮናል” አሉት።'),
  ('c7dcb005-7ea4-55f7-ab3b-80a568867c4f', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'da44f64e-0187-5c78-afee-7b99fa23101a', 4, 21, 'ያንጊዜም ብዙዎችን ከደዌአቸውና ከሕመማቸው ከክፉዎች አጋንንትም ፈወሳቸው፤ ለብዙዎች ዕውራንም እንዲያዩ ብርሃንን ሰጣቸው።'),
  ('18824202-bb87-5ae4-a2db-0730c6859185', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'da44f64e-0187-5c78-afee-7b99fa23101a', 5, 22, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “ሄዳችሁ ያያችሁትንና የሰማችሁትን ለዮሐንስ ንገሩት፤ ዕውሮች ያያሉ፤ አንካሶችም ይሄዳሉ፤ ለምጻሞችም ይነጻሉ፤ ደንቆሮችም ይሰማሉ፤ ሙታንም ይነሣሉ፤ ለድሆችም ወንጌል ይሰበካል።'),
  ('c040ac3e-b96b-5c76-afc4-8e28df21b3b6', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'da44f64e-0187-5c78-afee-7b99fa23101a', 6, 23, 'በእኔም የማይሰናከል ብፁዕ ነው።”'),
  ('86c77966-9879-58f9-a5f9-d2d9a1f15147', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 1, 24, 'የዮሐንስ ደቀ መዛሙርትም ከሄዱ በኋላ ለሕዝቡ ስለ መጥምቁ ዮሐንስ እንዲህ ይላቸው ጀመር፥ “ምን ልታዩ ወደ ምድረ በዳ ወጣችሁ? ከነፋስ የተነሣ የሚወዛወዝ ሸንበቆን ነውን?'),
  ('73ddb32a-3970-52dc-a8fc-a48d7ce2b04a', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 2, 25, 'ወይስ ምን ልታዩ ወጥታችኋል? ቀጭን ልብስ የለበሰውን ሰው ነውን? እነሆ፥ በክብር ልብስ ያጌጡስ በነገሥታት ቤት አሉ።'),
  ('f24b0006-0841-5e41-a476-76bb4e9a3655', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 3, 26, 'ወይስ ምን ልታዩ ወጥታችኋል? ነቢይን ነውን? አዎን፥ እላችኋለሁ፤ ከነቢይም ይበልጣል።'),
  ('45ab4a4c-03c9-5771-ab8a-44ee64bbad25', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 4, 27, 'እነሆ፥ መንገድህን በፊትህ የሚጠርግ መልእክተኛዬን በፊትህ እልካለሁ፥ ተብሎ ስለ እርሱ የተጻፈለት ይህ ነው።'),
  ('6e3d76dd-56ce-5dfb-af9f-3591a483132b', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 5, 28, 'እውነት እላችኋለሁ፤ ሴቶች ከወለዱአቸው መካከል ከመጥምቁ ዮሐንስ የሚበልጥ ማንም አልተነሣም፤ በእግዚአብሔር መንግሥት ግን የሚያንሰው ይበልጠዋል።”'),
  ('e9d92e84-1cf6-51ef-aea5-619647cc380a', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 6, 29, 'ሕዝቡም ሁሉ ቀራጮችም በሰሙ ጊዜ እግዚአብሔርን ጻድቅ ነው አሉት፤ የዮሐንስን ጥምቀት ተጠምቀው ነበርና።'),
  ('02f6faef-6bde-5179-a7a2-546e6e073683', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 7, 30, 'ፈሪሳውያንና የሕግ ጻፎች ግን የእግዚአብሔርን ትእዛዝ ተቃወሙ፤ በእርሱ አልተጠመቁምና።'),
  ('d6f961a8-95e2-5835-a265-5e156321ca9e', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 8, 31, '“እንግዲህ የዚችን ትውልድ ሰዎች በምን እመስላቸዋለሁ? ማንንስ ይመስላሉ?'),
  ('aeb73647-4f2c-506e-a214-6a9631d0f51a', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 9, 32, 'በገበያ ተቀምጠው ባልንጀሮቻቸውን ጠርተው፥ “አቀነቀንላችሁ፥ አልዘፈናችሁምም፤ ሙሾም አወጣንላችሁ፥ አላለቀሳችሁምም የሚሉአቸው ልጆችን ይመስላሉ።'),
  ('4b9cb040-7beb-545d-a99f-3a840d382c53', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 10, 33, 'መጥምቁ ዮሐንስ እህል ሳይበላ ወይንም ሳይጠጣ መጥቶ ነበርና ጋኔን አለበት አላችሁት።'),
  ('04a5f4d9-9cc2-51fc-afe3-e23996d2298b', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 11, 34, 'የሰው ልጅም እየበላና እየጠጣ መጣ፤ እናንተ ግን እነሆ፥ በላተኛና ወይን ጠጪ ሰው፥ የኃጥኣንና የቀራጮች ወዳጅ አላችሁት።'),
  ('e3d1ad33-a397-51f8-ae3d-f7de27f37a85', '4dec4139-43d5-5c44-a877-d6a16e061a3b', '4f2ce0a2-4405-5b10-a224-e74327807b93', 12, 35, 'ጥበብም ከልጆችዋ ሁሉ ጸደቀች።”'),
  ('a12ef715-4659-5b25-a37b-ae2d51737aa3', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 1, 36, 'ከፈሪሳውያንም አንዱ በእርሱ ዘንድ ምሳ እንዲበላ ለመነው፤ ወደ ፈሪሳዊውም ቤት ገብቶ በማዕድ ተቀመጠ።'),
  ('b5f4ae0a-e9e5-52dc-aac4-279226700599', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 2, 37, 'እነሆ፥ ከዚያች ከተማ ሰዎችም አንዲት ኀጢአተኛ ሴት በፈሪሳዊው ቤት በማዕድ እንደተቀመጠ ዐውቃ ሽቱ የሞላበት የአልባስጥሮስ ቢልቃጥ ገዝታ መጣች።'),
  ('3ee5c495-0730-542d-a94d-4b3f575d65d7', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 3, 38, 'በስተኋላውም በእግሮቹ አጠገብ ቆማ አለቀሰች፤ እግሮቹንም በእንባዋ ታርስ ነበር፥ በራስ ጠጕርዋም እግሮቹን ታብሰውና ትስመው፥ ሽቱም ትቀባው ነበር።'),
  ('41d6d53b-3c5f-5c53-ad18-640faa2e4083', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 4, 39, 'የጠራው ፈሪሳዊም ባየ ጊዜ በልቡ ዐሰበ፤ እንዲህም አለ፥ “ይህስ ነቢይ ቢሆን ኖሮ ይህቺ የምትዳስሰው ሴት ማን እንደ ሆነች፥ እንዴትስ እንደ ነበረች ባላወቀም ነበርን? ኀጢአተኛ ናትና።”'),
  ('4149b66a-451c-5e68-a771-c8edadf7f710', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 5, 40, 'ጌታችን ኢየሱስም መልሶ፥ “ስምዖን ሆይ፥ የምነግርህ ነገር አለኝ” አለው፤ እርሱም፥ “መምህር ሆይ፥ ተናገር” አለው።'),
  ('95a70693-88e2-5d9b-a70f-18f2acc2136b', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 6, 41, 'እርሱም እንዲህ አለው፥ “ለአንድ አበዳሪ ሁለት ባለ ዕዳዎች ነበሩት፤ በአንዱ አምስት መቶ ዲናር ነበረበት፤ በሁለተኛውም አምሳ።'),
  ('954b3a7d-d658-537a-a753-77b9c2c547db', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 7, 42, 'የሚከፍሉትም ባጡ ጊዜ ለሁለቱም ተወላቸው፤ እንግዲህ ከሁለቱ አብልጦ ሊወደው የሚገባው ማንኛው ነው?”'),
  ('9bc1164b-e569-5cab-a204-6ca90af04aeb', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 8, 43, 'ስምዖንም መልሶ፥ “ብዙውን የተወለት ነው እላለሁ” አለው፤ እርሱም፥ “መልካም ፈረድህ” አለው።'),
  ('e66f8b9c-136d-5df1-a0c6-c0f9e58c4901', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 9, 44, 'ወደ ሴቲቱም ዘወር ብሎ ስምዖንን እንዲህ አለው፥ “ይህቺን ሴት ታያታለህን? እኔ ወደ ቤትህ ገባሁ፤ ለእግሮች ውኃ ስንኳ አልሰጠኸኝም፤ እርስዋ ግን አልቅሳ በእንባዋ እግሬን አራሰች፤ በጠጕርዋም አበሰች።'),
  ('6e1625f4-29a5-5890-a5d7-5c8b045bfd85', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 10, 45, 'አንተስ ሰላምታ አልሰጠኸኝም፤ እርስዋ ግን ከገባሁ ጀምሮ እግሬን ከመሳም አላቋረጠችም።'),
  ('26165e51-f752-5b5c-a288-7d19e13d46b5', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 11, 46, 'አንተ ራሴን እንኳ ዘይት አልቀባኸኝም፤ እርስዋ ግን እግሬን ሽቱ ቀባችኝ።'),
  ('23a3d955-cea7-5cc8-af63-1ab0bf63c3f9', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 12, 47, 'ስለዚህም እልሃለሁ፤ ብዙ ኀጢኣቷ ተሰርዮላታል፤ በብዙ ወድዳለችና፤ ጥቂት የሚወድድ ጥቂት ይሰረይለታል፤ ብዙ የሚወድድም ብዙ ይሰረይለታል።”'),
  ('82998659-ca3e-5509-a756-ba0458b78d0d', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 13, 48, 'ሴቲቱንም፥ “ኀጢኣትሽ ተሰረየልሽ” አላት።'),
  ('199c46dc-edc5-532a-af42-68e782417750', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 14, 49, 'በማዕዱ የተቀመጡትም እርስ በርሳቸው፥ “ኀጢአትን የሚያስተሰርይ ይህ ማነው?” ይሉ ጀመር።'),
  ('90dc74b0-c9f1-50c4-a6e3-82fdfa77ac6d', '4dec4139-43d5-5c44-a877-d6a16e061a3b', 'fa42fc08-9d2c-519f-ae8b-3121fc45f037', 15, 50, 'ሴቲቱንም አላት፥ “እምነትሽ አድኖሻል፤ በሰላም ሂጂ።”'),
  ('27cd9c89-8414-56b4-a865-253b4f41ae84', '0378d31f-7732-5eab-aa41-63c279ed0181', '02d946bf-09bc-58fa-a5a3-326dabbe44b6', 1, 1, 'ከዚህም በኋላ ጌታችን ኢየሱስ በየከተማዉና በየመንደሩ ተመላለሰ፤ የእግዚአብሔርንም መንግሥት ሰበከላቸው፤ አስተማራቸውም፤ ዐሥራ ሁለቱ ደቀ መዛሙርትም ከእርሱ ጋር ነበሩ።'),
  ('de27d04e-b91b-55c9-ab0c-712e8b58483b', '0378d31f-7732-5eab-aa41-63c279ed0181', '02d946bf-09bc-58fa-a5a3-326dabbe44b6', 2, 2, 'ከክፉዎች አጋንንትና ከደዌያቸው ያዳናቸው ሴቶችም አብረውት ነበሩ። እነርሱም፦ መግደላዊት የምትባለው ሰባት አጋንንት የወጡላት ማርያም፥'),
  ('310d206f-2cbd-5fce-a616-97148dcb1365', '0378d31f-7732-5eab-aa41-63c279ed0181', '02d946bf-09bc-58fa-a5a3-326dabbe44b6', 3, 3, 'የሄሮድስ አዛዥ የነበረው የኩዛ ሚስት ዮሐና፥ ሶስናም፥ በገንዘባቸው ያገለግሉት የነበሩ ብዙዎች ሌሎችም ነበሩ።'),
  ('785bd612-d8b3-56b9-ad5a-bf6de6e06176', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 1, 4, 'ሕዝቡም ሁሉ፥ ከየከተማዉም ሁሉ ወደ እርሱ የመጡት ሲያዳምጡት እንዲህ ያለ ምሳሌ ነገራቸው።'),
  ('1d4aeabc-8f38-5316-a29e-6fb09fbc13ae', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 2, 5, '“ዘሪ ዘሩን ሊዘራ ወጣ፤ ሲዘራም አንዳንዱ በመንገድ ወደቀና ተረገጠ፤ የሰማይ ወፎችም በሉት።'),
  ('8357194a-6c1a-5bba-a456-6fc448add804', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 3, 6, 'ሌላውም በጭንጫ መሬት ላይ ወደቀ፤ በበቀለም ጊዜ ወዲያው ደረቀ፤ ሥር አልነበረውምና።'),
  ('ebaff8a3-d22f-5bdb-a554-030421ed7a0b', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 4, 7, 'ሌላዉም በእሾህ መካከል ወደቀ፤ እሾሁም አብሮ አደገና አነቀው።'),
  ('0a5fecb2-840b-55fb-aa89-495e79aefd2a', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 5, 8, 'በመልካም መሬት ላይ የወደቀ ዘርም ነበረ፤ በበቀለም ጊዜ መቶ እጥፍ አፈራ።” ይህንም ብሎ፥ “የሚሰማ ጆሮ ያለው ይስማ” አላቸው።'),
  ('37946eee-65e8-5cc5-a0ff-dc60adcd9aff', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 6, 9, 'ደቀ መዛሙርቱም፥ “ይህቺ ምሳሌ ምንድን ናት?” ብለው ጠየቁት።'),
  ('4859ef47-a541-54ae-a881-a731feaa3e95', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 7, 10, 'እርሱም እንዲህ አላቸው፥ “የእግዚአብሔርን መንግሥት ምሥጢር ማወቅ ለእናንተ ተሰጥቶአችኋል፤ ለእነዚያ ግን አይተው እንዳያዩ፥ ሰምተውም እንዳይሰሙ፥ እንዳያስተውሉም በምሳሌ ነው።'),
  ('a42ed372-1fae-555f-a6a6-be8a152cdec7', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 8, 11, 'ምሳሌዉም ይህ ነው፤ ዘሩ የእግዚአብሔር ቃል ነው፤'),
  ('2a2ef993-39b7-59f8-ac0c-67d05dd6e66f', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 9, 12, 'በመንገድ የወደቀው ቃሉን የሚሰሙ ናቸው፤ አምነውም እንዳይድኑ ሰይጣን መጥቶ ቃሉን ከልባቸው ይወስድባቸዋል።'),
  ('00fc94b5-a4fc-5efe-a773-d8006f548e81', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 10, 13, 'በጭንጫም ላይ የወደቀው ሰምተው ነገሩን በደስታ የሚቀበሉት ናቸው፤ ነገር ግን ለጊዜው ያምናሉ እንጂ ሥር የላቸውም፤ መከራም በአገኛቸው ጊዜ ይክዳሉ።'),
  ('28064511-db3b-582c-a61c-8025ecf80e10', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 11, 14, 'በእሾህም መካከል የወደቀው ቃሉን ሰምተው የባለጠግነት ዐሳብ፥ የኑሮም መቈርቈር የተድላና የደስታ መጣፈጥም የሚአስጨንቃቸውና ፍሬ የማያፈሩ ናቸው።'),
  ('b819c652-9c1f-5919-ade4-9a7be041e627', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 12, 15, 'በመልካም ምድር የወደቀው ግን ቃሉን በበጎና በንጹሕ ልብ የሚሰሙና የሚጠብቁት፥ ታግሠውና ጨክነውም የሚያፈሩ ናቸው።'),
  ('91cef214-f017-5397-aebb-c4abdf462d47', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 13, 16, '“መብራትን አብርቶ፥ ዕቃም ከድኖ ከአልጋ በታች የሚያኖራት የለም፤ ነገር ግን የሚመላለሱት ብርሃንን ያዩ ዘንድ በመቅረዝ ላይ ያኖራታል።'),
  ('db7a5395-5564-52f0-a018-cb52bd9c396e', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 14, 17, 'የማይገለጥ የተሰወረ የለምና፤ የማይታይም ወደ ግልጥም የማይመጣ የተከደነ የለም፤'),
  ('c784c7e6-cb5d-5d4b-a598-a081f633d2ce', '0378d31f-7732-5eab-aa41-63c279ed0181', 'c57f37c2-f0fa-5e16-a505-66015e13202a', 15, 18, 'እንግዲህ እንዴት እንደምትሰሙ አስተውሉ፤ ላለው ይሰጠዋል፤ ከሌለው ግን ያው ያለው የሚመስለው እንኳ ይወሰድበታል።”'),
  ('b4b189fe-17f5-5e6d-aebb-8229896eda7f', '0378d31f-7732-5eab-aa41-63c279ed0181', 'a96b19c1-e509-5638-af8e-b026ae554da2', 1, 19, 'እናቱና ወንድሞቹም ወደ እርሱ መጡ፤ ነገር ግን ሕዝቡ ብዙ ነበርና ሊያገኙት አልቻሉም።'),
  ('83b7d4f0-f006-58dc-afe9-be07899a1618', '0378d31f-7732-5eab-aa41-63c279ed0181', 'a96b19c1-e509-5638-af8e-b026ae554da2', 2, 20, '“እናትህና ወንድሞችህ ከውጭ ቆመዋል፤ ሊያዩህም ይሻሉ” አሉት።'),
  ('e77d2a3a-95f4-5b1f-af59-5dcc84042a58', '0378d31f-7732-5eab-aa41-63c279ed0181', 'a96b19c1-e509-5638-af8e-b026ae554da2', 3, 21, 'እርሱም መልሶ፥ “እናቴና ወንድሞች የእግዚአብሔርን ቃል ሰምተው የሚያደርጉ እነዚህ ናቸው” አላቸው።'),
  ('b56b939a-1152-5b23-a5f6-2755c6d87bd9', '0378d31f-7732-5eab-aa41-63c279ed0181', '96e3aefb-f1da-59c4-ad52-197cdc337c08', 1, 22, 'ከዕለታት በአንዲት ቀንም እንዲህ ሆነ፤ እርሱ ከደቀ መዛሙርቱ ጋር ወደ ታንኳ ወጣና፥ “ኑ ወደ ባሕሩ ማዶ እንሻገር” አላቸው እነርሱም ሄዱ።'),
  ('e7951297-d232-5d9d-a5c2-380a4a34d700', '0378d31f-7732-5eab-aa41-63c279ed0181', '96e3aefb-f1da-59c4-ad52-197cdc337c08', 2, 23, 'ሲሄዱም አንቀላፋ፤ በባሕሩም ላይ ዐውሎ ነፋስ መጣ፤ ውኃዉም ታንኳቸውን ሞላው፤ እነርሱም ተጨነቁ።'),
  ('4288f2e8-6513-5389-a146-10ae413beaf5', '0378d31f-7732-5eab-aa41-63c279ed0181', '96e3aefb-f1da-59c4-ad52-197cdc337c08', 3, 24, 'ቀርበውም፥ “መምህር ሆይ፥ መምህር ሆይ፥ ልንጠፋ ነው” ብለው ቀሰቀሱት፤ ተነሥቶም ነፋሱንና የውኃዉን ማዕበል ገሠጻቸው፤ እነርሱም ዝም አሉ፤ ታላቅ ፀጥታም ሆነ።'),
  ('ccdaf864-c657-5375-a0f2-039519788c7b', '0378d31f-7732-5eab-aa41-63c279ed0181', '96e3aefb-f1da-59c4-ad52-197cdc337c08', 4, 25, 'እርሱም “እምነታችሁ ወዴት አለ?” አላቸው፤ እነርሱም ፈርተው ተደነቁ፤ እርስ በርሳቸውም፥ “ውኃም ነፋስም የሚታዘዙለት ይህ ማነው?” አሉ።'),
  ('958c62ab-fad4-5610-add7-722188c3e47f', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 1, 26, 'ከዚህ በኋላ በገሊላ ወደብ አቅጣጫ ወዳለችው ወደ ጌርጌሴኖን ሀገር በታንኳ ሄዱ።'),
  ('6e035e9b-4721-54f0-a8aa-9d340b9eea64', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 2, 27, 'ወደ ምድርም በወረዱ ጊዜ ጋኔን ያደረበት ሰው ከከተማ ወጥቶ ተገናኘው፤ ልብሱንም ከጣለ ብዙ ዘመን ሆኖት ነበር፤ በመቃብር ብቻ ይኖር ነበር እንጂ ወደ ቤት አይገባም ነበር፤'),
  ('61df82e8-41cb-5c07-a1ff-a67a14b3a102', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 3, 28, 'ጌታችን ኢየሱስንም ባየው ጊዜ ጮኸ፤ ሮጦም ሰገደለት፤ “የልዑል እግዚአብሔር ልጅ ኢየሱስ ሆይ፥ ካንተ ጋር ምን አለኝ?” እያለም በታላቅ ቃል ጮኸ፤ እንዳያሠቃየውም ማለደው።'),
  ('e14cc92a-b0f4-527a-a808-ca418837533f', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 4, 29, 'ክፉውን ጋኔን ከዚያ ሰው ላይ እንዲወጣ ያዝዘው ነበርና፤ ዘወትርም አእምሮዉን ያሳጣው ነበርና፤ ብላቴኖችም በእግር ብረት አስረው ይጠብቁት ነበር፤ እግር ብረቱንም ይሰብር ነበር፤ ጋኔኑም በምድረ በዳ ያዞረው ነበር።'),
  ('5d5123d5-c830-52a8-afaf-c26f8a3300f9', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 5, 30, 'ጌታችን ኢየሱስም፥ “ስምህ ማነው?” ብሎ ጠየቀው፤ እርሱም፥ “ስሜ ሌጌዎን ነው” አለው፤ ብዙ አጋንንት ይዘውት ነበርና።'),
  ('4e2786c4-c85f-5646-aa99-8b8b90cfcf42', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 6, 31, 'ወደ ጥልቁም ይገቡ ዘንድ እንዳይሰድዳቸው ማለዱት።'),
  ('06db469c-37c0-5751-abfa-f1ae51d541c6', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 7, 32, 'በዚያም ብዙ የእሪያ መንጋ በተራራ ላይ ተሰማርቶ ነበር፤ ወደ እሪያዎችም እንዲገቡባቸው ይፈቅድላቸው ዘንድ ማለዱት፤ እርሱም ፈቀደላቸው።'),
  ('8f2d8cef-ff56-5b01-aa3f-6f7ea987f299', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 8, 33, 'እነዚያ አጋንንትም ከዚያ ሰው ላይ ወጥተው ወደ እሪያዎች ገቡ፤ የእሪያዎችም መንጋ አብደው ከገደሉ ወደ ባሕር ጠልቀው ሞቱ።'),
  ('03717f4d-f913-5b5d-a415-7657834d6abb', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 9, 34, 'እረኞችም የሆነውን ባዩ ጊዜ ሸሽተው ሄዱና ገብተው በከተማዉና በመንደሩ አወሩ።'),
  ('9d877bb7-77b4-5ee9-a74c-42ceac0bea57', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 10, 35, 'ሰዎችም የሆነውን ያዩ ዘንድ ወጡ፤ ሄደውም ወደ ጌታችን ወደ ኢየሱስ በደረሱ ጊዜ አጋንንት የወጡለትን ያን ሰው አእምሮዉ ተመልሶለት ልብሱን ለብሶ፥ ከጌታችን ከኢየሱስ እግር አጠገብ ተቀምጦ አገኙትና ፈሩ።'),
  ('cd70938f-af74-5c8f-a878-430292993435', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 11, 36, 'ያዩትም ሰዎች ጋኔን አድሮበት የነበረው ሰው እንዴት እንደ ዳነ ነገሩአቸው።'),
  ('d3310520-882e-5735-a6ce-3fa097ccd08d', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 12, 37, 'በጌርጌሴኖንም ዙሪያ ያሉ ሰዎች ከእነርሱ ዘንድ እንዲሄድላቸው ማለዱት፤ ጽኑ ፍርሀት ይዞአቸዋልና፤ ጌታችን ኢየሱስም በታንኳ ሆኖ ተመለሰ።'),
  ('b4060a7b-4aa1-531d-a41b-a656a219075e', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 13, 38, 'ያም አጋንንት የወጡለት ሰው ከእርሱ ጋር ይሄድ ዘንድ ጌታችን ኢየሱስን ማለደው፤'),
  ('0ced9053-b077-5b89-a921-79310db09007', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 14, 39, 'እርሱ ግን፥ “ወደ ቤትህ ተመልሰህ እግዚአብሔር ያደረገልህን ታላቅ ነገር ሁሉ ተናገር” ብሎ አሰናበተው። እርሱም ሄዶ በከተማዉ ሁሉ ጌታችን ኢየሱስ ያደረገለትን ሁሉ ተናገረ።'),
  ('aedf4043-b20b-5c11-a0c2-699eed130210', '0378d31f-7732-5eab-aa41-63c279ed0181', '931f3976-6b44-5ce7-aef9-9678efc56093', 15, 40, 'ጌታችን ኢየሱስም በተመለሰ ጊዜ ሕዝቡ በአንድነት ተቀበሉት፤ ሁሉ ይጠባበቁት ነበርና።'),
  ('eac82957-b919-5fc2-ac39-8e1be0e2d80b', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 1, 41, 'እነሆም ኢያኢሮስ የሚባል ሰው መጣ፤ እርሱም የምኵራብ ሹም ነበር፤ ከጌታችን ኢየሱስ እግር በታችም ሰገደ። ወደ ቤቱም ይገባ ዘንድ ለመነው።'),
  ('17335f61-b947-5b5a-ac91-587ac520e1c9', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 2, 42, 'ዕድሜዋ ዐሥራ ሁለት ዓመት የሚሆናት አንዲት ልጅ ነበረችው፤ እርስዋም ልትሞት ቀርባ ነበረች።'),
  ('fd98d1df-66ac-5bd2-a8b8-d5d0d420943f', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 3, 43, 'ከዚህም በኋላ ጌታችን ኢየሱስ ከእርሱ ጋር ሲሄድ ሰዎች ያጨናንቁት ነበር፤ ከዐሥራ ሁለት ዓመትም ጀምሮ ደም ይፈስሳት የነበረች ሴት መጣች፤ ገንዘብዋንም ሁሉ ለባለመድኀኒቶች ሰጥታ ጨርሳ ነበር፤ ነገር ግን ሊያድናት የቻለ ማንም አልነበረም።'),
  ('5c606dc8-fa8b-51a6-af7e-a7481f1fb2c1', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 4, 44, 'ቀርባም በጌታችን በኢየሱስ በስተኋላው ቆመችና የልብሱን ጫፍ ዳሰሰች፤ ያንጊዜም የደምዋ መፍሰስ ቆመ።'),
  ('156b21e0-20fa-56bb-a936-9dbb65dbdcab', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 5, 45, 'ጌታችን ኢየሱስም፥ “ማን ዳሰሰኝ?” አለ፤ ሁሉም ካዱ፤ ጴጥሮስና ከእርሱ ጋር የነበሩትም፥ “መምህር ሆይ፥ ሰው ይጋፋህና ያጨናንቅህ የለምን? አንተ ግን ማን ዳሰሰኝ? ትላለህ” አሉት።'),
  ('3c998361-320e-5635-a169-3fe582241711', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 6, 46, 'ጌታችን ኢየሱስም፥ “የዳሰሰኝ አለ፤ ከእኔ ኀይል እንደ ወጣ ዐውቃለሁና” አላቸው።'),
  ('2091354e-987d-59be-a266-6f4f0be4059f', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 7, 47, 'ሴቲቱም እንዳልተሰወረላት ባየች ጊዜ እየተንቀጠቀጠች ሄዳ ሰገደችለት፤ በሕዝቡም ሁሉ ፊት በምን ምክንያት ወደ እርሱ እንደ ቀረበችና የልብሱን ጫፍ እንደ ዳሰሰች ወዲያውም እንደ ዳነች ተናገረች።'),
  ('b4471556-1581-5cb6-ac7b-4dc803b877fc', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 8, 48, 'እርሱም፥ “ልጄ ሆይ፥ እምነትሽ አዳነችሽ፤ በሰላም ሂጂ” አላት።'),
  ('cfa2e879-2dde-5979-a9ec-6b64579cfe12', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 9, 49, 'ይህንም ሲናገር አንድ ሰው ከምኵራቡ ሹም ቤት መጥቶ፥ “ልጅህስ ሞታለች እንግዲህ መምህሩን አታድክመው” አለው።'),
  ('69d7309c-b7dd-5c5f-ab6e-b8f19e016b3b', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 10, 50, 'ጌታችን ኢየሱስም በሰማ ጊዜ የምኵራቡን ሹም፥ “አትፍራ፥ ብቻ እመን፤ ልጅህስ ትድናለች” አለው።'),
  ('aab6e8a0-4825-5a33-a660-cf76724918bc', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 11, 51, 'ወደ ቤትም በገባ ጊዜ ከጴጥሮስ፥ ከያዕቆብና ከዮሐንስ፥ ከብላቴናይቱም አባትና እናት በቀር ማንም ከእርሱ ጋር ሌላ ሰው ይገባ ዘንድ አልፈቀደም።'),
  ('943343a3-7954-50df-a783-10e6f032d7e7', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 12, 52, 'ሁሉም እያለቀሱ ዋይ ዋይ ይሉላት ነበር፤ ጌታችን ኢየሱስ ግን፥ “አታልቅሱ፤ ብላቴናይቱ ተኝታለች እንጂ አልሞተችም” አላቸው።'),
  ('f9c2d272-4d2f-5700-a731-438fdf2d890c', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 13, 53, 'እንደ ሞተችም ዐውቀዋልና ሳቁበት።'),
  ('523c16fe-986f-5add-a331-c92c8c8bcc07', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 14, 54, 'እርሱ ግን ሁሉን ወደ ውጭ አስወጣና እጅዋን ይዞ ጠራት፤ እንዲህም አላት፥ “ አንቺ ብላቴና ተነሺ።”'),
  ('fdc6567d-0832-5570-a77d-20a2d6fa3b60', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 15, 55, 'ወዲያውም ነፍስዋ ተመልሶላት ፈጥና ቆመች፥ የምትበላውንም ይሰጡአት ዘንድ አዘዘ።'),
  ('686a6df9-361f-5cd8-a4da-1ec4da878f60', '0378d31f-7732-5eab-aa41-63c279ed0181', 'aa2b8d65-7bbe-58a8-a4f6-4a490b6579e9', 16, 56, 'አባቷና እናቷም አደነቁ፤ እርሱ ግን የሆነውን ለማንም እንዳይነግሩ ከለከላቸው።'),
  ('edae1b82-fdf3-5078-a326-1f4599ba03df', '608b31fa-231f-510e-a55d-f62b2779dc42', 'a404a250-85a8-5d76-a7e0-d2b808771d78', 1, 1, 'ዐሥራ ሁለቱንም ሐዋርያት ጠራና፦ በአጋንንት ሁሉ ላይ፥ ድውያንንም ይፈውሱ ዘንድ ኀይልንና ሥልጣንን ሰጣቸው።'),
  ('a0199deb-638a-593c-a56b-d78c59a8cb89', '608b31fa-231f-510e-a55d-f62b2779dc42', 'a404a250-85a8-5d76-a7e0-d2b808771d78', 2, 2, 'የእግዚአብሔርን መንግሥት እንዲሰብኩ፥ ድውያንንና ሕሙማንንም ሁሉ እንዲፈውሱ ላካቸው።'),
  ('6517bfc7-13df-5d6c-a8c9-4c153a5b947a', '608b31fa-231f-510e-a55d-f62b2779dc42', 'a404a250-85a8-5d76-a7e0-d2b808771d78', 3, 3, 'እንዲህም አላቸው፥ “በትርም ቢሆን፥ ከረጢትም ቢሆን፥ እንጀራም ቢሆን፥ ወርቅም ቢሆን፥ ሁለት ልብስም ቢሆን ለመንገድ ምንም አትያዙ።'),
  ('ec51f51d-579e-5df8-a1f9-fdce1b8ebf04', '608b31fa-231f-510e-a55d-f62b2779dc42', 'a404a250-85a8-5d76-a7e0-d2b808771d78', 4, 4, 'በምትገቡበት ቤት በዚያ ተቀመጡ፤ እስክትሄዱም ድረስ ከዚያ አትውጡ።'),
  ('d5110464-cd6f-5b15-a757-70757bfa1b48', '608b31fa-231f-510e-a55d-f62b2779dc42', 'a404a250-85a8-5d76-a7e0-d2b808771d78', 5, 5, 'የማይቀበሉአችሁ ቢሆን ግን ከዚያች ከተማ ወጥታችሁ ምስክር ሊሆንባቸው የእግራችሁን ትቢያ አራግፉ።”'),
  ('c83f2041-55c1-5503-a390-2d72af658100', '608b31fa-231f-510e-a55d-f62b2779dc42', 'a404a250-85a8-5d76-a7e0-d2b808771d78', 6, 6, 'ወጥተውም በየአውራጃዉ መንደሮች ዞሩ፤ በስፍራውም ሁሉ ወንጌልን ሰበኩ፤ ድውያንንም ፈወሱ።'),
  ('b5f5f046-95d0-5285-a5c6-47c4c5b25f2e', '608b31fa-231f-510e-a55d-f62b2779dc42', '2f6863f2-0f2b-59f9-ac5a-4e08c839f6d0', 1, 7, 'የአራተኛው ክፍል ገዥ ሄሮድስም የተደረገውን ሁሉ ሰምቶ የሚናገረውን ያጣ ነበር፤ መጥምቁ ዮሐንስ ከሙታን ተለይቶ ተነሣ የሚሉ ነበሩና።'),
  ('58e11eaa-c851-5ba9-abbf-7c7c0ed40193', '608b31fa-231f-510e-a55d-f62b2779dc42', '2f6863f2-0f2b-59f9-ac5a-4e08c839f6d0', 2, 8, 'ኤልያስ ተገለጠ የሚሉም ነበሩ፤ ከቀደሙት ነቢያት አንዱ ተነሥቶአል የሚሉም ነበሩና።'),
  ('7b552437-ad7a-5ca3-a7c6-b81bed5b2292', '608b31fa-231f-510e-a55d-f62b2779dc42', '2f6863f2-0f2b-59f9-ac5a-4e08c839f6d0', 3, 9, 'ሄሮድስም፥ “እኔ የዮሐንስን ራስ አስቈረጥሁ፤ እንግዲህ ስለ እርሱ ሲወራ የምሰማው ይህ ማነው?” አለ፤ ሊያየውም ይሻ ነበር።'),
  ('587fce68-6563-56b1-aaf8-ffc7e3098ab2', '608b31fa-231f-510e-a55d-f62b2779dc42', '2f6863f2-0f2b-59f9-ac5a-4e08c839f6d0', 4, 10, 'ሐዋርያትም በተመለሱ ጊዜ ያደረጉትን ሁሉ ነገሩት፤ እርሱም ለብቻቸው ይዞአቸው ቤተ ሳይዳ ከምትባል ከተማ አጠገብ ወደ አለ ምድረ በዳ ወጡ።'),
  ('291421ba-8209-5b35-a420-e4d555731397', '608b31fa-231f-510e-a55d-f62b2779dc42', '2f6863f2-0f2b-59f9-ac5a-4e08c839f6d0', 5, 11, 'ሕዝቡም ዐውቀው ተከተሉት፤ እርሱም ተቀበላቸው፤ ስለ እግዚአብሔር መንግሥትም አስተማራቸው፤ ሊፈወሱ የሚሹትንም አዳናቸው።'),
  ('bcfba7a6-977d-553c-aec2-e700317dda71', '608b31fa-231f-510e-a55d-f62b2779dc42', '7ca1561d-f622-5ca7-aadb-1f585210d4b8', 1, 12, 'ቀኑም በመሸ ጊዜ ዐሥራ ሁለቱ ደቀ መዛሙርት መጥተው፥ “ያለንበት ምድረ በዳ ነውና በዙሪያችን ወዳሉ መንደሮችና ገጠሮች ሄደው እንዲያድሩ የሚበሉትንም እንዲያገኙ ሕዝቡን አሰናብት” አሉት።'),
  ('05ba9948-6ac8-52de-a9c4-448d100e915b', '608b31fa-231f-510e-a55d-f62b2779dc42', '7ca1561d-f622-5ca7-aadb-1f585210d4b8', 2, 13, 'እርሱ ግን፥ “እናንተ የሚበሉትን ስጡአቸው” አላቸው፤ እነርሱም፥ “ለዚህ ሁሉ ሕዝብ የሚበቃ ምግብ ልንገዛ ካልሄድን ከአምስት እንጀራና ከሁለት ዓሣ በቀር ሌላ በዚህ የለንም” አሉት።'),
  ('243957da-dae3-5f67-a587-5d369247b39d', '608b31fa-231f-510e-a55d-f62b2779dc42', '7ca1561d-f622-5ca7-aadb-1f585210d4b8', 3, 14, 'ሰዎቹም አምስት ሺህ ያህሉ ነበር፤ ደቀ መዛሙርቱንም፥ “አምሳ አምሳውን በየክፍላቸው አስቀምጡአቸው” አላቸው።'),
  ('5949ff6a-6f9e-5a1e-a809-4aaf18e5fec6', '608b31fa-231f-510e-a55d-f62b2779dc42', '7ca1561d-f622-5ca7-aadb-1f585210d4b8', 4, 15, 'እንዲሁም አደረጉ፤ ሁሉም ተቀመጡ።'),
  ('0710af4b-22e5-5fd2-ac24-bb6bef7c0784', '608b31fa-231f-510e-a55d-f62b2779dc42', '7ca1561d-f622-5ca7-aadb-1f585210d4b8', 5, 16, 'አምስቱን እንጀራና ሁለቱን ዓሣ ይዞ ወደ ሰማይ ተመለከተ፤ ባረከ፤ ቈርሶም ለሕዝቡ እንዲያቀርቡ ለደቀ መዛሙርቱ ሰጣቸው።'),
  ('8551320b-2bdb-5aa4-ab0b-8021c2a60764', '608b31fa-231f-510e-a55d-f62b2779dc42', '7ca1561d-f622-5ca7-aadb-1f585210d4b8', 6, 17, 'ሁሉም በልተው ጠገቡ፤ ያነሡትም የተረፈው ቍርስራሽ ዐሥራ ሁለት መሶብ ሞላ።'),
  ('978d02d2-85c8-505d-aeea-b77f5f05691d', '608b31fa-231f-510e-a55d-f62b2779dc42', '8606f85f-3134-52e3-aa0f-b54dcb5d5640', 1, 18, 'ከዚህም በኋላ ብቻውን ሲጸልይ ደቀ መዛሙርቱም ከእርሱ ጋር ሳሉ፥ “ሰዎች ማን ይሉኛል?” ብሎ ጠየቃቸው።'),
  ('8582116a-2037-5612-ae3a-3258d26679ad', '608b31fa-231f-510e-a55d-f62b2779dc42', '8606f85f-3134-52e3-aa0f-b54dcb5d5640', 2, 19, 'እነርሱም መልሰው፥ “መጥምቁ ዮሐንስ ነው የሚሉህ አሉ፤ ኤልያስ ነው የሚሉህም አሉ፤ ከቀደሙት ነቢያት አንዱ ተነሥቶአል የሚሉህም አሉ” አሉት።'),
  ('7012aa7d-5a74-5d2a-a3cb-a26ffb06e3d9', '608b31fa-231f-510e-a55d-f62b2779dc42', '8606f85f-3134-52e3-aa0f-b54dcb5d5640', 3, 20, 'እርሱም፥ “እናንተስ ማን ትሉኛላችሁ?” አላቸው፤ ጴጥሮስም መልሶ፥ “አንተ የእግዚአብሔር መሲሕ ነህ” አለው።'),
  ('27582bd1-af1e-57c3-a565-fff0df0a4c59', '608b31fa-231f-510e-a55d-f62b2779dc42', '8606f85f-3134-52e3-aa0f-b54dcb5d5640', 4, 21, 'ይህንም ለማንም እንዳይናገሩ ገሠጻቸውና ከለከላቸው።'),
  ('eeac9966-082e-5468-a838-34313410f5ef', '608b31fa-231f-510e-a55d-f62b2779dc42', '2234da15-f3ca-5f5c-ace0-6ad6275d33a6', 1, 22, '“ለሰው ልጅ ብዙ መከራ ያጸኑበት ዘንድ ሽማግሌዎችና የካህናት አለቆች፥ ጻፎችም ይፈትኑት ዘንድ፥ ይገድሉትም ዘንድ፥ በሦስተኛውም ቀን ይነሣ ዘንድ አለው” አላቸው።'),
  ('7010c53c-f819-5bc0-a073-53ca99da6f0b', '608b31fa-231f-510e-a55d-f62b2779dc42', '2234da15-f3ca-5f5c-ace0-6ad6275d33a6', 2, 23, 'ሁሉንም እንዲህ አላቸው፥ “ሊከተለኝ የሚወድ ሰው ራሱን ይካድ፤ ጨክኖም የሞቱን መስቀል ይሸከም፤ ዕለት ዕለትም ይከተለኝ።'),
  ('82b6baa7-d33b-575a-aa01-16cdf0b787de', '608b31fa-231f-510e-a55d-f62b2779dc42', '2234da15-f3ca-5f5c-ace0-6ad6275d33a6', 3, 24, 'ሰውነቱን ሊያድን የሚወድ ሁሉ ይጥላታል፤ ስለ እኔ ሰውነቱን የጣለ ግን ያድናታል።'),
  ('078bea0a-10b2-5e68-a2a4-6b791a8ac5a4', '608b31fa-231f-510e-a55d-f62b2779dc42', '2234da15-f3ca-5f5c-ace0-6ad6275d33a6', 4, 25, 'ሰው ዓለሙን ሁሉ ቢገዛ ነፍሱንም ካጣ ምን ይረባዋል?'),
  ('60be450e-2b93-5880-ae1f-dd6a1b6f9ca4', '608b31fa-231f-510e-a55d-f62b2779dc42', '2234da15-f3ca-5f5c-ace0-6ad6275d33a6', 5, 26, 'በእኔና በቃሌ የሚያፍር ሁሉ የሰው ልጅ በክብሩ፥ በአባቱም ክብር፥ ቅዱሳንመላእክትን አስከትሎ ሲመጣ ያፍርበታል።'),
  ('3b841157-ab7f-514c-ab0f-01cb4f8f717e', '608b31fa-231f-510e-a55d-f62b2779dc42', '2234da15-f3ca-5f5c-ace0-6ad6275d33a6', 6, 27, 'እውነት እላችኋለሁ፤ በዚህ ከቆሙት የእግዚአብሔርን መንግሥት እስኪያዩአት ድረስ ሞትን የማይቀምሱ አሉ።”'),
  ('bb34f5e0-3bca-5c53-a074-59b0ecb0f616', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 1, 28, 'ከዚህም ነገር በኋላ በስምንተኛው ቀን ጌታችን ኢየሱስ ጴጥሮስን፥ ያዕቆብንና ዮሐንስን ይዞአቸው ሊጸልይ ወደ ተራራ ወጣ።'),
  ('8021a928-113c-524c-a6ca-d82517ffe9d2', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 2, 29, 'ሲጸልይም የፊቱ መልክ ተለወጠ፤ ልብሱም ነጭ ሆነ፤ እንደ መብረቅም አብለጨለጨ።'),
  ('8efa0997-7ac7-5dbd-a554-24336b343559', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 3, 30, 'እነሆም፥ ሁለት ሰዎች መጥተው ከእርሱ ጋር ይነጋገሩ ነበር። እነርሱም ሙሴና ኤልያስ ነበሩ።'),
  ('90ab6172-d12b-5173-a90d-655de5752ddd', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 4, 31, 'በክብርም ተገልጠው በኢየሩሳሌም ይደረግ ዘንድ ያለውን ክብሩንና መውጣቱን ተናገሩ፤'),
  ('e78511dd-503a-51a5-af35-0a5b7af0f4ba', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 5, 32, 'ጴጥሮስንና ከእርሱ ጋር የነበሩትንም ዐይኖቻቸው በእንቅልፍ ፈዝዘው አገኘ፤ በነቁም ጊዜ ክብሩንና ከእርሱ ጋር ቆመው የነበሩትን ሁለት ሰዎች አዩ።'),
  ('d761eed2-0add-5f6d-ad49-fc879c5a7c10', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 6, 33, 'ከዚህም በኋላ ከእርሱ ሲለዩ ጴጥሮስ ጌታችን ኢየሱስን፥ “መምህር፥ ሆይ፥ እዚህ ብንኖር ለእኛ መልካም ነው፤ ሦስት ሰቀላዎችንም እንሥራ፤ አንዱን ለአንተ፥ አንዱንም ለሙሴ፥ አንዱንም ለኤልያስ” አለው፤ የሚናገረውንም አያውቅም ነበር።'),
  ('7f758e6a-b875-5012-a462-a7a2f269add2', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 7, 34, 'ይህንም ሲናገር ደመና መጣና ጋረዳቸው፤ ወደ ደመናውም በገቡ ጊዜ ፈሩ።'),
  ('ec0918cb-96e2-587f-af11-691fa08f5019', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 8, 35, 'ከደመናውም ውስጥ፥ “የመረጥሁት ልጄ ይህ ነው፤ እርሱን ስሙት” የሚል ቃል መጣ።'),
  ('606ab6ba-cbb6-553b-aa42-71ce4d518349', '608b31fa-231f-510e-a55d-f62b2779dc42', '913a50b1-dba5-55ac-ae5f-3403137238d1', 9, 36, 'ቃሉም ከመጣ በኋላ ጌታችን ኢየሱስ ብቻውን ተገኘ፤ እነርሱ ግን ዝም አሉ፤ ያዩትንና የሰሙትንም በዚያ ጊዜ ለማንም አልተናገሩም።'),
  ('cab97456-b5cf-55d7-a7c9-69c047de15e1', '608b31fa-231f-510e-a55d-f62b2779dc42', 'b4fa36f7-22e9-5c93-acbc-0968e2576125', 1, 37, 'በሁለተኛውም ቀን ከተራራው ወረዱ፤ ብዙ ሕዝብም ተቀበሉት።'),
  ('1f08e674-c490-5ddb-a60a-0fe9ee59027f', '608b31fa-231f-510e-a55d-f62b2779dc42', 'b4fa36f7-22e9-5c93-acbc-0968e2576125', 2, 38, 'አንድ ሰውም በሕዝቡ መካከል ጮኾ እንዲህ አለው፥ “መምህር ሆይ፥ እርሱ ለእኔ አንድ ነውና ልጄን ታይልኝ ዘንድ እለምንሃለሁ።'),
  ('1e1a442a-e3cf-528f-a5e3-cb5eae406419', '608b31fa-231f-510e-a55d-f62b2779dc42', 'b4fa36f7-22e9-5c93-acbc-0968e2576125', 3, 39, 'እነሆ፥ ጋኔን ሊነጥቀኝ ነው፤ ድንገትም ያስጮኸዋል፤ ጥሎም ያፈራግጠዋል፤ አረፋም ያስደፍቀዋል፤ ቀጥቅጦ በጭንቅ ይተወዋል።'),
  ('55f82d38-cabb-5214-aec6-2a532b9895d2', '608b31fa-231f-510e-a55d-f62b2779dc42', 'b4fa36f7-22e9-5c93-acbc-0968e2576125', 4, 40, 'እንዲያወጡትም ደቀ መዛሙርትህን ለመንሁአቸው፤ ነገር ግን ማውጣት ተሳናቸው።”'),
  ('dec21a77-9dd6-5975-a7be-bb9bf6ac7e02', '608b31fa-231f-510e-a55d-f62b2779dc42', 'b4fa36f7-22e9-5c93-acbc-0968e2576125', 5, 41, 'ጌታችን ኢየሱስም መልሶ፥ “የማታምን ከዳተኛ ትውልድ፥ እስከ መቼ ከእናንተ ጋር እኖራለሁ? እስከ መቼስ እታገሣችኋለሁ? ልጅህን ወደዚህ አምጣው” አለው።'),
  ('91617f13-1b23-5025-ae90-9488640e6cee', '608b31fa-231f-510e-a55d-f62b2779dc42', 'b4fa36f7-22e9-5c93-acbc-0968e2576125', 6, 42, 'ሲያመጣውም ጋኔኑ ጣለውና አፈራገጠው፤ ጌታችን ኢየሱስም ያን ክፉ ጋኔን ገሠጸው፤ ልጁንም አዳነው፤ ለአባቱም ሰጠው። ሁሉም ከእግዚአብሔር ታላቅነት የተነሣ አደነቁ።'),
  ('655e9d85-bc81-5daa-abb2-7ba6e3dcca87', '608b31fa-231f-510e-a55d-f62b2779dc42', 'be091a2f-ac51-5003-a808-320847428c33', 1, 43, 'እነርሱም ጌታችን ኢየሱስ ባደረገው ተአምራት ሁሉ ሲደነቁ ደቀ መዛሙርቱን እንዲህ አላቸው።'),
  ('3e2878e1-86a4-5cc5-a6df-bae2e30fb0e9', '608b31fa-231f-510e-a55d-f62b2779dc42', 'be091a2f-ac51-5003-a808-320847428c33', 2, 44, '“እናንተስ ይህን ነገር በልባችሁ አኑሩት፤ የሰው ልጅ በሰዎች እጅ ተላልፎ ይሰጥ ዘንድ አለውና።”'),
  ('6583b993-20c1-5c96-a5a8-4e5d274a2693', '608b31fa-231f-510e-a55d-f62b2779dc42', 'be091a2f-ac51-5003-a808-320847428c33', 3, 45, 'እነርሱ ግን ይህን ነገር አላስተዋሉትም፤ እንዳይመረምሩት ከእነርሱ የተሰወረ ነውና፤ ስለዚህ ነገርም እንዳይጠይቁት ይፈሩት ነበርና።'),
  ('e1d2027c-ed8c-58d4-aa19-6bd873bca326', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 1, 46, 'እርስ በርሳቸውም ከእነርሱ ማን እንደሚበልጥ ዐሰቡ።'),
  ('fecc2662-cb4e-5167-a66a-3b2830d38f99', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 2, 47, 'ጌታችን ኢየሱስም በልቡናቸው የሚያስቡትን ዐወቀባቸውና አንድ ሕፃን ወስዶ በመካከላቸው አቆመው።'),
  ('2de2bb8e-d673-5385-a7ea-45eefadb33ee', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 3, 48, 'እንዲህም አላቸው፥ “በስሜ እንደዚህ ያለውን ሕፃን የሚቀበል እኔን ይቀበላል፥ እኔንም የሚቀበል የላከኝን ይቀበላል፤ ራሱን ከሁሉ ዝቅ የሚያደርግ እርሱ ታላቅ ይሆናል።”'),
  ('998ec42d-b30d-50af-aeb8-b12bd87e00f1', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 4, 49, 'ዮሐንስም መልሶ፥ “መምህር ሆይ፥ በስምህ ጋኔን ሲያወጣ ያየነው አንድ ሰው አለ፤ ከእኛም ጋር አልተከተለህምና ከለከልነው፤” አለው።'),
  ('8874418f-7350-5a92-a8e6-21166e847f61', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 5, 50, 'ጌታችን ኢየሱስም፥ “አትከልክሉት፤ ባለጋራችሁ ካልሆነ ባልንጀራችሁ ነውና” አላቸው።'),
  ('e55d0ca0-d6eb-5cec-a862-afece61fec72', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 6, 51, 'የመውጣቱ ወራትም በቀረበ ጊዜ ወደ ኢየሩሳሌም ለመሄድ ፊቱን አቀና።'),
  ('7d959ae8-66e6-51b9-a612-8e5d53a2c192', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 7, 52, 'በፊቱም መልእክተኞችን ላከ፤ ሄደውም ያዘጋጁለት ዘንድ ወደ ሰማርያ ከተማ ገቡ።'),
  ('c05c1fe2-b83b-51fd-a498-b8bcce09b25c', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 8, 53, 'ነገር ግን አልተቀበሉትም፤ ፊቱን ወደ ኢየሩሳሌም አቅንቶ ነበርና።'),
  ('430bb4b4-a4bd-540a-a606-ea9231c2040f', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 9, 54, 'ደቀ መዛሙርቱ ያዕቆብና ዮሐንስም ይህን ባዩ ጊዜ፥ “አቤቱ፥ ኤልያስ እንደ አደረገ እሳት ከሰማይ ወርዶ ያጥፋቸው እንድንል ትፈቅዳለህን?” አሉት።'),
  ('ef8fd97b-c1a2-54a2-a89d-c89646711bbc', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 10, 55, 'እርሱ ግን ዘወር ብሎ፥ “ከምን መንፈስ እንደ ሆናችሁ አታውቁም” ብሎ ገሠጻቸው።'),
  ('8bebb8ea-4ac7-56b1-ac1a-f309d2d55872', '608b31fa-231f-510e-a55d-f62b2779dc42', '9078844c-f1d1-5474-a242-f15841fa80f3', 11, 56, 'የሰው ልጅ የሰውን ነፍስ ሊያድን እንጂ ሊያጠፋ አልመጣም። ወደ ሌላም መንደር ሄዱ።'),
  ('8cf2708e-bffe-5f5d-ac75-0d75da469ea5', '608b31fa-231f-510e-a55d-f62b2779dc42', 'de0ecd2c-0ac5-52e4-ab69-40e8df597b8e', 1, 57, 'ከዚህ በኋላ በመንገድ ሲሄዱ አንድ ሰው፥ “መምህር፥ ወደምትሄድበት ልከተልህን?” አለው።'),
  ('d16aa420-0198-5315-a5cf-3e554129c981', '608b31fa-231f-510e-a55d-f62b2779dc42', 'de0ecd2c-0ac5-52e4-ab69-40e8df597b8e', 2, 58, 'ጌታችን ኢየሱስም “ለቀበሮዎች ጕድጓድ አላቸው፤ ለሰማይ ወፎችም ጎጆ አላቸው፤ የሰው ልጅ ግን ራሱን የሚያስጠጋበት የለውም” አለው።'),
  ('ae60940b-6155-5ea7-a1c3-e43a8942e987', '608b31fa-231f-510e-a55d-f62b2779dc42', 'de0ecd2c-0ac5-52e4-ab69-40e8df597b8e', 3, 59, 'ሌላውንም፥ “ተከተለኝ” አለው፤ እርሱ ግን፥ “አቤቱ፥ በፊት ሄጄ አባቴን እንድቀብረው ፍቀድልኝ” አለው።'),
  ('2c58bd14-f0e1-531b-ae03-dc3d3c0e2608', '608b31fa-231f-510e-a55d-f62b2779dc42', 'de0ecd2c-0ac5-52e4-ab69-40e8df597b8e', 4, 60, 'ጌታችን ኢየሱስም፥ “ሙታኖቻቸውን ይቀብሩ ዘንድ ሙታንን ተዉአቸው፤ አንተ ግን ሂድና የእግዚአብሔርን መንግሥት ስበክ” አለው።'),
  ('23e11b58-30ac-5b4b-a1ee-1c6af4d12a9b', '608b31fa-231f-510e-a55d-f62b2779dc42', 'de0ecd2c-0ac5-52e4-ab69-40e8df597b8e', 5, 61, 'ሦስተኛውም፥ “አቤቱ፥ ልከተልህን? ነገር ግን ሄጄ ቤተ ሰቦችን ሁሉ እንድሰናበት ፍቀድልኝ” አለው።'),
  ('a0852696-946e-57be-a7dc-422131bcfcef', '608b31fa-231f-510e-a55d-f62b2779dc42', 'de0ecd2c-0ac5-52e4-ab69-40e8df597b8e', 6, 62, 'ጌታችን ኢየሱስም፥ “ማንም ዕርፍ ይዞ እያረሰ ወደ ኋላው የሚመለከት ለእግዚአብሔር መንግሥት የተገባ አይሆንም” አለው።'),
  ('c37f9cb4-c233-524a-a529-9da5df28bf9a', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 1, 1, 'ከዚህም በኋላ ጌታችን ሌሎች ሰባ ሰዎችን መረጠ፤ ሁለት ሁለት አድርጎም ሊሄድበት ወደ አለው ከተማና መንደር በፊቱ ላካቸው።'),
  ('836c02eb-2d75-5064-a791-7cc215745dba', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 2, 2, 'ጌታችን ኢየሱስም አላቸው፥ “መከሩ ብዙ ነው፤ ሠራተኛው ግን ጥቂት ነው፤ እንግዲህ ለመከሩ ሠራተኛ ጨምሮ ይልክ ዘንድ ባለ መከሩን ለምኑት።'),
  ('cbe882d1-c267-5ac0-a75e-85290bbb0d20', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 3, 3, 'ሂዱ፤ እነሆ፥ እኔ እንደ በጎች በተኵላዎች መካከል እልካችኋለሁ።'),
  ('df344b96-9818-5962-ad10-4cb0e89ccece', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 4, 4, 'ከረጢትም፥ ስልቻም፥ ጫማም፥ ምንም ምን አትያዙ፤ በመንገድም ማንንም ሰላም አትበሉ።'),
  ('f1508b0c-0aa2-5084-a182-326264c3a788', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 5, 5, 'ወደ ገባችሁበት ቤትም አስቀድማችሁ ‘ለዚህ ቤት ሰዎች ሰላም ይሁን’ በሉ።'),
  ('05322386-cbf7-57d1-afc3-d80d3d702ddc', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 6, 6, 'በዚያም የሰላም ልጅ ቢኖር ሰላማችሁ ያድርበታል፤ ያለዚያ ግን ሰላማችሁ ይመለስላችኋል።'),
  ('e866e372-bfb1-5577-a536-24a43f48ee28', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 7, 7, 'በዚያም ቤት ተቀመጡ፤ ከእነርሱ የተገኘውንም ብሉ፥ ጠጡም፤ ለሠራተኛ ዋጋው ይገባዋልና፤ ከቤትም ወደ ቤት አትሂዱ።'),
  ('0022f8b2-8614-549e-ae92-3efc2e84150e', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 8, 8, 'ወደ ማናቸውም ከተማ ብትገቡ፥ የዚያ ከተማ ሰዎችም ቢቀበሉአችሁ ያቀረቡላችሁን ብሉ።'),
  ('ca788ba7-241a-5811-afa6-0b85c8c8620a', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 9, 9, 'በውስጥዋ የሚገኙትን ድውያንንም ፈውሱ፤ ‘የእግዚአብሔርም መንግሥት ወደ እናንተ ቀርባለች’ በሉአቸው።'),
  ('313c5ce5-c7be-5778-a6d1-ff1667f2623d', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 10, 10, 'ነገር ግን ወደ ማናቸውም ከተማ ብትገቡ፥ የዚያች ከተማ ሰዎችም ባይቀበሉአችሁ ወደ አደባባይዋ ወጥታችሁ የእግራችሁን ትቢያ አራግፉ። እንዲህም በሉ፦'),
  ('319eb8d4-3dd1-5e73-a810-ee2ce37e2cc1', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 11, 11, 'ከከተማችሁ የተጣበቀብንን ትቢያ እንኳን እናራግፍላችኋለን፤ ነገር ግን የእግዚአብሔር መንግሥት ወደ እናንተ እንደ ቀረበች ይህን ዕወቁ።'),
  ('7891e48f-36ba-592b-a97f-3614e8e208b8', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 12, 12, 'በፍርድ ቀን ሰዶም ከዚያች ከተማ ይልቅ እንደምትሻል ይቅርታንም እንደምታገኝ እነግራችኋለሁ።'),
  ('c1192cec-b7a9-5015-a606-44102c0698d9', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 13, 13, '“ኮራዚ ወዮልሽ! ቤተ ሳይዳ ወዮልሽ! በእናንተ የተደረገው ተአምራት በጢሮስና በሲዶና ተደርጎ ቢሆን ቀድሞ ማቅ ለብሰው አመድም ነስንሰው በተቀመጡ ንስሓም በገቡ ነበር።'),
  ('e336eee2-2df4-5e97-a2cd-877407433ede', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 14, 14, 'ነገር ግን ጢሮስና ሲዶና ከእናንተ ይልቅ በፍርድ ቀን ይቅርታን ያገኛሉ።'),
  ('4add6606-106d-5ea1-a521-82075dd492fe', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 15, 15, 'አንቺም ቅፍርናሆም እስከ ሰማይ ድረስ ከፍ ከፍ ብትዪ እስከ ሲኦል ትወርጃለሽ።'),
  ('c36dd182-f0cf-59a4-a27c-c69fee547c05', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '46cd58ca-79bc-50fc-a19c-29a0d8a2d480', 16, 16, '“እናንተን የሚሰማ እኔን ይሰማል፤ እናንተንም እንቢ የሚል እኔን እንቢ ይላል፤ እኔንም እንቢ የሚል የላከኝን እንቢ ይላል፤ እኔንም የሚሰማ የላከኝን ይሰማል።”'),
  ('e5bad140-4b4b-5384-a2e8-1f1697067116', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 1, 17, 'እነዚያም ሰባው ደስ ብሎአቸው ተመለሱና፥ “አቤቱ፥ አጋንንት ስንኳ በስምህ ተገዙልን” አሉት።'),
  ('4a2991bc-c9f7-5efe-a695-58aa8fd8b048', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 2, 18, 'እርሱም እንዲህ አላቸው፥ “ሰይጣንን ከሰማይ እንደ መብረቅ ሲወድቅ አየሁት።'),
  ('502eda59-e314-5020-a91f-a361f8d926b0', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 3, 19, 'እነሆ፥ ጊንጦችንና እባቦችን፥ የጠላትንም ኀይል ሁሉ ትረግጡ ዘንድ ሥልጣንን ሰጠኋችሁ፤ የሚጐዳችሁም ነገር የለም።'),
  ('51a95653-a0aa-596c-a010-af0637684551', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 4, 20, 'ነገር ግን አጋንንት ስለ ተገዙላችሁ በዚህ ደስ አይበላችሁ፤ ግን ስማችሁ በሰማያት ስለ ተጻፈ ደስ ይበላችሁ።”'),
  ('e360177a-0dfa-5af5-a1d1-3e6012e89269', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 5, 21, 'በዚያች ሰዓትም ጌታችን ኢየሱስ በመንፈስ ቅዱስ ደስ አለው፤ እንዲህም አለ፥ “የሰማይና የምድር ጌታ አባት ሆይ፥ ይህን ከዐዋቂዎችና ከአስተዋዮች ሰውረህ ለሕፃናት ስለገለጥኸው አመሰግንሃለሁ፤ አዎን፥ አባት ሆይ፥ ፈቃድህ በፊትህ እንዲሁ ሆኖአልና።'),
  ('37b8abb8-f1a7-5e40-a6e6-fdc59197a398', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 6, 22, 'ሁሉ ከአባቴ ዘንድ ተሰጠኝ፤ ወልድ ማን እንደ ሆነ ከአብ በቀር የሚያውቅ የለም፤ አብም ማን እንደ ሆነ ከወልድ በቀር የሚያውቅ የለም። ወልድ ግን ለወደደው ይገልጥለታል።”'),
  ('616eafba-ad4c-58b6-a7c5-6f01650f3fa1', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 7, 23, 'ተመልሶም ደቀ መዛሙርቱን ለብቻቸው አድርጎ እንዲህ አላቸው፥ “እናንተ የምታዩትን የሚያዩ ዐይኖች ብፁዓን ናቸው።'),
  ('ab2f909d-6859-5120-a57e-a0a19f5806bc', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', '56842c13-d270-5eb4-a112-2c4418c3076c', 8, 24, 'ብዙ ነቢያትና ነገሥታት እናንተ የምታዩትን ሊያዩ ተመኙ፤ አላዩምም፤ እናንተ የምትሰሙትንም ሊሰሙ ተመኙ፥ አልሰሙም።”'),
  ('7e41bbed-c273-5255-ad5a-ca786aeab55a', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'cd6e1f3d-db56-51a0-a9dc-b0819fd4e726', 1, 25, 'ከዚህ በኋላ አንድ ሕግ ዐዋቂ ሊፈትነው ተነሣና፥ “መምህር ሆይ፥ የዘለዓለም ሕይወትን እወርስ ዘንድ ምን ላድርግ?” አለው።'),
  ('730cc4eb-8102-5500-ad4d-6761a8fb109f', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'cd6e1f3d-db56-51a0-a9dc-b0819fd4e726', 2, 26, 'እርሱም፥ “በኦሪት ምን ተጽፎአል? እንዴትስ ታነብባለህ?” አለው።'),
  ('8d9d33a8-7af6-5073-aeb1-ba9399bcad8d', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'cd6e1f3d-db56-51a0-a9dc-b0819fd4e726', 3, 27, 'እርሱም መልሶ፥ “እግዚአብሔር አምላክህን በፍጹም ልብህ፥ በፍጹም ሰውነትህ፥ በፍጹም ኀይልህ፥ በፍጹም ዐሳብህ ውደደው፤ ባልንጀራህንም እንደ ራስህ ውደድ ይላል” አለው።'),
  ('ce7f2344-f6f1-5b26-aa3f-df751a339470', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'cd6e1f3d-db56-51a0-a9dc-b0819fd4e726', 4, 28, 'ጌታችን ኢየሱስም፥ “መልካም መልሰሃል፤ እንዲሁ አድርግ፤ ትድናለህም” አለው።'),
  ('621affa4-d8a5-54d9-a6cc-3ed7b5e507c0', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'cd6e1f3d-db56-51a0-a9dc-b0819fd4e726', 5, 29, 'ራሱን ሊያከብር ባልንጀራውንም ሊንቅ ወድዶ፥ “ባልንጀራዬ ማነው?” አለው።'),
  ('230753a1-a760-54fb-ad4e-db6079e83bcd', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 1, 30, 'ጌታችን ኢየሱስም መልሶ እንዲህ አለው፥ “አንድ ሰው ከኢየሩሳሌም ወደ ኢያሪኮ ይወርድ ነበር፤ ሽፍቶችም አገኙት፤ ደበደቡት፥ አቈሰሉት፥ ልብሱንም ገፍፈው፤ በሕይወትና በሞት መካከል ጥለውት ሄዱ።'),
  ('ee7dd245-d677-5d4e-aa51-2a9e4a101cd0', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 2, 31, 'አንድ ካህንም በዚያች መንገድ ሲወርድ ድንገት አገኘው፤ አይቶም አልፎት ሄደ።'),
  ('b24065ef-de32-5609-a776-05abf12ca7be', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 3, 32, 'እንዲሁም አንድ ሌዋዊ በዚያ ቦታ አገኘውና፥ አይቶ እንደ ፊተኛው አልፎት ሄደ።'),
  ('0bb58e5a-7c84-5c7b-ac2d-eafc362dda19', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 4, 33, 'አንድ ሳምራዊ ግን በዚያች መንገድ ሲሄድ አገኘው፤ አይቶም አዘነለት።'),
  ('21750e1e-3879-5c3a-a359-943d18eb3266', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 5, 34, 'ወደ እርሱም ቀረበ፤ ቍስሉንም አጋጥሞ አሰረለት፤ በቍስሉ ላይም ወይንና ዘይት ጨመረለት፤ በአህያውም ላይ አስቀምጦ እንዲፈውሰው የእንግዶችን ቤት ወደሚጠብቀው ወሰደው፤ የሚድንበትንም ዐሰበ።'),
  ('c6dd35a8-717e-52b1-a3ce-67f267bb3c16', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 6, 35, 'በማግሥቱም ሁለት ዲናር አውጥቶ ለእንግዳ ቤት ጠባቂው ሰጠውና፦ ‘በዚህ አስታምልኝ፤ ከዚህ የሚበልጥ ለእርሱ የምታወጣው ቢኖር እኔ በተመለስሁ ጊዜ እከፍልሃለሁ’ አለው።'),
  ('7a622e59-7af5-5d68-a525-5f23295d7d1d', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 7, 36, 'እንግዲህ ሽፍቶች ለደበደቡት ሰው ከእነዚህ ከሦስቱ ባልንጀራ የሚሆነው ማንኛው ይመስልሃል?”'),
  ('21510e56-262b-5b9f-a2da-3674670ad16f', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'd6b96c5d-fa81-5410-af19-8ee6b8754524', 8, 37, 'እርሱም“ምሕረት ያደረገለት ነዋ” አለው፤ ጌታችን ኢየሱስም፥ “እንኪያስ አንተም ሂድና እንዲሁ አድርግ” አለው።'),
  ('5fb187ee-1d39-576b-a04c-efe811e37dd3', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'b4a07435-8c26-5bbb-a5bb-91c235188e4d', 1, 38, 'ከዚህም በኋላ ሄደው ወደ አንዲት መንደር ገቡ፤ ማርታ የምትባል አንዲት ሴትም በቤቷ ተቀበለችው።'),
  ('a2d35cb0-0e1a-5037-acdd-fb6200f00442', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'b4a07435-8c26-5bbb-a5bb-91c235188e4d', 2, 39, 'ማርያም የምትባል እኅትም ነበረቻት፤ እርስዋም ከጌታችን ኢየሱስ እግር አጠገብ ተቀምጣ ትምህርቱን ትሰማ ነበር።'),
  ('aa65667e-4fd1-5cfa-a315-36be18681e3a', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'b4a07435-8c26-5bbb-a5bb-91c235188e4d', 3, 40, 'ማርታ ግን ብዙ በማዘጋጀት ትደክም ነበር፤ ቆማም፥ “ጌታዬ ሆይ፥ እኅቴ ትታኝ ብቻዬን ስሠራ አያሳዝንህምን? ርጃት በላት” አለችው።'),
  ('4850c490-9480-5793-a66b-d26e4f095926', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'b4a07435-8c26-5bbb-a5bb-91c235188e4d', 4, 41, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላት፥ “ማርታ፥ ማርታ፥ በብዙ ነገር ትደክሚያለሽ፥ ትቸገሪያለሽም፤ ታዘጋጂያለሽም።'),
  ('a1e7493b-b217-5d2a-ad68-00e766b34c0e', 'fba33f86-dbf8-51a7-a563-eb1b5ba99745', 'b4a07435-8c26-5bbb-a5bb-91c235188e4d', 5, 42, 'ጥቂት ይበቃል፤ ያም ባይሆን አንድ ይበቃል፤ ማርያምስ የማይቀሙአትን መልካም ዕድል መረጠች።”'),
  ('752d4f35-f646-55cc-aac6-4bc77c168890', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 1, 1, 'ከዚህም በኋላ በአንዲት ቦታ ጸለየ፤ ጸሎቱን በጨረሰ ጊዜም ከደቀ መዛሙርቱ አንዱ፥ “ጌታ ሆይ፥ ዮሐንስ ለደቀ መዛሙርቱ እንደ አስተማራቸው ጸሎት አስተምረን” አለው።'),
  ('f3910c17-8bbb-5dbd-a4b2-304b41648bc2', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 2, 2, 'እርሱም እንዲህ አላቸው፥ “በምትጸልዩበት ጊዜ እንዲህ በሉ፦ በሰማያት የምትኖር አባታችን ሆይ፥ ስምህ ይቀደስ፤ መንግሥትህ ትምጣ፤ ፈቃድህ በሰማይ እንደ ሆነ እንዲሁም በምድር ይሁን።'),
  ('d299aa5b-43ed-5ee8-aae0-65e1cdb36745', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 3, 3, 'የዕለት ምግባችንን በየዕለቱ ስጠን።'),
  ('ae6f362f-ddbb-53ce-a25e-a9ac60cea365', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 4, 4, 'እኛም የበደለንን ሁሉ ይቅር እንድንል በደላችንን ይቅር በለን፤ አቤቱ፥ ወደ ፈተና አታግባን፤ ከክፉ ሁሉ አድነን እንጂ።”'),
  ('c738105e-3ce3-5b93-a434-acb931701dd0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 5, 5, 'እንዲህም አላቸው፥ “ከመካከላችሁ ወዳጅ ያለው ሰው ቢኖር በመንፈቀ ሌሊትም ወደ እርሱ ሄዶ እንዲህ ቢለው፦ ‘ወዳጄ ሆይ ሦስት እንጀራ አበድረኝ።'),
  ('35ddc8ba-3db8-54e3-a25f-d3d347e13428', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 6, 6, 'ወዳጄ ከመንገድ መጥቶብኛልና የማቀርብለት የለኝም።’'),
  ('358887f7-316c-5bba-a4c0-d8c2b64c2d18', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 7, 7, 'ያ ወዳጁም ከውስጥ ሆኖ፦ ‘አትዘብዝበኝ፤ ደጁን አጥብቀን ዘግተናል፤ ልጆችም ከእኔ ጋር በአልጋ ላይ ተኝተዋል፤ እሰጥህ ዘንድ መነሣት አልችልም’ ይለዋልን?'),
  ('6837d3c7-ab4b-5742-adcd-edc403a21b3c', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 8, 8, 'ወዳጁ ስለሆነ ሊሰጠው ባይነሣ እንኳ እንዳይዘበዝበው ተነሥቶ የወደደውን ያህል ይሰጠዋል።'),
  ('ba53b352-4ff2-5d1d-afa4-a2ecda8f5e3d', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 9, 9, 'እኔም እላችኋለሁ፦ ለምኑ፥ ይሰጣችኋልም፤ ፈልጉ፥ ታገኛላችሁም፤ ደጅ ምቱ፥ ይከፈትላችኋልም።'),
  ('ff74e9c2-b9f0-57f9-a372-e32241535127', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 10, 10, 'የሚለምን ሁሉ ይሰጠዋልና፤ የሚፈልግም ያገኛልና፤ ደጅ ለሚመታም ይከፈትለታልና።'),
  ('f6225dbc-e4f3-5e59-a5a4-7c7928627f59', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 11, 11, 'ከእናንተ መካከል ልጁ ዳቦ የሚለምነው አባት ቢኖር ድንጋይ ይሰጠዋልን? ዓሣ ቢለምነውስ በዓሣ ፋንታ እባብን ይሰጠዋልን?'),
  ('4ff92eaa-aa43-5015-afcf-96e39f84c2e0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 12, 12, 'ወይስ ዕንቍላል ቢለምነው በዕንቍላል ፋንታ ጊንጥ ይሰጠዋልን?'),
  ('087e9dc1-75dc-50f7-a936-41f73fbee4e0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'fcc43c0d-17f4-5fe6-acc1-64faddbdd7dc', 13, 13, 'እናንተ ክፉዎች ስትሆኑ ለልጆቻችሁ መልካም ስጦታን መስጠትን የምታውቁ ከሆነ፥ የሰማይ አባታችሁማ ለሚለምኑት መልካሙን ሀብተ መንፈስ ቅዱስ እንዴት አብዝቶ ይሰጣቸው ይሆን?”'),
  ('37488daf-92ab-5836-a8b7-6a9f361adecb', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 1, 14, 'ዲዳና ደንቆሮ ጋኔንንም ያወጣ ነበር፤ ጋኔኑም በወጣ ጊዜ ዲዳና ደንቆሮ የነበረው ተናገረ፤ ሰዎችም አደነቁ።'),
  ('d80c02bc-5a65-53f9-a4b5-f62a1a4df262', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 2, 15, 'ነገር ግን ከመካከላቸው፥ “በአጋንንት አለቃ በብዔል ዜቡል አጋንንትን ያወጣቸዋል” ያሉ ነበሩ፤ እርሱም መልሶ፥ “ሰይጣን ሰይጣንን ማውጣት እንደምን ይቻለዋል?” አላቸው።'),
  ('ff5ee4e8-c1b7-5ac7-a6f2-b525841c237c', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 3, 16, 'ሌሎችም ሊፈትኑት ከእርሱ ዘንድ ከሰማይ ምልክትን ይፈልጉ ነበር።'),
  ('f9338daf-922f-5185-a39a-753af380dfee', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 4, 17, 'እርሱ ግን የሚያስቡትን ዐወቀባቸውና እንዲህ አላቸው፥ “እርስ በርስዋ የምትለያይ መንግሥት ሁሉ ትጠፋለች፤ ቤትም እርስ በርሱ ቢለያይ ያ ቤት ይወድቃል።'),
  ('df46bb27-ce82-5d8a-af92-956e434c7eb3', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 5, 18, 'ሰይጣንስ እርስ በርሱ ከተለያየ መንግሥቱ እንዴት ይጸናል? በአጋንንት አለቃ በብዔል ዜቡል አጋንንትን ያወጣል ትላላችሁና።'),
  ('12aa684c-d1bc-5535-a970-b17778440641', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 6, 19, 'እኔ በብዔል ዜቡል አጋንንትን የማወጣ ከሆነ፥ ልጆቻችሁ በምን ያወጡአቸዋል? ስለዚህ እነርሱ ይፋረዱአችኋል።'),
  ('921ca284-f310-57a0-ade8-d8a5e9b3d910', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 7, 20, 'እኔ በእግዚአብሔር ጣት አጋንንትን የማወጣ ከሆነ እንግዲህ አሁን የእግዚአብሔር መንግሥት ወደ እናንተ ደርሳለች።'),
  ('5c26e310-1127-50db-a373-9b26da464821', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 8, 21, 'ኀይለኛ ሰው በጦር መሣሪያ ቤቱን የጠበቀ እንደ ሆነ ገንዘቡ ሁሉ ደኅና ይሆናል።'),
  ('144bb4f5-8b1b-555b-a61f-e5040ada5c38', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 9, 22, 'ከእርሱ የሚበረታው ቢመጣና ቢያሸንፈው ግን፥ ይታመንበት የነበረውን የጦር መሣሪያውን ይገፈዋል፤ የማረከውንና የዘረፈውን ገንዘቡንም ይወስዳል።'),
  ('e9059d04-8051-597b-aca6-7fd7153507aa', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 10, 23, 'ከእኔ ጋር ያልሆነ ባለጋራዬ ነው፤ ከእኔ ጋር የማይሰበስብም ይበትንብኛል።'),
  ('5fab2f36-77fc-55e0-a9ef-8df1bf227311', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 11, 24, '“ክፉ ጋኔንም ከሰው በወጣ ጊዜ ውኃ ወደሌለበት ምድረ በዳ ይሄዳል፤ የሚያርፍበትንም መኖሪያ ይሻል፤ ያላገኘ እንደ ሆነም ወደ ወጣሁበት ቤቴ እመለሳለሁ ይላል።'),
  ('1fdca8d7-c7ba-589a-ae69-06bb036eb9ba', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 12, 25, 'በመጣም ጊዜ ተጠርጎ አጊጦም ያገኘዋል።'),
  ('8d04564c-b0e6-591a-aeec-cc5ce6b93546', 'c094ca36-abee-5475-ac0d-67a994887a43', '3202d8c6-a731-52e0-ab5d-a9c1ff612b21', 13, 26, 'ከዚህም በኋላ ይሄድና ከእርሱ የሚከፉ ሌሎች ባልንጀሮቹን ሰባት አጋንንት ያመጣል፤ ገብተውም በዚያ ሰው ያድሩበታል፤ ለዚያ ሰውም ከፊተኛው ይልቅ የኋለኛው የከፋ ይሆንበታል።”'),
  ('31d61608-3bc4-58a6-ab19-7c1d07fa050c', 'c094ca36-abee-5475-ac0d-67a994887a43', 'ac4b096e-679a-51e6-acf6-c0c5c809a869', 1, 27, 'ከዚህም በኋላ ይህን ሲናገር ከሕዝቡ መካከል አንዲት ሴት ድምፅዋን አሰምታ፥ “የተሸከመችህ ማኅፀን ብፅዕት ናት፤ የጠባሃቸው ጡቶችም ብፁዓት ናቸው” አለችው።'),
  ('3539178f-5aae-5ec2-aa2b-c89d1d111e06', 'c094ca36-abee-5475-ac0d-67a994887a43', 'ac4b096e-679a-51e6-acf6-c0c5c809a869', 2, 28, 'እርሱም፥ “ብፁዓንስ የእግዚአብሔርን ቃል ሰምተው የሚጠብቁ ናቸው” አላት።'),
  ('79ac9260-1459-56a7-ade9-bd9eddff36b7', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 1, 29, 'ብዙ ሰዎችም ተሰብስበው ሳሉ እንዲህ ይላቸው ጀመረ ፥ “ይቺ ትውልድ ክፉ ናት፤ ምልክትም ትሻለች፤ ነገር ግን ከነቢዩ ከዮናስ ምልክት በቀር ምልክት አይሰጣትም።'),
  ('1d869f45-77d7-5273-a16c-a233b310a2b0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 2, 30, 'ዮናስ ለነነዌ ሰዎች ምልክት እንደ ሆናቸው የሰው ልጅም ለዚች ትውልድ እንዲሁ ምልክት ይሆናታል።'),
  ('d3cffd9a-dd48-5b6b-aaa8-4f79b396ef5c', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 3, 31, 'የአዜብ ንግሥት በፍርድ ቀን ከዚች ትውልድ ጋር ተነሥታ ትፋረዳቸዋለች፤ የሰሎሞንን ጥበብ ልትሰማ ከምድር ዳርቻ መጥታለችና፤ እነሆ፥ ከሰሎሞን የሚበልጥ በዚህ አለ።'),
  ('d6ccc4bc-72da-50c7-a656-6778921b570f', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 4, 32, 'የነነዌ ሰዎች በፍርድ ቀን ከዚች ትውልድ ጋር ተነሥተው ይፋረዱአታል፤ ያሳፍሩአታልም፤ ዮናስ በሰበከላቸው ጊዜ ንስሓ ገብተዋልና፤ እነሆ፥ ከዮናስ የሚበልጥ በዚህ አለ።'),
  ('d0fbf9ad-fb0a-589f-a9a7-8833f632e8ad', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 5, 33, '“በስውር ቦታ ወይም ከዕንቅብ በታች ሊያኖራት መብራትን የሚያበራ የለም፤ የሚመላለሱ ሁሉ ብርሃንን ያዩ ዘንድ በመቅረዝዋ ላይ ያኖራታል እንጂ።'),
  ('5959e17a-6e84-53e8-a95c-a0f8072b2c38', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 6, 34, 'የሰውነትህ መብራት ዐይንህ ነው፤ ዐይንህ ብሩህ ከሆነ ሰውነትህ ሁሉ ብሩህ ነው፤ ዐይንህ ታማሚ ቢሆን ግን፤ ሰውነትህ ሁሉ ጨለማ ነው።'),
  ('d6dec0a3-a695-5a8e-a449-351c428e2d28', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 7, 35, 'እንግዲህ ብርሃንህ ጨለማ እንዳይሆን ተጠንቀቅ።'),
  ('bdd7d770-8324-565a-a3ce-fdbbbff3fb01', 'c094ca36-abee-5475-ac0d-67a994887a43', 'a10bc7b4-dbef-52da-af26-161458a9ba76', 8, 36, 'ሰውነትህ ሁሉ ብሩህ ከሆነ በአንተም ላይ ምንም ጨለማ ባይኖርብህ የመብረቅ ብርሃን እንደሚያበራልህ ሁለንተናህ ብሩህ ይሆናል።”'),
  ('dc0c96b0-3be9-5117-a9a1-1482d589a227', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 1, 37, 'ይህንም ሲነግራቸው አንድ ፈሪሳዊ በእርሱ ዘንድ ምሳ እንዲበላ ለመነው፤ ገብቶም ለምሳ ተቀመጠ።'),
  ('9e965f49-dd63-5bfd-a909-d7ddbe845e79', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 2, 38, 'ፈሪሳዊዉም አይቶ አደነቀ፤ ምሳ ለመብላት እጁን አልታጠበም ነበርና።'),
  ('2785b52b-cf34-535a-abac-02db69d01449', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 3, 39, 'ጌታችን ኢየሱስም እንዲህ አለው፥ “እናንተ ፈሪሳውያን፥ ዛሬ የጽዋውንና የወጭቱን ውጭውን ታጥቡታላችሁ፤ ታጠሩታላችሁም፤ ውስጡ ግን ቅሚያንና ክፋትን የተመላ ነው።'),
  ('50f196ec-8baf-5f91-accb-d0d260e5e385', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 4, 40, 'እናንተ ሰነፎች፥ የውጭውን የፈጠረ የውስጡንስ የፈጠረ አይደለምን?'),
  ('e0049960-310c-54b3-aff1-a26abf0dc3b0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 5, 41, 'ነገር ግን የሚወደደውን ምጽዋት አድርጋችሁ ስጡ፤ ሁሉም ንጹሕ ይሆንላችኋል።'),
  ('0f9592e0-0f75-5bb9-a93b-77c90f852785', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 6, 42, 'የእንስላልና የጤና አዳም፥ ከአትክልትም ሁሉ ዐስራት የምታገቡ ፍርድንና የእግዚአብሔርን ፍቅር ቸል የምትሉ እናንተ ጻፎችና ፈሪሳውያን፥ ወዮላችሁ! ይህንም ልታደርጉ ይገባችኋል፥ ያንም አትተዉ።'),
  ('946b28a7-26db-5385-ab51-06ef1cbebae0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 7, 43, 'እናንተ ግብዞች ጻፎችና ፈሪሳውያን፥ ወዮላችሁ! በምኵራብ ፊት ለፊት መቀመጥን፥ በገበያም እጅ መነሣትን ትወዳላችሁና።'),
  ('82dbdb39-cfab-5b41-a87b-fdc51c849476', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 8, 44, 'እናንተ ግብዞች ጻፎችና ፈሪሳውያን፥ ወዮላችሁ! ሰዎች ሳያውቁ በላዩ እንደሚመላለሱበት እንደ ተሰወረ መቃብር ናችሁና።”'),
  ('420cf6e4-5e6a-5828-abe4-f04bd4e0f491', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 9, 45, 'ከሕግ ዐዋቂዎችም አንዱ መልሶ፥ “መምህር ሆይ፥ ይህን ስትል እኛን እኮ መስደብህ ነው” አለው።'),
  ('947133f7-8e4a-53b2-a0f9-f79a5e3eff70', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 10, 46, 'እርሱም እንዲህ አለው፤ “ለእናንተ ለሕግ ዐዋቂዎች ወዮላችሁ! ሰውን ከባድ ሸክም ታሸክሙታላችሁ፤ እናንተ ግን ያን ሸክም በአንዲት ጣታችሁ እንኳን አትነኩትም።'),
  ('01b584cc-9203-5dac-aeb5-006a51e50d98', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 11, 47, 'እናንተ ጻፎችና ፈሪሳውያን፥ ወዮላችሁ! አባቶቻችሁ የገደሉአቸውን የነቢያትን መቃብር ትሠራላችሁና።'),
  ('e30c60ba-2b7a-55e6-ab06-27a72e193cef', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 12, 48, 'የአባቶቻችሁም ሥራ ደስ አሰኝቶአችኋል፤ የምትመሰክሩባቸውም እናንተ ራሳችሁ ናችሁ፤ እነርሱ የገደሉአቸውን መቃብራቸውን እናንተ ትሠራላችሁና።'),
  ('60e6d6ec-0be4-5563-ab54-092b9ef85457', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 13, 49, 'ስለዚህ የእግዚአብሔር ጥበቡ እንዲህ አለች፦ እነሆ፥ እኔ ነቢያትንና ሐዋርያትን ወደ እነርሱ እልካለሁ፤ ከእነርሱም ይገድላሉ፤ ያሳድዳሉም።'),
  ('7a5d3da4-5f96-545b-a4b0-440fc7c4d4c0', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 14, 50, 'ዓለም ከተፈጠረ ጀምሮ እስከዚህች ትውልድ ድረስ ስለ ፈሰሰው ስለ ነቢያት ሁሉ ደም ይበቀላቸው ዘንድ፥'),
  ('b867f702-b019-5a3d-a132-2dbd7cb1cc23', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 15, 51, 'ከአቤል ደም ጀምሮ በመሠዊያውና በቤተ መቅደሱ መካከል እስከ ገደሉት እስከ ዘካርያስ ደም ድረስ እውነት እላችኋለሁ ከዚች ትውልድ ይፈለጋል።'),
  ('7af2efbf-c367-5ba4-a7a7-867ab1fb8ac6', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 16, 52, 'እናንተ ጻፎችና ፈሪሳውያን፥ ወዮላችሁ! የጽድቅንና የዕውቀትን መክፈቻ ወስዳችሁ ትሰውራላችሁና፤ እናንተም አትገቡምና፤ የሚገቡትንም መግባትን ትከለክሉአቸዋላችሁ።”'),
  ('6f6d5b7c-e296-5a50-a245-2485e043f6d3', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 17, 53, 'በሕዝቡም ሁሉ ፊት ይህን ሲነግራቸው ጻፎችና ፈሪሳውያን አጽንተው ይጣሉት፥ ይቀየሙትም ጀመር።'),
  ('748381f8-1d1e-5ff7-a600-0391aca8a626', 'c094ca36-abee-5475-ac0d-67a994887a43', 'cf064643-5583-5e28-a5a3-0869c6c6a34e', 18, 54, 'በአነጋገሩም ሊያስቱትና ሊያጣሉት ያደቡበት ነበር።'),
  ('a62560e9-d977-5f78-ac9e-d94fc20ec52f', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 1, 1, 'በዚያን ጊዜም እጅግ ብዙ ሰዎች እርስ በርሳቸው እስኪረጋገጡ ድረስ ወደ እርሱ ተሰበሰቡ፤ ደቀ መዛሙርቱንም እንዲህ ይላቸው ጀመረ፥ “አስቀድማችሁ ከፈሪሳውያን እርሾ ተጠበቁ፤ ይኸውም ግብዝነት ነው።'),
  ('e883c345-f41f-5abc-ac9a-f896017ef41f', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 2, 2, 'የማይገለጥ የተሰወረ፥ የማይታይም የተሸሸገ የለምና።'),
  ('f8cb3c09-b371-5e08-af5c-47cb74a8243e', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 3, 3, 'በጨለማ የምትናገሩት በብርሃን ይሰማል፤ በእልፍኝም ውስጥ በጆሮ የምትንሾካሾኩት በሰገነት ይሰበካል።'),
  ('17a23425-d5ef-55eb-ac9a-865032562d55', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 4, 4, 'ለእናንተ ለወዳጆች እላችኋለሁ፦ ሥጋችሁን የሚገድሉትን አትፍሩአቸው፤ ከዚህም የበለጠ ማድረግ የሚችሉት የላቸውም።'),
  ('f66107e7-cebb-50ad-a096-68ed582fc0f7', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 5, 5, 'ነገር ግን፤ የምትፈሩትን አሳያችኋለሁ፤ እናንተስ ከገደለ በኋላ ወደ ገሃነም ሊጥል ሥልጣን ያለውን ፍሩት፤ አዎ፥ እላችኋለሁ፤ እርሱን ፍሩ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4909e384-dbb0-51c3-a8e7-cf1956688418', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 6, 6, 'አምስት ወፎች በሁለት ሻሚ መሐለቅ ይሸጡ የለምን? ከእነርሱ አንዲቱ ስንኳን በእግዚአብሔር ፊት አትረሳም።'),
  ('e1f1ab16-0796-5207-a7fd-ee66f7460bde', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 7, 7, 'የእናንተስ የራስ ጠጕራችሁ ሁሉ የተቈጠረ ነው፤ እንግዲህ አትፍሩ፤ ከብዙ ወፎች እናንተ ትበልጣላችሁና።'),
  ('a378c7cb-4aa0-5104-a9e5-75bef091927f', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 8, 8, '“እላችኋለሁ፦ በሰው ፊት የሚያምንብኝን ሁሉ እኔም በእግዚአብሔር መላእክት ፊት አምነዋለሁ።'),
  ('8f3b38fb-41a6-5149-a7ff-2f7c19089042', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 9, 9, 'በሰው ፊት የሚክደኝን ግን እኔም በእግዚአብሔር መላእክት ፊት እክደዋለሁ።'),
  ('750060a9-8be6-5cb3-ad08-c74a302e7bde', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 10, 10, 'በሰው ልጅ ላይ የስድብ ቃል የሚናገር ሁሉ ይሰረይለታል፤ በመንፈስ ቅዱስ ላይ የስድብ ቃል የሚናገር ግን በዚህ ዓለምም ሆነ በሚመጣው ዓለም አይሰረይለትም።'),
  ('6b783948-252b-5971-a9fe-c196e8562468', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 11, 11, 'ወደ አደባባይ ወደ ሹሞቹና ወደ ነገሥታቱ፥ ወደ መኳንንቱም በሚወስዱአችሁ ጊዜ የምትሉትንና የምትናገሩትን አታስቡ።'),
  ('5360aea6-4bde-5b6c-a49d-9f0db0c0ee69', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '4fea84b3-143c-5b27-a4d1-89d8993c0c22', 12, 12, 'ያንጊዜ በእናንተ ላይ የሚናገረው መንፈስ ቅዱስ ነውና።”'),
  ('e57679e4-0274-5b3b-a4d0-532bd23f842e', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '57e7758c-96c0-50a9-aa64-a95bbf6a802d', 1, 13, 'ከሕዝቡም አንዱ፥ “መምህር ሆይ፥ ርስቴን እንዲያካፍለኝ ለወንድሜ ንገረው” አለው።'),
  ('f8ed08b9-e517-5f12-afa3-de7d11117843', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '57e7758c-96c0-50a9-aa64-a95bbf6a802d', 2, 14, 'ጌታችን ኢየሱስም፥ “አንተ ሰው፥ በእናንተ ላይ አካፋይና ዳኛ አድርጎ ማን ሾመኝ?” አለው።'),
  ('02150dcd-670f-5d37-a6eb-e9ed0b9d798f', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '57e7758c-96c0-50a9-aa64-a95bbf6a802d', 3, 15, '“ዕወቁ፤ ከቅሚያም ሁሉ ተጠበቁ፤ ሰው የሚድን ገንዘብ በማብዛት አይደለምና” አላቸው።'),
  ('c64ae1e9-ad3d-5399-a93a-4722d837cf2a', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '6de0c034-ab49-5b8f-ae23-2f34c5669db6', 1, 16, 'ምሳሌም መሰለላቸው፤ እንዲህም አላቸው፤ “እርሻው የበጀለትና ሀገር የተመቸው አንድ ባለጸጋ ሰው ነበረ።'),
  ('27717121-8318-5ddd-a0e0-602764638a44', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '6de0c034-ab49-5b8f-ae23-2f34c5669db6', 2, 17, 'እህሌን የማኖርበት የለኝምና ምን ላድርግ ብሎ በልቡ ዐሰበ።'),
  ('75528a57-e85c-5df5-a219-81652ed21d5e', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '6de0c034-ab49-5b8f-ae23-2f34c5669db6', 3, 18, 'እርሱም አለ፦ እንዲህ አደርጋለሁ፤ የቀድሞውን ጎተራዬን አፈርሳለሁ፤ ከእርሱ የሚበልጥ ሌላ ጎተራም እሠራለሁ፤ እህሌንና በረከቴንም በዚያ እሰበስባለሁ።'),
  ('88f815dc-f457-582f-a80f-aa033ead63c7', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '6de0c034-ab49-5b8f-ae23-2f34c5669db6', 4, 19, 'ሰውነቴንም እንዲህ እላታለሁ፦ ሰውነቴ ሆይ፥ የሰበሰብሁልሽ ለብዙ ዓመታት የሚበቃሽ የደለበ ብዙ ሀብት አለሽ፤ እንግዲህ ወዲህ ዕረፊ፥ ብዪ፤ ጠጪም፤ ደስም ይበልሽ።'),
  ('fc195568-4c64-5ce6-a4bc-e038b949c66f', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '6de0c034-ab49-5b8f-ae23-2f34c5669db6', 5, 20, 'እግዚአብሔርም፦ አንተ ሰነፍ! በዚች ሌሊት ነፍስህን ከሥጋህ ለይተው ይወስዷታል፤ እንግዲህ ያጠራቀምኸው ለማን ይሆናል? አለው።'),
  ('b5abc1cc-0df7-5a59-a374-2e5d870743d9', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '6de0c034-ab49-5b8f-ae23-2f34c5669db6', 6, 21, 'ሀብትን ለራሱ የሚሰበስብ፤ ሀብቱም ከእግዚአብሔር ያልሆነ እንዲሁ ነው።”'),
  ('0211e94b-7eda-5fd0-abbe-fcf571c3206d', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 1, 22, 'ለደቀ መዛሙርቱም እንዲህ አላቸው፥ “ስለዚህ እላችህዋለሁ፤ ለነፍሳችሁ ስለምትበሉትና ስለምትጠጡት፥ ለሰውነታችሁም ስለምትለብሱት አትጨነቁ።'),
  ('fb1025f8-3611-5e26-a963-f409136a5daf', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 2, 23, 'ነፍስ ከምግብ ትበልጣለችና፤ ሰውነትም ከልብስ ይበልጣልና።'),
  ('cbdec5b1-dc45-5dcc-aa50-50213e82ea71', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 3, 24, 'የማይዘሩትንና የማያጭዱትን፥ ጎተራና ጕድጓድ የሌላቸውን የቍራዎችን ጫጭቶች ተመልከቱ፤ እግዚአብሔር ግን ይመግባቸዋል፤ እንግዲህ እናንተ ከወፎች እንዴት እጅግ አትበልጡም?'),
  ('3c77ec40-5bb3-5cfc-a011-211ab8806002', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 4, 25, 'ከእናንተስ ዐስቦ በቁመቱ ላይ አንድ ክንድ መጨመር የሚቻለው ማነው?'),
  ('19b94009-40bd-5d41-a62d-101478512880', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 5, 26, 'ይህን ቀላሉን የማትችሉ ከሆነ በሌላው ለምን ትጨነቃላችሁ?'),
  ('17ea1cd0-848d-5624-a674-0be170be8d5b', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 6, 27, 'እነሆ፥ አበባዎችን እንደሚያድጉ ተመልከቱ፤ አይፈትሉም፤ አይደክሙም፤ ነገር ግን እላችኋለሁ፤ ሰሎሞን እንኳ በክብሩ ዘመን ሁሉ ከእነርሱ እንደ አንዱ አልለበሰም።'),
  ('58e2300e-e8cf-5c09-ae54-2b13cdb525eb', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 7, 28, 'እነሆ፥ ዛሬ ያለውን፥ ነገም ወደ እሳት የሚጣለውን የአበባ አገዳ እግዚአብሔር እንዲህ የሚያደርገው ከሆነ፥ እናንተ እምነት የጐደላችሁ፥ ለእናንተማ እንዴት አብልጦ አያደርግላችሁ?'),
  ('f37885b0-c6c5-5fd4-a501-5b25f02fb9d5', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 8, 29, 'እናንተም የምትበሉትንና የምትጠጡትን አትፈልጉ፤ ወዲያና ወዲህም አትበሉ፤ አትጨነቁለትም።'),
  ('0c5087f3-b58a-5360-a532-6514d4436759', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 9, 30, 'ይህን ሁሉ በውጭ ያሉ የዓለም አሕዛብ ይሹታልና፤ ለእናንተስ አባታችሁ ይህን ሁሉ እንደምትሹት ያውቃል።'),
  ('0dd020ab-4dfe-5dce-ae0a-a1dfb4be72ff', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 10, 31, 'ነገር ግን የእግዚአብሔርን መንግሥትና ጽድቅ ሹ፤ ይህም ሁሉ ይጨመርላችኋል።'),
  ('9c5f49cd-18cd-5b20-a15c-0deb528eb931', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 11, 32, '“አንተ ታናሽ መንጋ፥ አትፍራ፤ አባታችሁ መንግሥቱን ሊሰጣችሁ ወዶአልና።'),
  ('4ccc579c-779b-5e39-ac38-0d8f27dc4060', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 12, 33, 'ሀብታችሁን ሸጣችሁ ምጽዋት ስጡ፤ ሌባ በማያገኝበት ነቀዝም በማያበላሽበት፥ የማያረጅ ከረጢት፥ የማያልቅም መዝገብ በሰማያት ለእናንተ አድርጉ።'),
  ('0a07c18b-e0b9-595b-ab91-7b4819bc7d05', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '1139556f-abf4-5603-a9e6-ee55d8474581', 13, 34, 'መዝገባችሁ ካለበት ልባችሁ በዚያ ይኖራልና።'),
  ('320f8ec8-dcaf-573d-aca4-2e237144c43a', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 1, 35, '“ወገባችሁ የታጠቀ መብራታችሁም የበራ ይሁን።'),
  ('9ef267b1-6dca-5c9a-a98e-15f188b771e4', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 2, 36, 'እናንተም፥ በመጣና በር በመታ ጊዜ ወዲያው ይከፍቱለት ዘንድ ከሰርግ እስኪመለስ ጌታቸውን እንደሚጠብቁ ሰዎች ሁኑ።'),
  ('7c94d824-7e5e-59bf-a0f4-6477d752b63c', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 3, 37, 'ጌታቸው በመጣ ጊዜ እንዲህ ሲያደርጉና ሲተጉ የሚያገኛቸው አገልጋዮች ብፁዓን ናቸው፤ እውነት እላችኋለሁ፤ ወገቡን ታጥቆ በማዕድ ያስቀምጣቸዋል፤ እየተመላለሰም ያገለግላቸዋል።'),
  ('e49550ab-efc2-58bf-a087-26c490103cf2', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 4, 38, 'ከሌሊቱ በሁለተኛው ወይም በሦስተኛው ክፍል ቢመጣና እንዲሁ ቢያገኛቸው እነዚያ አገልጋዮች ብፁዓን ናቸው።'),
  ('0809579a-632a-57ef-aaaf-fd3d475100cd', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 5, 39, 'ነገር ግን ይህን ዕወቁ፤ ባለቤት ሌባ የሚመጣበትን ጊዜ ቢያውቅ ተግቶ በጠበቀ፥ ቤቱንም እንዲቈፍሩት ባልፈቀደም ነበር።'),
  ('f82c6272-ea4b-5acf-abbb-965855cd344c', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 6, 40, 'እናንተም ተዘጋጅታችሁ ኑሩ፤ የሰው ልጅ ባልጠረጠራችሁበት ሰዓት ይመጣልና።”'),
  ('43600724-0cce-5354-a772-aedd0662ea80', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 7, 41, 'ጴጥሮስም፥ “አቤቱ፥ ይህን ምሳሌ የምትናገረው ለእኛ ነውን? ወይስ ለሁሉ ነው?” አለው።'),
  ('5fbb09b6-1ea9-5cbd-a0ac-3af7920c5e42', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 8, 42, 'ጌታችንም እንዲህ አለው፥ “ምግባቸውን በየጊዜው ይሰጣቸው ዘንድ ጌታው በቤተሰቡ ላይ የሚሾመው ደግ ታማኝና ብልህ መጋቢ ማን ይሆን?'),
  ('e6403268-0cb4-5833-a521-12df2c735c9b', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 9, 43, 'ጌታው በመጣ ጊዜ እንዲህ ሲያደርግ የሚያገኘው አገልጋይ ብፁዕ ነው።'),
  ('f278f829-1965-53f9-a9c8-2b2ce3122b8f', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 10, 44, 'እውነት እላችኋለሁ፥ በሀብቱ ሁሉ ላይ ይሾመዋል፤'),
  ('1a15e90a-e71c-5872-a76d-a1cc4b6efddd', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 11, 45, 'ነገር ግን ያ ክፉ አገልጋይ በልቡ፦ ጌታዬ ቶሎ አይመጣም ቢል፥ በጌታው ቤት ያሉትንም ወንዶችንና ሴቶችን አገልጋዮች ሊደበድብና ሊያጕላላ ቢጀምር፥ ከሰካራሞችም ጋር ቢበላና ቢጠጣ፥ ቢሰክርም፥'),
  ('7fa9e10f-3be6-5320-a7a2-72d884471bf1', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 12, 46, 'የዚያ አገልጋይ ጌታ ባልጠረጠረው ዕለት፥ ባላወቀውም ሰዓት መጥቶ ከሁለት ይሰነጥቀዋል፤ ዕድሉንም ከማይታመኑ ጋር ያደርገዋል።'),
  ('b5cd56bf-c18b-50c3-ab26-d249024e9682', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 13, 47, 'የጌታውን ፈቃድ ዐውቆ እንደ ፈቃዱ የማይሠራና የማያዘጋጅ የዚያ አገልጋይ ቅጣቱ ብዙ ነው።'),
  ('46fc2343-dade-5e8b-a7a5-05cda4bb74d7', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '9253ac87-bddb-57a3-af82-427458633689', 14, 48, 'ያላወቀ ግን ባይሠራም ቅጣቱ ጥቂት ነው፤ ብዙ ከሰጡት ብዙ ይፈልጉበታልና። ጥቂት ከሰጡትም ጥቂት ይፈልጉበታልና።'),
  ('a5d0c546-5e4d-56e5-abfd-bc175e98c22d', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 1, 49, '“በምድር ላይ እሳትን አምጥቼአለሁ፤ እርስዋን ከማንደድ በቀር ምን እሻለሁ?'),
  ('f5464474-0056-5642-a784-54f85993d529', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 2, 50, 'ነገር ግን፤ የምጠመቃት ጥምቀት አለችኝ፤ እስክፈጽማትም ድረስ እጅግ እታገሣለሁ።”'),
  ('3df16cbc-9970-5e6a-a394-c8352364de9e', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 3, 51, 'ሕዝቡንም እንዲህ አላቸው፥ “ለምድር ሰላምን ያመጣሁ ይመስላችኋልን? እላችኋለሁ፤ አይደለም፤ ሰይፍንና መለያየትን ነው እንጂ።'),
  ('0ec2e80e-37f6-5039-ab7d-e1c3a93b167c', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 4, 52, 'ከእንግዲህስ ወዲህ አምስት ሰዎች በአንድ ቤት ቢኖሩ ሦስቱ ከሁለቱ፥ ሁለቱም ከሦስቱ ይለያሉ፤'),
  ('f93eedcf-41d1-577a-abc8-d9c1e0571968', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 5, 53, 'አባት ከልጁ፥ ልጅም ከአባቱ ይለያል፤ እናት ከልጅዋ፥ ልጅም ከእናቷ ትለያለች፤ አማት ከምራቷ፥ ምራትም ከአማቷ ትለያለች።”'),
  ('19a749b9-b1be-5a6b-a5fd-8a538cb0ad20', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 6, 54, 'ከዚህም በኋላ ሕዝቡን እንዲህ አላቸው፥ “ደመና በምዕራብ በኩል ደምኖ ባያችሁ ጊዜ ‘ዝናም ይመጣል’ ትላላችሁ፤ እንዲሁም ይሆናል።'),
  ('81285c57-e3a5-5a1e-a90c-820477f07c30', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 7, 55, 'የአዜብ ነፋስ በነፈሰ ጊዜም ‘ድርቅ ይሆናል፤’ ትላላችሁ እንዲሁም ይሆናል።'),
  ('8612d86f-2cbf-5c21-ae50-0ab4ed6fe4a1', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 8, 56, 'እናንት ግብዞች! የሰማዩንና የምድሩን ፊት መመርመር ታውቃላችሁ፤ ነገር ግን እነዚህን ዘመናት መመርመርን እንዴት አታውቁም?'),
  ('6d914d35-812b-5f16-adee-83e7d8ad69e4', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 9, 57, 'እናንተ ራሳችሁ እውነቱን ለምን አትፈርዱም?'),
  ('a6652a44-6b93-5f9f-ac28-a8faf80b38d0', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 10, 58, 'ከባለጋራህ ጋር ወደ ሹም በምትሄድበት ጊዜ ወደ ዳኛ እንዳይወስድህ በመንገድ ሳለህ ታረቅ፤ ዕዳህንም ክፈል፤ ዳኛው ለሎሌው አሳልፎ ይሰጥሃልና። ሎሌውም በወኅኒ ቤት ያስርሃል።'),
  ('1f3f435d-e279-55d4-a4a3-2a13c1a0ebe3', 'feb131b2-8650-55fb-a8c3-0265f9d64930', '90d5e3ae-8355-5cca-a447-b0d9de513665', 11, 59, 'ያለብህን የመጨረሻዋን ግማሽ ሣንቲም ቢሆን እስክትጨርስ ድረስ አትወጣም እልሃለሁ።”'),
  ('d38a18ac-7e60-50a2-a555-e1bb6060fd1a', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '0ca9cc14-ec0b-5b3e-aa6c-497dfb8d26b4', 1, 1, 'በዚያ ወራትም ሰዎች ወደ እርሱ መጥተው ጲላጦስ ደማቸውን ከመሥዋዕታቸው ጋር ስለ ቀላቀለው ስለ ገሊላ ሰዎች ነገሩት።'),
  ('177bdd58-ebf1-51da-a1e3-4a84c8076fef', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '0ca9cc14-ec0b-5b3e-aa6c-497dfb8d26b4', 2, 2, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “ይህች መከራ ስለ አገኘቻቸው እነዚህ ገሊላውያን ከገሊላ ሰዎች ሁሉ ይልቅ ተለይተው ኀጢኣተኞች የሆኑ ይመስሉአችኋልን?'),
  ('dff3b0ce-324b-5e31-a44d-d50b2efca355', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '0ca9cc14-ec0b-5b3e-aa6c-497dfb8d26b4', 3, 3, 'አይደለም፤ እላችኋለሁ፤ እናንተም ንስሓ ካልገባችሁ ሁላችሁ እንደ እነርሱ ትጠፋላችሁ።'),
  ('d45b1af0-7cfd-53a6-aff7-e90736cc2f37', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '0ca9cc14-ec0b-5b3e-aa6c-497dfb8d26b4', 4, 4, 'ወይስ እነዚያ በሰሊሆም ግንብ ተጭኖ የገደላቸው ዐሥራ ስምንቱ ሰዎች ከኢየሩሳሌም ሰዎች ይልቅ ተለይተው ኀጢእታኞች ይመስሉአችኋልን?'),
  ('780bc9d8-b865-5792-aa8d-70e45042adf9', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '0ca9cc14-ec0b-5b3e-aa6c-497dfb8d26b4', 5, 5, 'አይደለም፤ እላችኋለሁ፤ እናንተም ንስሓ ካልገባችሁ ሁላችሁ እንደ እነርሱ ትጠፋላችሁ።”'),
  ('e51e19f6-de47-5813-a7ce-7da80cb6d1b1', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '4cf372fb-e3a8-5cd3-a6eb-afa7191a1457', 1, 6, 'እንዲህም ብሎ መሰለላቸው፥ “አንድ ሰው በታወቀች በወይኑ ቦታ ውስጥ በለስ ነበረችው፤ ፍሬዋን ሊወስድ ወደ እርስዋ ሄዶ አላገኘም።'),
  ('d366c1d5-8cf5-5859-ac77-688a95959433', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '4cf372fb-e3a8-5cd3-a6eb-afa7191a1457', 2, 7, 'የወይኑን ጠባቂም፦ “የዚችን በለስ ፍሬ ልወስድ ስመላለስ እነሆ፥ ሦስት ዓመት ነው፤ አላገኘሁም፤ እንግዲህስ ምድራችንን እንዳታቦዝን ቍረጣት” አለው።'),
  ('affef447-6b1e-51a1-a0dc-d9d2aee5915c', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '4cf372fb-e3a8-5cd3-a6eb-afa7191a1457', 3, 8, 'እርሱም መልሶ እንዲህ አለው፥ “አቤቱ አፈር ቈፍሬ በሥሯ እስከ አስታቅፋት፥ ፍግም እስከ አፈስባት ድረስ የዘንድሮን እንኳ ተዋት።'),
  ('ce113ee0-998a-5033-a5e1-118068f846e4', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '4cf372fb-e3a8-5cd3-a6eb-afa7191a1457', 4, 9, 'ምናልባት ለከርሞ ታፈራ እንደ ሆነ፥ ያለዚያ ግን እንቈርጣታለን።”'),
  ('b01101aa-7e54-5d5c-a289-223d941e41c4', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 1, 10, 'በሰንበትም በአንድ ምኵራብ ውስጥ አስተማራቸው።'),
  ('199db52f-3569-56d8-af9d-e8c23444afdd', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 2, 11, 'ዐሥራ ስምንት ዓመት ሙሉ ጋኔን ያጐበጣት አንዲት ሴት ነበረች፤ ጐባጣም ነበረች፤ ከቶ ቀጥ ብላ መቆም አትችልም ነበር።'),
  ('b639ff32-b7db-5dd0-a4eb-5aaa1c643b3b', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 3, 12, 'ጌታችን ኢየሱስም አይቶ ራራላት፥ ጠርቶም፥ “ሴትዮ፥ ከደዌሽ ተፈትተሻል” አላት።'),
  ('c02aa075-8c84-5138-a0c9-fa4cba639695', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 4, 13, 'እጁንም በላይዋ ጫነ፤ ያንጊዜም ፈጥና ቀጥ አለች፤ እግዚአብሔርንም አመሰገነችው።'),
  ('e050acc5-35fe-506b-a489-98f21cbf4801', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 5, 14, 'የምኵራቡ ሹምም ጌታ ኢየሱስ በሰንበት ፈውሶአልና፤ እየተቈጣ መልሶ ሕዝቡን እንዲህ አላቸው፥ “ሥራችሁን የምትሠሩባቸው ስድስት ቀኖች ያሉ አይደለምን? ያንጊዜ ኑና ተፈወሱ፤ በሰንበት ቀን ግን አይሆንም።”'),
  ('2eb8450f-4766-5000-a07b-837d087c7d7c', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 6, 15, 'ጌታችን ኢየሱስም መልሶ አላቸው፥ “እናንት ግብዞች፥ እናንተሳ አህያችሁን ወይም በሬአችሁን በሰንበት ቀን ገለባ ከሚበላበት አትፈቱትምን? ውኃ ልታጠጡትስ አትወስዱትምን?'),
  ('6fef85c8-ac79-5126-a4d2-c73cbd566959', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 7, 16, 'ይህቺ የአብርሃም ልጅ እነሆ፥ ሰይጣን ከአሰራት ዐሥራ ስምንት ዓመት ነው፤ እርስዋስ በሰንበት ቀን ከእስራቷ ልትፈታ አይገባምን?”'),
  ('e3e93411-51aa-5014-ab26-190c597e720f', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '165f74f3-904a-51d9-afee-1d53d12c8e61', 8, 17, 'ይህንም ባለ ጊዜ በእርሱ ላይ በጠላትነት የተነሡበት ሁሉ አፈሩ፤ ነገር ግን ሕዝቡ ሁሉ ከእርሱ ስለሚደረገው ድንቅ ነገር ሁሉ ደስ አላቸው።'),
  ('8c525078-5e86-5a76-ac16-c09a9fb89cbc', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', 'eb9272bd-6e01-5b65-a6ce-c276854c5f01', 1, 18, 'በዚያ ቀንም ጌታችን ኢየሱስ እንዲህ አላቸው፥ “መንግሥተ ሰማያት ምን ትመስላለች? በምንስ እመስላታለሁ?'),
  ('da621ea6-9bea-5079-a2a9-c5ae09cace46', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', 'eb9272bd-6e01-5b65-a6ce-c276854c5f01', 2, 19, 'ሰው ወስዶ በእርሻ ውስጥ የዘራት የሰናፍጭ ቅንጣትን ትመስላለች፤ አደገች፤ ታላቅ ዛፍም ሆነች፤ የሰማይ ወፎችም በቅርንጫፎችዋ ውስጥ ተጠለሉ።”'),
  ('7b1f898c-5717-5bb3-adcd-faea6ef9f1c2', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '9916cfea-1626-5e2a-ac0c-298469cdd69a', 1, 20, 'ዳግመኛም እንዲህ አለ፥ “የእግዚአብሔርን መንግሥት በምን እመስላታለሁ?'),
  ('a606784e-ce03-5152-a862-65a28d362216', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '9916cfea-1626-5e2a-ac0c-298469cdd69a', 2, 21, 'ሴት ወስዳ ሦስት መስፈሪያ ዱቄት የለወሰችበትን፥ ሁሉንም እንዲቦካ ያደረገውን እርሾ ትመስላለች”።'),
  ('96f77e2e-220d-50dd-ad06-c9d0edc390ed', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 1, 22, 'በየከተማውና በየመንደሩ እየሄደ፥ በኢየሩሳሌምም እየተመላለሰ ያስተምር ነበር።'),
  ('0c8ed719-f50e-5686-a7b0-6ec4ff6d6898', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 2, 23, 'አንድ ሰውም፥ “አቤቱ የሚድኑ ጥቂቶች ናቸውን?” አለው። እርሱ ግን እንዲህ አላቸው፦'),
  ('e92ee1e1-48a7-5a13-ac7e-033eb4ef4479', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 3, 24, '“ወደ ጠባቡ በር ትገቡ ዘንድ በርቱ፤ እላችኋለሁ፥ ሊገቡ የሚሹ ብዙዎች ናቸው፤ ግን አይችሉም።'),
  ('39eaf29a-a41b-5549-a505-d012ece91ade', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 4, 25, 'ባለቤቱ ተነሥቶ ደጁን ይዘጋልና፤ ያንጊዜ ከደጅ ቆመው፦ ‘አቤቱ፥ አቤቱ፥ ክፈትልን’ እያሉ በር ሊመቱ ይጀምራሉ፤ መልሶም፦ ከወዴት እንደ ሆናችሁ አላውቃችሁም ይላቸዋል።'),
  ('126f5cee-c45c-579b-af3e-b072ac7cbacd', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 5, 26, 'ከዚህም በኋላ፦ በፊትህ በላን፥ ጠጣን፥ በአደባባያችንም አስተማርህ ልትሉ ትጀምራላችሁ።'),
  ('04c3cc77-0288-5394-a7f9-7cc81524c7a7', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 6, 27, 'እርሱም እንዲህ ይላቸዋል፦ እናንተ ከወዴት እንደ ሆናችሁ አላውቃችሁም፤ ዐመፅን የምታደርጉ ሁላችሁ፥ ከእኔ ራቁ፤'),
  ('8f30a547-4f8d-5667-ab40-625ea02e1439', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 7, 28, 'አብርሃምን፥ ይስሐቅንና ያዕቆብን፥ ነቢያትንም ሁሉ በእግዚአብሔር መንግሥት በአያችኋቸው ጊዜ እናንተን ወደ ውጭ ያወጡአችኋል፤ በዚያም ልቅሶና ጥርስ ማፋጨት ይሆናል።'),
  ('1553633d-b906-5a8e-a88b-6b303d6112b3', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 8, 29, 'ከምሥራቅና ከምዕራብ፥ ከሰሜንና ከደቡብ ይመጣሉ፤ በእግዚአብሔርም መንግሥት በማዕድ ይቀመጣሉ፤'),
  ('cacea8f9-e28e-5401-aa7f-af0b0c58645a', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '59360a71-1831-558b-a584-1ec409590b87', 9, 30, 'ኋለኞች ፊተኞች ይሆናሉ፤ ፊተኞችም ኋለኞች ይሆናሉ።”'),
  ('c069b104-9d55-593b-a8f5-9e12fdcead02', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '8e89d26d-3541-5413-ae99-fcc1fb2a86dd', 1, 31, 'በዚያችም ቀን ከፈሪሳውያን ወገን ሰዎች መጥተው፥ “ከዚህ ውጣና ሂድ፤ ሄሮድስ ሊገድልህ ይሻልና” አሉት።'),
  ('d1033ce1-049c-5aa6-a654-7ae0120da005', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '8e89d26d-3541-5413-ae99-fcc1fb2a86dd', 2, 32, 'እርሱም እንዲህ አላቸው፥ “ሂዱና ያችን ቀበሮ እንዲህ በሉአት፤ እነሆ፥ ዛሬና ነገ አጋንንትን አወጣለሁ፤ ሕይወትንም አድላለሁ፤ በሦስተኛውም ቀን እፈጽማለሁ።'),
  ('2490995c-76a0-5eed-a28f-0de0eb291606', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', '8e89d26d-3541-5413-ae99-fcc1fb2a86dd', 3, 33, 'ዛሬና ነገስ አለሁ፤ በሦስተኛው ቀን ግን እሄዳለሁ፤ ነቢይ በኢየሩሳሌም እንጂ በውጭ ሊሞት አይገባውምና።'),
  ('a0f7d85f-faa7-57f4-afc0-ca1d551b9934', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', 'e44cdc5f-4206-5a3c-a86f-cf22476c85e2', 1, 34, '“ነቢያትን የምትገድሊያቸው፥ ወደ አንቺ የተላኩትን ሐዋርያትንም የምትደበድቢያቸው ኢየሩሳሌም፥ ኢየሩሳሌም፥ ዶሮ ጫጩቶችዋን ከክንፍዋ በታች እንደምትሰበስብ ልጆችሽን ልሰበስባቸው ምን ያህል ወደድሁ? ነገር ግን እንቢ አላችሁ።'),
  ('792009c2-82f5-5131-a634-24ae0b21042d', '53c0ec4a-ab53-560c-ac04-f10d3d94fb3d', 'e44cdc5f-4206-5a3c-a86f-cf22476c85e2', 2, 35, 'እነሆ፥ ቤታችሁ ምድረ በዳ ሆኖ ይቀርላችኋል፤ ከዛሬ ወዲያ ‘በእግዚአብሔር ስም የሚመጣ ቡሩክ ነው’ እስክትሉ ድረስ እንደማታዩኝ እነግራችኋለሁ።”'),
  ('95316dd9-79cc-5293-a602-9ccf9e8158b2', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '23347ce5-85c6-56db-a4ac-510ec5c716b8', 1, 1, 'ከዚህም በኋላ ሄዶ ከፈሪሳውያን አለቆች ወደ አንዱ ቤት በሰንበት ቀን እህል ሊበላ ገባ፤ እነርሱ ግን ይጠባበቁት ነበር።'),
  ('1a0cf47b-0896-5b00-a885-35bf1fdab673', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '23347ce5-85c6-56db-a4ac-510ec5c716b8', 2, 2, 'እነሆም፥ ሆዱ የተነፋ አንድ ሰው በፊቱ ነበር።'),
  ('5e9883d1-e12b-5fb5-a9f6-cd2e221ceade', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '23347ce5-85c6-56db-a4ac-510ec5c716b8', 3, 3, 'ጌታችን ኢየሱስም መልሶ ሕግ ዐዋቂዎችንና ፈሪሳውያንን፥ “በሰንበት ድውይ መፈወስ ይገባልን? ወይስ አይገባም?” ብሎ ጠየቃቸው።'),
  ('49f44814-bbd2-573b-a094-58a2d656f234', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '23347ce5-85c6-56db-a4ac-510ec5c716b8', 4, 4, 'እነርሱም ዝም አሉ፤ ይዞም ፈወሰውና ሰደደው።'),
  ('58ffbba3-d1c2-5a8e-af0d-6e9197a50426', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '23347ce5-85c6-56db-a4ac-510ec5c716b8', 5, 5, '“ከእናንተ በሬው ወይም አህያው በጕድጓድ ውስጥ የወደቀበት አንድ ሰው ቢኖር ዕለቱን በሰንበት ቀን ያነሣው የለምን?” አላቸው።'),
  ('64d0b206-ea32-5106-ad3f-7e8c2aab0329', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '23347ce5-85c6-56db-a4ac-510ec5c716b8', 6, 6, 'ስለዚህም ነገር ሊመልሱለት አልተቻላቸውም።'),
  ('f4770b85-f960-5e9c-af8d-61d01ef95b53', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 1, 7, 'በምሳ ላይ ለነበሩትም ወደ ላይኛው ወንበር ሲሽቀዳደሙ ባያቸው ጊዜ ምሳሌ መስሎ አስተማራቸው።'),
  ('2eebf75f-d536-5ef3-aaf1-a384c90b901f', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 2, 8, 'እንዲህም አለ፥ “ለምሳ የጠራህ ሰው ቢኖርና ብትሄድ በላይኛው መቀመጫ አትቀመጥ፤ ምናልባት ከአንተ የሚበልጥ ይመጣ ይሆናል።'),
  ('29222acc-5785-5c78-aa0e-a28cef9d816e', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 3, 9, 'በኋላ ያ አንተንም እርሱንም የጠራ መጥቶ፦ ይህን ቦታ ለእርሱ ተውለት ይልሃልና፤ ያንጊዜም አፍረህ ትመለሳለህ፤ ወደ ዝቅተኛ ቦታም ትወርዳለህ።'),
  ('088473ef-0dde-5be8-ab53-26d1e1afbc5a', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 4, 10, 'የጠራህ ሰው ቢኖርና ብትሄድ ግን የጠራህ በመጣ ጊዜ ወዳጄ ወደ ላይኛው መቀመጫ ውጣ ይልህ ዘንድ በታችኛው መቀመጫ ተቀመጥ፤ ያንጊዜም ከአንተ ጋር ለማዕድ በተቀመጡት ሰዎች ፊት ክብር ይሆንልሃል።'),
  ('45f7d3e4-122c-54a3-a008-ac868e876127', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 5, 11, 'ራሱን ከፍ የሚያደርግ ሁሉ ይዋረዳልና፤ ራሱንም ያሚያዋርድ ከፍ ይላልና።”'),
  ('6f4b7437-7cfa-5bd9-a261-ba40d3ae44d6', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 6, 12, 'የጠራውንም እንዲህ አለው፥ “በበዓል ምሳ ወይም ራት በምታደርግበት ጊዜ ወዳጆችህንና ወንድሞችህን፥ ዘመዶችህንና ጎረቤቶችህን፥ ባለጸጎች ባልንጀሮችህንም አትጥራ፤ እነርሱም ይጠሩሃልና፤ ብድርም ይሆንብሃልና።'),
  ('2ba3b80b-3211-5079-a127-2e6064ec0961', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 7, 13, 'ነገር ግን በበዓል ምሳ በምታደርግበት ጊዜ ድሆችንና ጦም አዳሪዎችን፥ ዕውሮችን፥ እጅና እግርም የሌላቸውን ጥራ።'),
  ('1fe3abbb-f1cd-5eeb-a680-22d984ccf5ec', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 8, 14, 'አንተም ብፁዕ ትሆናለህ፤ የሚከፍሉህ የላቸውምና፤ ነገር ግን ጻድቃን በሚነሡበት ጊዜ ዋጋህን ታገኛለህ።”'),
  ('a995078d-b51e-5d12-a24f-177542fda158', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '9e4d8bd6-9f24-5dbc-aadf-792efc85b214', 9, 15, 'ለምሳ ከተቀመጡትም አንዱ ይህን ሰምቶ፥ “በእግዚአብሔር መንግሥት እህል የሚበላ ብፁዕ ነው” አለው።'),
  ('d25dcfa2-903c-5bac-ab68-8ec8677f4d02', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 1, 16, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “አንድ ሰው ታላቅ ምሳ አደረገና ብዙ ሰዎችን ጠራ።'),
  ('a946c4e8-5dc8-5c21-a416-a417c68f2780', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 2, 17, 'ለምሳ የተጠሩበትም ቀን በደረሰ ጊዜ የታደሙትን ይጠራቸው ዘንድ አገልጋዩን ላከ፤ እርሱም ሄዶ የታደሙትን፦ አሁን ምሳውን ፈጽመን አዘጋጅተናልና ኑ አላቸው።'),
  ('7c2b77eb-025f-5084-a862-c7be106d4e79', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 3, 18, 'ሁሉም በአንድ ቃል ተባብረው እንቢ አሉ፤ የመጀመሪያው፦ እርሻ ገዝችአለሁ፤ ሄጄም ላያት እሻለሁ፤ እንቢ እንደ አላልሁ ቍጠርልኝ በለው አለው።'),
  ('3e186f3a-6d08-5d97-a424-c3b3c30b35e2', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 4, 19, 'ሁለተኛውም፦ አምስት ጥማድ በሬ ገዝቻለሁ፤ ላያቸውና ልፈትናቸው እሄዳለሁ፤ እንደ መጣሁ፥ እንቢ እንደ አላልሁም ቍጠርልኝ በለው አለው።'),
  ('ee1efd80-ddec-5d39-ac2e-90a6e9484ada', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 5, 20, 'ሦስተኛውም፦ ሚስት አግብችአለሁ፤ ስለዚህ ልመጣ አልችልም በለው አለው።'),
  ('2c94a19e-c6ed-5c4f-a871-ab0c752c4831', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 6, 21, 'አገልጋዩም ተመልሶ ለጌታው ይህንኑ ነገረው፤ ያንጊዜም ባለቤቱ ተቈጣ፤ አገልጋዩንም፦ ፈጥነህ ወደ አደባባይና ወደ ከተማው ጐዳና ሂድ፤ ድሆችንና ጦም አዳሪዎችን፥ ዕውሮችንና አንካሶችን ወደዚህ አምጣልኝ አለው።'),
  ('600bfba0-5e88-5235-aaa4-87c2c5996355', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 7, 22, 'ከዚህም በኋላ አገልጋዩ፦ አቤቱ እንደ አዘዝኸኝ አደረግሁ፤ ገናም ቦታ አለ አለው።'),
  ('475afb34-1e58-5f80-aa85-ccf9d0c9af8a', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 8, 23, 'ጌታውም አገልጋዩን፦ ወደ መንገዶችና ወደ ከተማው ቅጥር ፈጥነህ ሂድና ቤቴ እንዲመላ ይገቡ ዘንድ ግድ በላቸው አለው።'),
  ('5c5519f1-922e-5123-afbc-86e6f2854973', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', 'f614cb42-7c4d-5d33-ae72-9cfd10e98f6d', 9, 24, 'ከእነዚህ ከታደሙት ሰዎች አንዱ ስንኳን ማዕዴን እንደማይቀምሳት እነግራችኋለሁ።”'),
  ('c536b6b8-5f9d-56ff-a44a-9747114e96f4', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '816ab04c-0afe-5535-a17d-1d7f6a70605e', 1, 25, 'ከዚህም በኋላ ብዙ ሰዎች አብረውት ሲሄዱ መለስ ብሎ እንዲህ አላቸው።'),
  ('923658b3-9cfb-536b-a499-7704d1f6b53e', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '816ab04c-0afe-5535-a17d-1d7f6a70605e', 2, 26, '“ወደ እኔ የሚመጣ፥ ሊከተለኝም የሚወድ አባቱንና እናቱን፥ ሚስቱንና ልጆቹን፥ ወንድሞቹንና እኅቶቹን፥ የራሱንም ሰውነት እንኳ ቢሆን የማይጠላ ደቀ መዝሙሬ ሊሆን አይችልም።'),
  ('738a96df-3154-5cb1-ac5d-e65e535c8b92', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '816ab04c-0afe-5535-a17d-1d7f6a70605e', 3, 27, 'መስቀሉን ተሸክሞ ሊከተለኝ የማይመጣ ደቀ መዝሙሬ ሊሆን አይችልም።”'),
  ('ea72cb58-bade-5987-ada6-29869b63bc34', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 1, 28, '“ከእናንተም ወገን የግንብ ቤት መሥራት የሚወድ ቢኖር ይጨርሰው ዘንድ የሚችል እንደ ሆነ አስቀድሞ ተቀምጦ የሚፈጅበትን የማያስብ ማን ነው?'),
  ('70567a46-c067-5fea-ad53-70c2dcc3bab7', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 2, 29, 'መሠረቱን ጥሎ መጨረስ ያቃተውም እንደ ሆነ ያዩት ሁሉ፥'),
  ('cfe6a8b1-3963-5512-aa09-2782092f1d01', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 3, 30, '‘ይህ ሰው ሊሠራ ጀመረ፤ ግን መጨረስ ተሳነው’ እያሉ ሊዘብቱበት ይጀምራሉ።'),
  ('7847835b-e42b-5ff0-a90a-a98b90c226e6', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 4, 31, 'ንጉሥም ሌላውን ንጉሥ ይወጋ ዘንድ ሊሄድ ቢወድ ሁለት እልፍ ይዞ ወደ እርሱ የሚመጣውን በአንድ እልፍ ሊዋጋው ይችል እንደ ሆነ አስቀድሞ ተቀምጦ ይመክር የለምን?'),
  ('753f20c3-76c3-5268-acd8-bd965add0669', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 5, 32, 'ያለዚያ ግን፥ ገና በሩቁ ሳለ አማላጆች መልእክተኞችን ልኮ ዕርቅ ይለምናል።'),
  ('5e78e76f-189c-5ac4-a80d-e4c8e7e78620', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 6, 33, 'እንግዲህ እንደዚሁ ከእናንተ ወገን ከሁሉ ያልወጣ፥ የእርሱ ገንዘብ ከሆነውም ሁሉ ያልተለየ ደቀ መዝሙሬ ሊሆን አይችልም።'),
  ('b3fbe016-9873-5501-ad6c-36601b64d099', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 7, 34, '“ጨው መልካም ነው፤ ጨው አልጫ ከሆነ እንግዲህ በምን ያጣፍጡታል?'),
  ('faf71339-1a54-5ec4-a3f0-88ab4465dd8e', '1cea3fb4-5ef2-5711-a8ef-2c9cb5f5da1f', '3d737c64-ed76-58b7-acff-18f9445d2c92', 8, 35, 'ለምድርም ቢሆን፥ ለፍግ መቆለያም ቢሆን አይረባም፤ ነገር ግን ወደ ውጭ ይጥሉታል፤ የሚሰማ ጆሮ ያለው ይስማ።”'),
  ('33266698-4f6b-5f20-a2d9-62e1b171dffd', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 1, 1, 'ቀራጮችና ኀጢኣተኞችም ሊሰሙት ወደ እርሱ ይቀርቡ ነበር።'),
  ('d8d7f58a-ae66-5653-af60-44dd9662fa57', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 2, 2, 'ጻፎችና ፈሪሳውያንም፥ “ይህስ ኀጢኣተኞችን ይቀበላል፤ አብሮአቸውም ይበላል” ብለው አንጐራጐሩ።'),
  ('ed9eff08-97e4-5e80-a7cd-cd8534fcc393', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 3, 3, 'እንዲህም ብሎ መሰለላቸው።'),
  ('3e72adde-0ba5-5fc7-a3fe-b1d6b49eccb9', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 4, 4, '“ከእናንተ መካከል መቶ በጎች ያሉት ሰው ቢኖር፥ ከእነርሱ አንዲቱ ብትጠፋው ዘጠና ዘጠኙን በምድረ በዳ ትቶ እስኪያገኛት ድረስ ይፈልጋት ዘንድ ወደ ጠፋችው ይሄድ የለምን?'),
  ('118ffa5d-0cc9-5a32-a254-d23075a26e85', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 5, 5, 'በአገኛትም ጊዜ ደስ ብሎት በትከሻው ላይ ይሸከማታል።'),
  ('2c36bf6a-ba46-5496-aa97-4756339c3c91', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 6, 6, 'ወደ ቤቱም በገባ ጊዜ፥ ወዳጆቹንና ጎረቤቶቹን ጠርቶ፦ የጠፋችኝን በጌን አግኝቼአታለሁና ከእኔ ጋር ደስ ይበላችሁ ይላቸዋል።'),
  ('3ad4eaf8-70b9-5d64-a20d-d7a4a97d06c4', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '7d405408-fd66-5974-aba9-32341206c9b7', 7, 7, 'እላችኋለሁ፥ እንዲሁ ንስሓ ከማያስፈልጋቸው ከዘጠና ዘጠኙ ጻድቃን ይልቅ ንስሓ ስለሚገባ ስለ አንድ ኀጢኣተኛ በሰማያት ፍጹም ደስታ ይሆናል።'),
  ('1e364b9c-ccfe-5762-add5-bc6e715eef4e', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '0f891dae-a4b5-5a0d-a869-74d748bcc2c2', 1, 8, '“ዐሥር ድሪም ያላት ሴት ብትኖር፥ አንዲቱ ብትጠፋባት መብራት አብርታ በቤቷ ያለውን ሁሉ እየፈነቀለች እስክታገኛት ድረስ ተግታ ትፈልግ የለምን?'),
  ('ae961e3f-d572-55ec-a7b8-4081f90387ee', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '0f891dae-a4b5-5a0d-a869-74d748bcc2c2', 2, 9, 'ያገኘቻት እንደ ሆነም ወዳጆችዋንና ጎረቤቶችዋን ጠርታ፦ ‘የጠፋችኝን ድሪሜን አግኝቼአታለሁና፥ ከእኔ ጋር ደስ ይበላችሁ’ ትላቸዋለች።'),
  ('15358436-9146-52b9-a8c4-2b250719e665', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', '0f891dae-a4b5-5a0d-a869-74d748bcc2c2', 3, 10, 'እላችኋለሁ፥ እንዲሁ ንስሓ ስለሚገባ ስለ አንድ ኀጢኣተኛ በእግዚአብሔር መላእክት ፊት በሰማያት ደስታ ይሆናል።”'),
  ('5b80b609-376b-51f4-a759-5e90c7f2f861', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 1, 11, 'ዳግመኛም እንዲህ አለ፥ “አንድ ሰው ሁለት ልጆች ነበሩት።'),
  ('000bc123-a89a-5aeb-ad56-3b75c78be857', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 2, 12, 'ታናሹ ልጁም አባቱን፦ ‘አባቴ ሆይ፥ ከገንዘብህ የሚደርሰኝን ከፍለህ ስጠኝ’ አለው፤ ገንዘቡንም ከፍሎ ሰጠው።'),
  ('c8e77c98-a76e-540c-a760-6aaf1316a435', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 3, 13, 'ከጥቂት ቀን በኋላም ያ ትንሹ ልጁ ገንዘቡን ሁሉ ሰብስቦ ወደ ሩቅ ሀገር ሄደ፤ በዚያም በመዳራት እየኖረ ገንዘቡን ሁሉ በተነ፤ አጠፋም።'),
  ('010b1855-af28-5f29-ab68-21402b07544a', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 4, 14, 'ገንዘቡንም ሁሉ በጨረሰ ጊዜ፥ በዚያ ሀገር ጽኑ ራብ መጣ፤ እርሱም ተቸገረ።'),
  ('f8ecd0fa-d8ef-5537-ab26-619be24bbe8a', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 5, 15, 'ሄዶም ከዚያ ሀገር ሰዎች ለአንዱ ተቀጠረ፤ እሪያዎችንም ይጠብቅ ዘንድ ወደ እርሻው ቦታ ሰደደው።'),
  ('74be5379-8ada-59eb-a61d-504ae7521b40', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 6, 16, 'እሪያዎች ከሚመገቡት ተረንቃሞም ይጠግብ ዘንድ ተመኘ፤ ግን የሚሰጠው አልነበረም።'),
  ('be67961e-58f4-5d64-aa52-46516085b135', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 7, 17, 'በልቡም እንዲህ ብሎ ዐሰበ፦ እህል የሚተርፋቸው የአባቴ ሠራተኞች ምን ያህል ናቸው? እኔ ግን በዚህ በረኃብ ልሞት ነው።'),
  ('2d72a770-617b-5e14-a66b-0b325d625234', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 8, 18, 'ተነሥቼ ወደ አባቴ ልሂድና እንዲህ ልበለው፦ ‘አባቴ ሆይ፥ በሰማይም፥ በፊትህም በደልሁ።'),
  ('aba78a16-4b50-5271-a1f7-58796fbf763c', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 9, 19, 'እንግዲህ ወዲህስ ልጅህ ልባል አይገባኝም፤ ከአገልጋዮችህ እንደ አንዱ አድርገኝ።’'),
  ('051c356c-a931-5f05-a300-aa8f693228ae', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 10, 20, 'ተነሥቶም ወደ አባቱ ሄደ፤ አባቱም ከሩቅ አየውና ራራለት፤ ሮጦም አንገቱን አቅፎ ሳመው።'),
  ('235c0d1d-5297-56b0-a0e1-40f92b7d709c', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 11, 21, 'ልጁም፦ ‘አባቴ ሆይ፥ በሰማይም፥ በፊትህም በደልሁ፤ ከእንግዲህ ወዲህ ልጅህ ልባል አይገባኝም፤ ነገር ግን ከአገልጋዮችህ እንደ አንዱ አድርገኝ’ አለው።'),
  ('9e8614d5-97fd-56e6-a67a-0a5a432b3547', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 12, 22, 'አባቱም አገልጋዮቹን እንዲህ አላቸው፦ ‘ያማሩ ልብሶችን ቶሎ አምጡና አልብሱት፤ ለጣቱም ቀለበት፥ ለእግሩም ጫማ አድርጉለት፤’'),
  ('6c78c051-0935-53ba-a542-3f250765f1ab', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 13, 23, 'የሰባውን ፍሪዳም አምጡና እረዱ፤ እንብላ፤ ደስም ይበለን።'),
  ('76202420-e57e-5d95-ad64-b9bb1594b59d', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 14, 24, 'ይህ ልጄ ሞቶ ነበር፤ አሁን ግን ሕያው ሆኖአልና፥ ጠፍቶም ነበር፤ ተገኝቶአልና ደስ ይላቸውም ጀመር።'),
  ('d2d2b31c-b852-5a5d-acd9-34ca486b4a04', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 15, 25, '“ታላቁ ልጁም በእርሻ ነበርና ተመልሶ ወደ ቤቱ አጠገብ በደረሰ ጊዜ የዘፈኑንና የመሰንቆውን ድምፅ ሰማ።'),
  ('74d4b6a5-41c8-59a6-ad54-718d5ad9420b', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 16, 26, 'ከአባቱ ብላቴኖችም አንዱን ጠርቶ፦ ‘ይህ የምሰማው ምንድን ነው?’ አለው።'),
  ('e3ed1094-dc7a-51a2-afd4-398344912905', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 17, 27, 'እርሱም፦ ‘ወንድምህ ከሄደበት መጣ፤ አባትህም የሰባውን ፍሪዳ አረደ፤ በሕይወት አግኝቶታልና’ አለው።'),
  ('bfdb86e1-e5c1-54d8-aa29-ec5c5240b6de', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 18, 28, 'ተቈጥቶም ‘አልገባም’ አለ፤ አባቱም ወጥቶ ማለደው።'),
  ('845769eb-16a2-504b-acb3-118159760a24', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 19, 29, 'መልሶም አባቱን እንዲህ አለው፦ ‘እነሆ፥ ይህን ያህል ዓመት ተገዛሁልህ፤ ፈጽሞ ከትእዛዝህ አልወጣሁም፤ ለእኔ ግን ከባልንጀሮች ጋር ደስ እንዲለኝ አንድ የፍየል ጠቦት እንኳ አልሰጠኸኝም።'),
  ('f57764a6-8518-5b48-a10f-7e5ac9585c91', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 20, 30, 'ከአመንዝሮች ጋር ገንዘብህን ሁሉ የጨረሰ ይህ ልጅህ በተመለሰ ጊዜ ግን የሰባውን ፍሪዳ አረድህለት።’'),
  ('4eb39ea2-48c3-59fe-af94-f1b157892f06', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 21, 31, 'አባቱም እንዲህ አለው፦ ‘ልጄ አንተማ እኮ ዘወትር ከእኔ ጋር ነህ፤ የእኔ የሆነው ሁሉ የአንተ ነው።'),
  ('2a7eb16a-2a84-5bf7-a37f-13d499ce605b', '0acda45b-95ef-51b0-aa10-d994c9ce50bd', 'cc5260e4-e4f5-5c9d-aeb8-9ac5343e4642', 22, 32, 'ነገር ግን ይህ ወንድምህ ሞቶ ነበረ፤ ሕያው ሆኖአልና፥ ጠፍቶም ተገኝቶአልና፥ ደስ ሊለን፥ ሐሤትም ልናደርግ ይገባል።”'),
  ('f81745d8-a633-5a94-ae5b-676b5cb56082', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 1, 1, 'ጌታችን ኢየሱስም ለደቀ መዛሙርቱ እንዲህ አላቸው፥ “መጋቢ የነበረው አንድ ባለጸጋ ሰው ነበረ፤ ገንዘቡን ሁሉ እንደሚበትን አድርገው በእርሱ ዘንድ ከሰሱት።'),
  ('f5011dbf-e44d-5bea-a150-233363db19db', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 2, 2, 'ጌታውም ጠርቶ፦ ‘በአንተ ላይ የምሰማው ይህ ነገር ምንድን ነው? እንግዲህ ወዲህ ለእኔ መጋቢ ልትሆን አትችልምና የመጋቢነትህን ሂሳብ አስረክበኝ’ አለው።'),
  ('b8696c43-d86b-5645-a3d1-331141938db8', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 3, 3, 'ያም መጋቢ ዐስቦ እንዲህ አለ፦ ‘ምን ላድርግ? አሁን ጌታዬ ከመጋቢነቴ ይሽረኛል፤ ማረስ አልችልም፤ ለመለመንም አፍራለሁ።'),
  ('f7f6db0f-eddd-5c03-a1d9-6749decd2f00', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 4, 4, 'እንግዲህ ጌታዬ ከምግብናዬ የሻረኝ እንደ ሆነ በቤታቸው ይቀበሉኝ ዘንድ የማደርገውን እኔ ዐውቃለሁ።’'),
  ('b1e21ab8-6d5e-5068-aeb7-48bc138e8202', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 5, 5, 'ለጌታውም ዕዳ የሚከፍሉትን ጠራቸው፤ የመጀመሪያውንም፦ ‘ለጌታዬ የምትከፍለው ዕዳ ምን ያህል ነው?’ አለው፤ እርሱም፦ ‘መቶ ማድጋ ዘይት ነው’ አለው።'),
  ('6e61ed50-f48e-517a-adc0-e24ab702e632', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 6, 6, '‘እነሆ፥ ደብዳቤህ፤ ተቀምጠህ አምሳ ማድጋ አለብኝ ብለህ ፈጥነህ ጻፍ’ አለው።'),
  ('881ea6f7-13ce-5a4f-ab13-918f9a4469c2', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 7, 7, 'ሁለተኛውንም፦ ‘አንተሳ ለጌታዬ የምትከፍለው ዕዳ ምን ያህል ነው?’ አለው፤ እርሱም፦ ‘መቶ ማድጋ ስንዴ ነው’ አለው፤ ‘እነሆ፥ ደብዳቤህ፤ ተቀምጠህ ሰማንያ አለብኝ ብለህ ፈጥነህ ጻፍ’ አለው።'),
  ('7f08c0de-4c56-5667-a7a8-601112d12d9e', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 8, 8, 'ጌታውም ዐመፀኛውን መጋቢ እንደ ብልህ ሰው ስለ ሠራ አመሰገነው፤ ከብርሃን ልጆች ይልቅ የዚህ ዓለም ልጆች በዓለማቸው ይራቀቃሉና።'),
  ('442d3696-7782-5bf1-ab56-0babca1be7e0', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 9, 9, 'እኔም እላችኋለሁ፦ ባለቀባችሁ ጊዜ እነርሱ በዘለዓለም ቤታቸው ይቀበሉአችሁ ዘንድ በዐመፃ ገንዘብ ለእናንተ ወዳጆች አድርጉበት።'),
  ('6cbbb5d6-440f-5ea8-afc1-ca6fb6e548c9', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 10, 10, '“በጥቂት የሚታመን በብዙ ይታመናል፤ በጥቂት የሚያምፅም በብዙም ቢሆን ያምፃል።'),
  ('a61cd6de-be04-5061-af1f-018ac0a9abfe', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 11, 11, 'በዐመፃ ገንዘብ ካልታመናችሁ በእውነተኛው ገንዘብ ማን ያምናችኋል?'),
  ('3b035e7c-7943-5121-a802-edbd93764155', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 12, 12, 'በሌላውስ ገንዘብ ካልታመናችሁ የራሱን ማን ይሰጣችኋል?'),
  ('514547cc-5561-5729-a74b-d6c6e6d081fd', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 13, 13, 'ለሁለት ጌቶች መገዛት የሚችል አገልጋይ የለም፤ ካልሆነም አንዱን ይወድዳል፤ ሁለተኛውንም ይጠላል፤ ወይም ለአንዱ ይታዘዛል፤ ለሁለተኛውም እንቢ ይላል፤ እንዲሁም እናንተ ገንዘብ እየወደዳችሁ ለእግዚአብሔር መገዛት አትችሉም።”'),
  ('a340e8a5-2340-57cf-a98e-18c2c3f86427', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 14, 14, 'ገንዘብን የሚወዱ ፈሪሳውያንም ይህን ሁሉ ነገር ሰምተው ተጠቃቀሱበት።'),
  ('2d84ed1a-0ed1-5e29-a09f-9305e2ca9e8e', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', 'dedd1413-a3b4-5561-a471-2fb53a692ded', 15, 15, 'እርሱም፥ “እናንተስ ለሰው ይምሰል ትመጻደቃላችሁ፤ እግዚአብሔርም ልቡናችሁን ያውቃል፤ በሰው ዘንድ የከበረ በእግዚአብሔር ዘንድ የተናቀ ይሆናልና።'),
  ('21903507-4dd8-5d9c-aec3-288c1b618460', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '4451df38-d969-5549-adda-c819006047c9', 1, 16, '“ኦሪትም ነቢያትም ከጥንት ጀምሮ እስከ ዮሐንስ ድረስ ነበሩ፤ ከዚያ ጊዜ ጀምሮ የእግዚአብሔር መንግሥት ይሰበካል፤ ሁሉም ወደ እርስዋ ይጋፋል።'),
  ('fcac9236-375b-5cdc-a596-02ac0e1767fc', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '4451df38-d969-5549-adda-c819006047c9', 2, 17, 'ነገር ግን ከኦሪት አንዲት ቃል ከምትወድቅ ሰማይና ምድር ቢያልፍ ይቀላል።'),
  ('a9589aaf-76aa-50a2-adea-43c867844183', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '4451df38-d969-5549-adda-c819006047c9', 3, 18, '“ሚስቱን ፈትቶ ሌላዪቱን የሚያገባ ሁሉ ያመነዝራል፤ ባልዋ የፈታትንም የሚያገባ ያመነዝራል።'),
  ('c570e8c3-eec9-58e7-a258-ee5da78911c6', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 1, 19, '“አንድ ባለጸጋ ሰው ነበረ፤ ቀይ ሐርና ነጭ ሐር፥ እጅግም ቀጭን ልብስ ይለብስ ነበር፤ ዘወትርም ተድላና ደስታ ያደርግ ነበር።'),
  ('a7acdadd-c549-5f52-a324-d5da45af351c', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 2, 20, 'በቍስል ሕመም ተይዞ በባለጸጋው ደጅ የወደቀ አልዓዛር የሚባል አንድ ድሃም ነበረ።'),
  ('964b7135-ce59-573a-a7d4-2bf7a33f1190', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 3, 21, 'ከባለጸጋው ማዕድ የሚወድቀውንም ፍርፋሪ ሊመገብ ይመኝ ነበር፤ ውሾችም እየመጡ ቍስሉን ይልሱት ነበር።'),
  ('002246d5-4c1d-5a15-a3e7-070e15bbf01d', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 4, 22, 'ከዚህም በኋላ ድሃው ሞተ፤ መላእክትም ወደ አብርሃም አጠገብ ወሰዱት፤ ባለጸጋውም ደግሞ ሞተ፤ ተቀበረም፤'),
  ('df81b4b8-f66d-58b8-a261-41d6be43e2c3', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 5, 23, 'በሲኦልም በሥቃይ ሳለ ዐይኖቹን አንሥቶ አብርሃምን ከሩቅ አየው፤ አልዓዛርንም በአጠገቡ ተቀምጦ አየው።'),
  ('da389faf-4835-553b-af50-45757904353c', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 6, 24, '‘አባት አብርሃም ሆይ፥ እዘንልኝ፤ በዚች እሳት እጅግ ተሠቃይቻለሁና፥ ጣቱን ከውኃ ነክሮ ምላሴን ያቀዘቅዝልኝ ዘንድ አልዓዛርን ላከው’ ብሎ ተጣራ።'),
  ('027bc3af-a4e4-56e1-a1ff-a92e7ff1d4f8', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 7, 25, 'አብርሃም ግን እንዲህ አለው፦ ‘ልጄ ሆይ፥ አንተ በሕይወትህ ተድላና ደስታ እንዳደረግህ፥ አልዓዛርም እንዲሁ ሁልጊዜ በችጋር እንደ ነበረ ዐስብ፤ አሁን ግን እንዲሁ እርሱ በዚህ ፈጽሞ ተድላና ደስታ ያደርጋል፤ አንተ ግን መከራ ትቀበላለህ።'),
  ('08342481-adf1-533b-a47d-44ee8226ab74', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 8, 26, 'ከዚህም ሁሉ ጋር ከዚህ ወደ እናንተ ማለፍ የሚሹ እንዳይችሉ፥ ከእናንተ ወገን የሆኑትም ወደ እኛ እንዳይሻገሩ በእኛና በእናንተ መካከል ታላቅ ገደል አለ’'),
  ('79099f06-e61d-552a-a66c-4e118e0274e1', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 9, 27, 'እርሱም እንዲህ አለው፦ ‘አባት አብርሃም ሆይ፥ አልዓዛርን ወደ አባቴ ቤት እንድትልከው እለምንሃለሁ።'),
  ('450c6008-e9e6-59e6-a6b3-888ae6d66466', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 10, 28, 'አምስት ወንድሞች ስለ አሉኝ ይንገራቸው፤ እነርሱም ደግሞ ወደዚች የሥቃይ ቦታ እንዳይመጡ ይስሙ።’'),
  ('93a2badc-1d91-58ca-aece-1f6cc672ca74', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 11, 29, 'አብርሃምም፦ ‘ሙሴና ነቢያት አሉአቸው፤ እነርሱን ይስሙ’ አለው።'),
  ('589f2f68-4eae-5ef9-aac7-5b709c3c7278', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 12, 30, 'እርሱም፦ ‘የለም፤ አባት አብርሃም ሆይ፥ ከሙታን አንዱ ወደ እነርሱ ካልሄደና ካልነገራቸው ንስሓ አይገቡም’ አለው።'),
  ('9e7a8a2a-2ebc-5eb8-a0c3-ef705a5e6365', 'ce2047c6-d287-5c3a-acd4-0e831a922fbd', '03a33820-ad40-5572-a24f-66b1849dea4c', 13, 31, 'አብርሃምም፦ ‘ሙሴንና ነቢያትን ካልሰሙማ ከሙታን ተለይቶ የተነሣ ቢኖርም እንኳ አይሰሙትም፤ አያምኑትምም’ አለው።”'),
  ('ef93c854-f2ed-5c20-a722-2e3d3f71da70', '285de62d-08ba-58ed-a91b-196c863a619f', '25f722d1-cdc7-53a7-a96e-46abf7c9d458', 1, 1, 'ጌታችን ኢየሱስም ለደቀ መዛሙርቱ እንዲህ አላቸው፥ “መሰናክል ግድ ይመጣል፤ ነገር ግን መሰናክልን ለሚያመጣት ሰው ወዮለት።'),
  ('144c5150-3d50-57df-aefb-f7b57d746273', '285de62d-08ba-58ed-a91b-196c863a619f', '25f722d1-cdc7-53a7-a96e-46abf7c9d458', 2, 2, 'ከእነዚህ ከታናናሾቹ አንዱን ከሚያሰናክል ይልቅ አህያ የሚፈጭበት የወፍጮ ድንጋይ በአንገቱ ታስሮ ወደ ጥልቅ ባሕር ቢሰጥም በተሻለው ነበር።'),
  ('c472d518-7cad-5f2e-abd0-5f501f3981a8', '285de62d-08ba-58ed-a91b-196c863a619f', '25f722d1-cdc7-53a7-a96e-46abf7c9d458', 3, 3, 'ለራሳችሁ ተጠንቀቁ፤ ወንድምህ አንተን ቢበድል ብቻህን ምከረው፤ ቢጸጸት ግን ይቅር በለው።'),
  ('63ce206c-ff86-5c53-a52a-22f41120d5d4', '285de62d-08ba-58ed-a91b-196c863a619f', '25f722d1-cdc7-53a7-a96e-46abf7c9d458', 4, 4, 'በየቀኑ ሰባት ጊዜ ቢበድልም ሰባት ጊዜ ከተጸጸተ ይቅር በለው።”'),
  ('adb52be5-dbcc-58ae-acfd-eea355bd4a48', '285de62d-08ba-58ed-a91b-196c863a619f', '6c43b0dc-eb9a-5133-aefc-e51e56dfa3d2', 1, 5, 'ሐዋርያትም ጌታን፥ “እምነትን ጨምርልን” አሉት።'),
  ('3d15188e-841b-5dea-a852-f37e288209db', '285de62d-08ba-58ed-a91b-196c863a619f', '6c43b0dc-eb9a-5133-aefc-e51e56dfa3d2', 2, 6, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “የሰናፍጭ ቅንጣት ታህል እምነት ብትኖራችሁ ይህችን ሾላ ከሥርሽ ተነቅለሽ በባሕር ውስጥ ተተከዪ ብትሉአት ትታዘዝላችኋለች።”'),
  ('28fdeabe-a6fb-56cb-ac9d-b1b03616bcea', '285de62d-08ba-58ed-a91b-196c863a619f', '9b13de82-29b0-5df1-a61c-49fbd7660a16', 1, 7, '“አራሽ ወይም ከብት ጠባቂ አገልጋይ ያለው ከእናንተ ማን ነው? ከእርሻው በተመለሰ ጊዜ ጌታው ና፥ ፈጥነህ ወደዚህ ውጣና ከእኔ ጋር በማዕድ ተቀመጥ ይለዋልን?'),
  ('9de25259-3579-5ac4-a6f3-689934356fcf', '285de62d-08ba-58ed-a91b-196c863a619f', '9b13de82-29b0-5df1-a61c-49fbd7660a16', 2, 8, 'እራቴን አዘጋጅልኝ፥ እስክበላና እስክጠጣ ድረስም ታጥቀህ አሳልፍልኝ፤ ከዚህም በኋላ አንተ ብላ፥ ጠጣም ይለው የለምን?'),
  ('30ca9883-439f-5faa-ac17-50c331c567cc', '285de62d-08ba-58ed-a91b-196c863a619f', '9b13de82-29b0-5df1-a61c-49fbd7660a16', 3, 9, 'እንግዲህ ጌታው ያዘዘውን ሥራውን ቢሠራ ለዚያ አገልጋይ ምስጋና አለውን?'),
  ('43a169a6-2ea1-55bc-a296-8266b4bf65b7', '285de62d-08ba-58ed-a91b-196c863a619f', '9b13de82-29b0-5df1-a61c-49fbd7660a16', 4, 10, 'እንዲሁ እናንተም ያዘዝኋችሁን ሁሉ አድርጋችሁ ‘እኛ ሥራ ፈቶች አገልጋዮች ነን፤ ለመሥራትም የሚገባንን ሠራን’ በሉ።”'),
  ('aa97b301-cb3f-5077-a800-8aba2d6ecbb4', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 1, 11, 'ከዚህ በኋላ ወደ ኢየሩሳሌም ሲሄድ በሰማርያና በገሊላ መካከል ዐለፈ።'),
  ('1bdbff3d-46aa-55dc-a1cc-8d4dee5f9aea', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 2, 12, 'ወደ አንዲት መንደርም ሲገባ ለምጽ የያዛቸው ዐሥር ሰዎች ተቀበሉትና ራቅ ብለው ቆሙ።'),
  ('008d7588-67ac-5230-aa5b-16692714e3da', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 3, 13, 'ድምጻቸውንም ከፍ አድርገው፥ “ጌታ ኢየሱስ ሆይ፥ እዘንልን” አሉ።'),
  ('5fc3927d-0079-5240-a0d6-edf12474e57e', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 4, 14, 'ባያቸውም ጊዜ፥ “ወደ ካህን ሂዱና ራሳችሁን አስመርምሩ” አላቸው፤ ሲሄዱም ነጹ።'),
  ('9a6b981b-479e-56bf-a1a9-7bc95380cf79', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 5, 15, 'ከእነርሱም አንዱ እንደ ነጻ ባየ ጊዜ፥ በታላቅ ቃል እያመሰገነ ተመለሰ።'),
  ('31e29f29-31f7-51d9-a972-4d8bc897b801', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 6, 16, 'በግንባሩም ወድቆ ከጌታችን ከኢየሱስ እግር በታች ሰገደና አመሰገነው፤ ሰውየውም ሳምራዊ ነበር።'),
  ('0c2d3c98-9d16-5fc2-a992-c575c578c1d4', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 7, 17, 'ጌታችን ኢየሱስም መልሶ እንዲህ አለ፤ “የነጹ ዐሥር አልነበሩምን? እንግዲህ ዘጠኙ የት አሉ?'),
  ('68ba644b-a608-5b11-ab46-c1839bd9812b', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 8, 18, 'ወገኑ ሌላ ከሆነ ከዚህ ሰው በቀር ለእነዚያ ተመልሶ እግዚአብሔርን ማመስገን ተሳናቸውን?”'),
  ('dd12d894-fb4d-599f-a79b-1704d01e9f69', '285de62d-08ba-58ed-a91b-196c863a619f', '849625df-4116-5931-a82b-04482c9bd6c7', 9, 19, 'እርሱንም፥ “ተነሥና ሂድ፤ እምነትህ አዳነችህ” አለው።'),
  ('96d2bff6-f1b2-5f05-a5ea-9eb068936486', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 1, 20, 'ፈሪሳውያንም “የእግዚአብሔር መንግሥት መቼ ትመጣለች?” ብለው ጠየቁት፤ እርሱም መልሶ እንዲህ አላቸው፥ “የእግዚአብሔር መንግሥት በመጠባበቅ አትመጣም።'),
  ('f031c9c6-758d-58bc-a1c2-d8872e46ffa2', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 2, 21, 'እንኋት፥ በዚህ ናት፤ ወይም እነኋት፥ በዚያ ናት አይሉአትም፤ የእግዚአብሔር መንግሥትስ እነኋት፥ በመካከላችሁ ናት።”'),
  ('5d8702d5-de6c-55d4-a4ef-6e8765fa27c6', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 3, 22, 'ደቀ መዛሙርቱንም እንዲህ አላቸው፥ “ከሰው ልጆች ቀኖች አንዲቱን ታዩ ዘንድ የምትመኙበት ወራት ይመጣል፤ ነገር ግን አታዩአትም።'),
  ('57edf8b8-ca04-5da8-a2da-eab505f17770', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 4, 23, 'እነሆ፥ በዚህ ነው፥ ወይም እነሆ፥ በዚያ ነው ቢሉአችሁ አትውጡ፤ አትከተሉአቸውም።'),
  ('3193c1d4-99db-5d34-a816-93bc8689f46e', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 5, 24, 'መብረቅ ብልጭ ብሎ ከሰማይ ዳርቻ እስከ ሰማይ ዳርቻ እንደሚያበራ የሰው ልጅ አመጣጡ እንዲሁ ነውና።'),
  ('02be1c11-0169-50a4-a5f6-abcd2e24b75d', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 6, 25, 'ነገር ግን ከዚህ ሁሉ አስቀድሞ ብዙ መከራን ይቀበላል፤ ይህች ትውልድም ትንቀዋለች፤ ትፈታተነዋለችም።'),
  ('f0db9e50-b626-5138-a49c-71bc5fd50232', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 7, 26, 'በኖኅ ዘመን እንደ ሆነው የሰው ልጅ በሚመጣበት ጊዜ እንዲሁ ይሆናል።'),
  ('d49dd365-8c90-5862-a6a7-ecd1a2d82fd9', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 8, 27, 'ኖኅ ወደ መርከብ እስከ ገባበት ቀን ድረስ ሲበሉና ሲጠጡ፥ ሲያገቡና ሲጋቡ ነበረ፤ የጥፋት ውኃም መጥቶ ሁሉን አንድ አድርጎ አጠፋ።'),
  ('ac75502a-bdf5-572b-a854-93b884e746ae', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 9, 28, 'በሎጥ ዘመንም ሲበሉና ሲጠጡ፥ ቤት ሲሠሩና ተክል ሲተክሉ፥ ሲሸጡና ሲገዙ ነበረ።'),
  ('8c2a631a-d2ab-530e-a421-65cc2f3267bb', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 10, 29, 'ሎጥ ከሰዶም በወጣበት ቀን ግን ከሰማይ እሳትና ዲን ዘነመ፤ ሁሉንም አጠፋ።'),
  ('5a077b61-f7f6-5a6a-ab02-2515f2ff8625', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 11, 30, 'የሰው ልጅም በሚመጣበት ቀን እንዲሁ ይሆናል፤ አይታወቅምም።'),
  ('0b6a213d-07fa-5342-a7b2-209b2f19b5e2', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 12, 31, 'ያንጊዜም በሰገነት ላይ ያለ፥ ገንዘቡም በምድር ቤት የሆነበት ሰው ለመውሰድ አይውረድ፤ በዱር ያለም ወደ ኋላው አይመለስ።'),
  ('a07f72f6-6d4f-537b-a27b-b58c869368f7', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 13, 32, 'የሎጥን ሚስት ዐስቡአት።'),
  ('c28ac853-38b9-5852-a16b-9e220d93a450', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 14, 33, 'ነፍሱን ሊያድናት የሚወድ ይጣላት፤ ስለ እኔ ነፍሱን የሚጥላትም ያድናታል።'),
  ('cdd3db78-4626-571c-ac8e-f7aa9b653061', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 15, 34, 'እላችኋለሁ፦ ሁለት ሰዎች በአንድ አልጋ ይተኛሉ፤ አንዱን ይወስዳሉ፤ ሁለተኛውንም ይተዋሉ።'),
  ('cc0bccd9-905f-5447-ab96-0cf63f6a52a3', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 16, 35, 'ሁለት ሴቶችም በአንድ ወፍጮ ይፈጫሉ፤ አንዲቱን ይወስዳሉ፤ ሁለተኛዪቱንም ይተዋሉ።'),
  ('0a7ce9cd-af59-5bb7-a021-20b967960bc9', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 17, 36, 'ሁለት ሰዎች በአንድ እርሻ ላይ ይኖራሉ፤ አንዱን ይወስዳሉ፤ ሁለተኛውንም ይተዋሉ።”'),
  ('743ad658-dc4f-5824-aa4b-a7cca7ade9c4', '285de62d-08ba-58ed-a91b-196c863a619f', '51a9c43b-638c-5a96-a841-2ac806bb7321', 18, 37, 'እነርሱም መልሰው፥ “አቤቱ፥ ወዴት ነው?” አሉት፤ እርሱም፥ “ገደላ በአለበት አሞሮች በዚያ ይሰበሰባሉ” አላቸው።'),
  ('6a044579-ed93-58a1-a2fe-c49cb49afce6', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 1, 1, 'ዘወትር እንዲጸልዩ፥ እንዳይሰለቹም በምሳሌ ነገራቸው።'),
  ('3d52fb44-a828-51d2-acd8-69359cfbb8dd', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 2, 2, 'እንዲህም አላቸው፥ “በአንዲት ከተማ እግዚአብሔርን የማይፈራ፥ ሰውንም የማያፍር አንድ ዳኛ ነበር።'),
  ('c5dcd1ee-38cf-5a68-a9eb-b54420c05b01', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 3, 3, 'በዚያችም ከተማ አንዲት መበለት ነበረች፤ ዕለት ዕለትም ወደ እርሱ እየመጣች ከባለጋራዬ ፍረድልኝ ትለው ነበር።'),
  ('2b43b413-a2bf-5210-acd7-5a70505630e3', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 4, 4, 'እንቢ ብሎም አዘገያት። ከዚህም በኋላ በልቡ ዐስቦ እንዲህ አለ፦ ‘ምንም እግዚአብሔርን ባልፈራ፥ ሰውንም ባላፍር'),
  ('ca22ff03-aae6-516e-a31c-e24b4a6331a2', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 5, 5, 'ይህቺ ሴት እንዳትዘበዝበኝ፥ ዘወትርም እየመጣች እንዳታታክተኝ እፈርድላታለሁ’።”'),
  ('ddb500b3-c368-5295-a575-cc8448cde31a', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 6, 6, 'ጌታችንም እንዲህ አላቸው፥ “ዐመፀኛው ዳኛ ያለውን ስሙ።'),
  ('329af147-a93f-5b79-a2c1-b925292d76c0', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 7, 7, 'እንግዲህ እግዚአብሔር በመዓልትና በሌሊት ወደ እርሱ ለሚጮኹ ለወዳጆቹ አይፈርድምን? ወይስ ቸል ይላቸዋልን?'),
  ('57335933-8b28-5c82-ab54-db26fd2df7de', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '157efb16-e17b-5eab-a877-22270e67c944', 8, 8, 'እላችኋለሁ ፈጥኖ ይፈርድላቸዋል፤ ነገር ግን የሰው ልጅ በመጣ ጊዜ በምድር ላይ እምነትን ያገኝ ይሆን?”'),
  ('f1a8a817-303d-551d-a53b-3b018a6fd922', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '7259c1bf-39ba-585e-ab72-bbf6d9cefca5', 1, 9, 'ራሳቸውን ለሚያመጻድቁና ባልንጀራቸውን ለሚንቁ እንዲህ ብሎ መሰለላቸው።'),
  ('4702c2fb-bf74-5ad4-a70c-bd96c74f05da', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '7259c1bf-39ba-585e-ab72-bbf6d9cefca5', 2, 10, '“ሁለት ሰዎች ሊጸልዩ ወደ ቤተ መቅደስ ወጡ፤ አንዱ ፈሪሳዊ፥ ሁለተኛውም ቀራጭ ነበር።'),
  ('973e8cc2-56cc-59ae-a5f6-416d22d37c66', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '7259c1bf-39ba-585e-ab72-bbf6d9cefca5', 3, 11, 'ፈሪሳዊውም ቆመና እንዲህ ብሎ ጸለየ፦ ‘አቤቱ እንደ ሌሎች ሰዎች፥ እንደ ቀማኞችና እንደ ዐመፀኞች፥ እንደ አመንዝሮችም፥ ወይም እንደዚህ ቀራጭ ያላደረግኸኝ አመሰግንሃለሁ።'),
  ('bb4cf09f-c4cd-5f0f-a6ce-7b94a87a2633', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '7259c1bf-39ba-585e-ab72-bbf6d9cefca5', 4, 12, 'እኔ በየሳምንቱ ሁለት ቀን እጾማለሁ፤ ከማገኘውም ሁሉ ከዐሥር አንድ እሰጣለሁ።’'),
  ('fcce1aa6-3e66-5054-a695-4da915947ee9', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '7259c1bf-39ba-585e-ab72-bbf6d9cefca5', 5, 13, 'ቀራጩ ግን ራቅ ብሎ ቆመ፤ ዐይኖቹንም ወደ ላይ ወደ ሰማይ ሊያነሣ አልወደደም፤ ደረቱንም እየመታ፦ ‘አቤቱ፥ እኔን ኀጢኣተኛውን ይቅር በለኝ’ አለ።'),
  ('a4695f99-f858-510f-a889-8857d5a83f4c', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '7259c1bf-39ba-585e-ab72-bbf6d9cefca5', 6, 14, 'እላችኋለሁ፥ ከዚያ ይልቅ ይህ ጻድቅ ሆኖ ወደ ቤቱ ተመለሰ፤ ራሱን ከፍ ከፍ የሚያደርግ ሁሉ ይዋረዳልና፤ ራሱንም የሚያዋርድ ይከብራልና።”'),
  ('ab84cffd-3bf3-5bc3-ae2d-582e03bd814f', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '97feb190-4563-5ea6-a6a4-9a36bc073e79', 1, 15, 'ይባርካቸውም ዘንድ ሕፃናትን ወደ እርሱ አመጡአቸው፤ ደቀ መዛሙርቱም አይተው ገሠጹአቸው።'),
  ('0b5267a4-3b5b-5df7-a0ab-567ceeaa7980', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '97feb190-4563-5ea6-a6a4-9a36bc073e79', 2, 16, 'ጌታችን ኢየሱስም ጠራቸው፤ እንዲህም አላቸው፥ “ሕፃናትን ወደ እኔ ይመጡ ዘንድ ተዉአቸው፥ አትከልክሉአቸውም፤ የእግዚአብሔር መንግሥት እንደ እነዚህ ላሉት ናትና።'),
  ('3e92ab7a-ed65-536d-a2b0-d2ff1db3d22b', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '97feb190-4563-5ea6-a6a4-9a36bc073e79', 3, 17, 'እውነት እላችኋለሁ፥ የእግዚአብሔርን መንግሥት እንደ ሕፃናት ያልተቀበላት አይገባባትም።”'),
  ('3926f7c7-250a-5a2a-a82a-11b31fe5c2c6', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 1, 18, 'አንድ አለቃም፥ “ቸር መምህር፥ ምን ሥራ ሠርቼ የዘለዓለም ሕይወትን እወርሳለሁ?” አለው።'),
  ('81947389-8a8d-5465-a2b8-407778b449d9', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 2, 19, 'ጌታችን ኢየሱስም እንዲህ አለው፥ “ለምን ቸር ትለኛለህ? ከአንዱ ከእግዚአብሔር በቀር ቸር የለም።'),
  ('51196533-4eb3-5464-a19b-4ff81adb0be4', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 3, 20, 'ትእዛዛቱን አንተ ራስህ ታውቃለህ፤ ‘አትግደል፤ አታመንዝር፤ አትስረቅ፤ በሐሰት አትመስክር፤ አባትህንና እናትህንም አክብር።’'),
  ('854b4673-53bf-5c81-ae42-712581eb37d1', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 4, 21, 'እርሱም፦ ‘ይህንስ ሁሉ ከልጅነቴ ጀምሬ እስከ ዛሬ ጠብቄአለሁ’።” አለው።'),
  ('1565072e-feeb-5430-a199-150d8adb9388', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 5, 22, 'ጌታችን ኢየሱስም ይህን ሰምቶ እንዲህ አለው፥ “አንዲት ቀርታሃለች፤ ሂድና ያለህን ሁሉ ሸጠህ ለነዳያን ስጥ፤ በሰማይም መዝገብ ታገኛለህ፤ መጥተህም ተከተለኝ።”'),
  ('7f9ad840-49ad-53a9-a30f-48d897e25574', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 6, 23, 'እርሱ ግን ይህን ሰምቶ በጣም አዘነ፤ እርሱ እጅግ ባለጸጋ ነበርና።'),
  ('9e7f7fba-24be-5e15-a65a-9796f516dee8', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 7, 24, 'ጌታችን ኢየሱስም እጅግ ሲያዝን አይቶ እንዲህ አለ፥ “ገንዘብ ላላቸው ሰዎች ወደ እግዚአብሔር መንግሥት መግባት እንዴት ጭንቅ ነው!'),
  ('6a31e28a-5694-5e92-ab1c-cff130ddbf87', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 8, 25, 'ባለጸጋ ወደ እግዚአብሔር መንግሥት ከሚገባ ይልቅ ግመል በመርፌ ቀዳዳ ሊያልፍ ይቀላል።”'),
  ('3fd13780-c506-5928-a97c-859e74357bf1', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 9, 26, 'የሰሙትም፥ “እንግዲህ ማን ሊድን ይችላል?” አሉ።')
